INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('bocconi-university', '[11]', 8, 'matched', '["data/raw/factsheets/Bocconi/2023- 2024/Bocconi Fact Sheet 2023-2024.pdf","data/raw/factsheets/Bocconi/2024-2025/Bocconi Fact Sheet 2024-2025 Online website version (2).pdf","data/raw/factsheets/Bocconi/2024-2025/Bocconi Fact Sheet 2024-2025 Printable version (3).pdf","data/raw/factsheets/Bocconi/2025-2026/AY2526_Factsheet International Student Desk Exchange_Pieghevole.pdf"]', '[]', 'Bocconi University', 'Bocconi', 'Italy', NULL, 'Milan', 'Europe', 'active', '["UG"]', 'Requires nomination by a home partner university; undergraduate exchange students select 30xxx undergraduate-level courses.', 'Business and Economics', '["BUS"]', '["Business","Economics"]', NULL, NULL, '["English","Italian"]', 'substantial', 'B2 level in English (or Italian for Italian-taught courses) expected and verified through home-university nomination; no central TOEFL/IELTS test score mandate published on the incoming exchange portal. RHET 1020 exemption not stated.', 'Not required for English-taught courses; B2 Italian expected if selecting Italian-taught courses. Optional pre-term Italian crash course offered (Aug 25–Sep 5 Fall; Jan 25–Feb 6 Spring).', '["Fall","Spring"]', '2026-09-02 to 2026-12-22 (early exchange exams) / 2027-02-02 (regular exam sessions)', '2027-02-03 to 2027-07-10 (classes end 2027-05-15; earliest departure 2027-06-01)', NULL, NULL, 'auc_exchange_waiver', 'EUR', 1700, 1800, 9670.5, 'partial', 'No mandatory Bocconi enrollment health insurance fee; non-EU students require valid international health insurance for visa/Permesso di Soggiorno (e.g., WAI Italy ~EUR 91/6 months) and pay ~EUR 100.46 + EUR 16 stamp for Permesso di Soggiorno.', 'assisted', 'Limited on-campus residence rooms (EUR 4,000–4,800/semester single) allocated on a first-come, first-served basis; Bocconi provides guidance for private rentals (double EUR 500–750/mo, single EUR 600–1,100/mo, entire flat EUR 800–1,800/mo).', NULL, NULL, 'Non-EU incoming exchange students require an Italian Type D Student Visa prior to arrival via Universitaly / local Italian Consulate and must apply for a Permesso di Soggiorno within 8 working days of arrival (~EUR 100.46 + EUR 16 revenue stamp).', 'http://www.unibocconi.eu/', 'https://www.unibocconi.it/en/for-international-students/incoming-exchange-students', 'https://didattica.unibocconi.eu/ts/tsn_ord_ir.php', NULL, 'ECTS equivalent (1 Bocconi credit = ~25h total workload including ~8 lecture hours); incoming exchange students take 1 to 5 courses per semester.', 'Undergraduate exchange students must select undergraduate-level courses (coded in the 30xxx series); graduate and integrated Law offerings are restricted to matching degree levels.', '["Most recent university academic transcript","CV / Resume","Headshot photo (for Bocconi ID card)","Passport personal data page (or EU national ID card)","Disability certificate from home university (optional, only if requesting accommodations)"]', 'Lecture and written/oral exam assessment with mid-term sessions and an early December exam session option for Fall exchange students.', NULL, 'urban', NULL, 'International Student Desk (ISD) online application portal, mandatory Welcome Check-in days, optional pre-term Italian crash course, visa/Permesso guidance, and housing info.', 'Home partner coordinator submits online nomination first; Spring 2027 student online application window ran Sep 30 – Oct 22, 2026 (15:00 CET). Fall deadlines communicated per partner nomination cycle.', '{}', '{"academic_style":{"notes":null,"source_ref":"https://www.unibocconi.it/en/for-international-students/incoming-exchange-students","source_type":"official_web","status":"partial","value":"Lecture and written/oral exam assessment with mid-term sessions and an early December exam session option for Fall exchange students."},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:11","source_type":"excel_list","status":"verified","value":"Business and Economics"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:11","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:11","source_type":"excel_list","status":"verified","value":["UG"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:11","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":"Urban city campus located in Milan.","source_ref":"https://www.unibocconi.it/en/about-bocconi/campus-and-services/buildings-and-classrooms","source_type":"official_web","status":"verified","value":"urban"},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:11","source_type":"excel_list","status":"verified","value":"Milan"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:11","source_type":"excel_list","status":"verified","value":"Italy"},"course_catalog_url":{"notes":null,"source_ref":"https://didattica.unibocconi.eu/ts/tsn_ord_ir.php","source_type":"official_web","status":"verified","value":"https://didattica.unibocconi.eu/ts/tsn_ord_ir.php"},"course_restrictions_note":{"notes":null,"source_ref":"https://www.unibocconi.it/en/for-international-students/incoming-exchange-students","source_type":"official_web","status":"verified","value":"Undergraduate exchange students must select undergraduate-level courses (coded in the 30xxx series); graduate and integrated Law offerings are restricted to matching degree levels."},"credit_system_and_load":{"notes":null,"source_ref":"https://www.unibocconi.it/en/for-international-students/incoming-exchange-students","source_type":"official_web","status":"verified","value":"ECTS equivalent (1 Bocconi credit = ~25h total workload including ~8 lecture hours); incoming exchange students take 1 to 5 courses per semester."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Excel agreement scope is ''Business and Economics''; at AUC, Business and the Mohamed Shafik Gabr Department of Economics are both housed in the Onsi Sawiris School of Business (BUS) per https://www.aucegypt.edu/academics/school-business.","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:11","source_type":"excel_list","status":"verified","value":["BUS"]},"eligible_majors":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:11","source_type":"excel_list","status":"verified","value":["Business","Economics"]},"english_course_availability":{"notes":"Wide array of undergraduate and graduate courses taught in English alongside Italian offerings in the official exchange course table.","source_ref":"https://didattica.unibocconi.eu/ts/tsn_ord_ir.php","source_type":"official_web","status":"partial","value":"substantial"},"english_course_list_url":{"notes":"Course table at https://didattica.unibocconi.eu/ts/tsn_ord_ir.php requires interactive language/level filtering rather than a static English-only URL.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":null,"source_ref":"https://www.unibocconi.it/en/for-international-students/incoming-exchange-students","source_type":"official_web","status":"partial","value":"B2 level in English (or Italian for Italian-taught courses) expected and verified through home-university nomination; no central TOEFL/IELTS test score mandate published on the incoming exchange portal. RHET 1020 exemption not stated."},"est_monthly_living_local":{"notes":"AY 2026-2027 Cost of Attendance monthly living budget estimate (EUR 1,700–1,800/month, contextually used e.g. for US Direct Loans planning). Incoming-exchange specific page (https://www.unibocconi.it/en/foe/incoming-exchange-students/estimated-costs) and AY25-26 factsheet (data/raw/factsheets/Bocconi/2025-2026/AY2526_Factsheet International Student Desk Exchange_Pieghevole.pdf#page=2) itemize private double room EUR 500–750/mo, single room EUR 600–1,100/mo, flat EUR 800–1,800/mo, dorm EUR 4,000–4,800/sem, canteen ~EUR 5/meal, metro pass EUR 22/mo (<27 yrs).","source_ref":"https://www.unibocconi.it/en/admissions/cost-aid/cost-attendance-ay-2026-2027","source_type":"official_web","status":"partial","value":{"currency":"EUR","max":1800,"min":1700}},"excel_rows":[11],"exchange_page_url":{"notes":null,"source_ref":"https://www.unibocconi.it/en/for-international-students/incoming-exchange-students","source_type":"official_web","status":"verified","value":"https://www.unibocconi.it/en/for-international-students/incoming-exchange-students"},"excluded_majors":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"ext":{},"fact_sheet_status":{"drive_links":["https://drive.google.com/drive/folders/1QXqoof0eDYuXvZnBxZSnZuRN1KaK04C9"],"extracted_files":["data/raw/extracted/Bocconi/2023- 2024/Bocconi Fact Sheet 2023-2024.pdf.txt","data/raw/extracted/Bocconi/2024-2025/Bocconi Fact Sheet 2024-2025 Online website version (2).pdf.txt","data/raw/extracted/Bocconi/2024-2025/Bocconi Fact Sheet 2024-2025 Printable version (3).pdf.txt","data/raw/extracted/Bocconi/2025-2026/AY2526_Factsheet International Student Desk Exchange_Pieghevole.pdf.txt"],"local_files":["data/raw/factsheets/Bocconi/2023- 2024/Bocconi Fact Sheet 2023-2024.pdf","data/raw/factsheets/Bocconi/2024-2025/Bocconi Fact Sheet 2024-2025 Online website version (2).pdf","data/raw/factsheets/Bocconi/2024-2025/Bocconi Fact Sheet 2024-2025 Printable version (3).pdf","data/raw/factsheets/Bocconi/2025-2026/AY2526_Factsheet International Student Desk Exchange_Pieghevole.pdf"],"match_status":"matched","notes":null},"fall_term_dates":{"notes":"AY 2026-2027 Fall schedule: mandatory check-in Aug 25–28; Italian crash course Aug 25–Sep 5; classes Sep 2–Dec 5; mid-terms Oct 19–28; early exchange exam session Dec 9–22 (earliest departure Dec 23); regular exam sessions Jan 7–19 and Jan 20–Feb 2, 2027.","source_ref":"https://www.unibocconi.it/en/for-international-students/incoming-exchange-students","source_type":"official_web","status":"verified","value":"2026-09-02 to 2026-12-22 (early exchange exams) / 2027-02-02 (regular exam sessions)"},"final_semester_allowed":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_grants_or_stipends":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_language_requirement":{"notes":"Crash course dates for AY 2026-2027 published on https://www.unibocconi.it/en/for-international-students/incoming-exchange-students.","source_ref":"http://www.ir.unibocconi.eu/itacourse","source_type":"official_web","status":"verified","value":"Not required for English-taught courses; B2 Italian expected if selecting Italian-taught courses. Optional pre-term Italian crash course offered (Aug 25–Sep 5 Fall; Jan 25–Feb 6 Spring)."},"housing_availability":{"notes":null,"source_ref":"https://www.unibocconi.it/en/housing-information-incoming-exchange-students","source_type":"official_web","status":"verified","value":"assisted"},"housing_notes":{"notes":"Rent itemization from https://www.unibocconi.it/en/foe/incoming-exchange-students/estimated-costs and AY25-26 factsheet #page=2.","source_ref":"https://www.unibocconi.it/en/housing-information-incoming-exchange-students","source_type":"official_web","status":"verified","value":"Limited on-campus residence rooms (EUR 4,000–4,800/semester single) allocated on a first-come, first-served basis; Bocconi provides guidance for private rentals (double EUR 500–750/mo, single EUR 600–1,100/mo, entire flat EUR 800–1,800/mo)."},"instruction_languages":{"notes":null,"source_ref":"https://www.unibocconi.it/en/for-international-students/incoming-exchange-students","source_type":"official_web","status":"verified","value":["English","Italian"]},"international_support_services":{"notes":null,"source_ref":"https://www.unibocconi.it/en/for-international-students/incoming-exchange-students","source_type":"official_web","status":"verified","value":"International Student Desk (ISD) online application portal, mandatory Welcome Check-in days, optional pre-term Italian crash course, visa/Permesso guidance, and housing info."},"living_cost_usd_est":{"notes":"5-month midpoint estimate: 1,750 EUR/month * 5 months = 8,750 EUR * 1.1052 USD/EUR = 9,670.50 USD (ECB 2026-11-13 reference rate, collected 2026-11-15: https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html).","source_ref":"https://www.unibocconi.it/en/admissions/cost-aid/cost-attendance-ay-2026-2027","source_type":"official_web","status":"partial","value":9670.5},"mandatory_host_fees_and_insurance":{"notes":"Confirmed also in data/raw/factsheets/Bocconi/2025-2026/AY2526_Factsheet International Student Desk Exchange_Pieghevole.pdf#page=2.","source_ref":"https://www.unibocconi.it/en/foe/incoming-exchange-students/estimated-costs","source_type":"official_web","status":"verified","value":"No mandatory Bocconi enrollment health insurance fee; non-EU students require valid international health insurance for visa/Permesso di Soggiorno (e.g., WAI Italy ~EUR 91/6 months) and pay ~EUR 100.46 + EUR 16 stamp for Permesso di Soggiorno."},"min_gpa_host":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"min_standing_note":{"notes":"No central incoming GPA minimum published; academic selection is handled by the home partner university.","source_ref":"https://www.unibocconi.it/en/for-international-students/incoming-exchange-students","source_type":"official_web","status":"verified","value":"Requires nomination by a home partner university; undergraduate exchange students select 30xxx undergraduate-level courses."},"nomination_deadlines":{"notes":null,"source_ref":"https://www.unibocconi.it/en/for-international-students/incoming-exchange-students/online-application","source_type":"official_web","status":"partial","value":"Home partner coordinator submits online nomination first; Spring 2027 student online application window ran Sep 30 – Oct 22, 2026 (15:00 CET). Fall deadlines communicated per partner nomination cycle."},"official_name":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:11","source_type":"excel_list","status":"verified","value":"Bocconi University"},"official_website_url":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:11","source_type":"excel_list","status":"verified","value":"http://www.unibocconi.eu/"},"region":{"notes":"From normalized manifest country/region mapping","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:11","source_type":"excel_list","status":"verified","value":"Europe"},"required_application_docs":{"notes":null,"source_ref":"https://www.unibocconi.it/en/for-international-students/incoming-exchange-students/online-application","source_type":"official_web","status":"verified","value":["Most recent university academic transcript","CV / Resume","Headshot photo (for Bocconi ID card)","Passport personal data page (or EU national ID card)","Disability certificate from home university (optional, only if requesting accommodations)"]},"schema_version":"1.0.0","seat_quota":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"shard":8,"short_name":{"notes":null,"source_ref":"https://www.unibocconi.it/en/for-international-students/incoming-exchange-students","source_type":"official_web","status":"verified","value":"Bocconi"},"slug":"bocconi-university","spring_term_dates":{"notes":"AY 2026-2027 Spring schedule (TBC welcome): check-in Jan 25–29; crash course Jan 25–Feb 6; classes Feb 3–May 15 (some Law courses end May 22); mid-terms Mar 18–Apr 3; 1st exam session May 17–31; 2nd exam session Jun 3–Jul 10.","source_ref":"https://www.unibocconi.it/en/for-international-students/incoming-exchange-students","source_type":"official_web","status":"verified","value":"2027-02-03 to 2027-07-10 (classes end 2027-05-15; earliest departure 2027-06-01)"},"state_or_province":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"tuition_model":{"notes":"Incoming bilateral exchange students pay tuition at their home institution and are exempt from Bocconi tuition and academic fees.","source_ref":"https://www.unibocconi.it/en/for-international-students/incoming-exchange-students","source_type":"official_web","status":"verified","value":"auc_exchange_waiver"},"visa_lead_time_and_financial_proof":{"notes":"Visa portal URL extracted from Bocconi fact sheet; Permesso fees from https://www.unibocconi.it/en/foe/incoming-exchange-students/estimated-costs.","source_ref":"http://www.ir.unibocconi.eu/incomingexchangevisa","source_type":"official_web","status":"verified","value":"Non-EU incoming exchange students require an Italian Type D Student Visa prior to arrival via Universitaly / local Italian Consulate and must apply for a Permesso di Soggiorno within 8 working days of arrival (~EUR 100.46 + EUR 16 revenue stamp)."}}');
INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('bogazici-university', '[12]', 1, 'matched', '["data/raw/factsheets/Bogazici/2023-2024/Boğaziçi University.pdf","data/raw/factsheets/Bogazici/2024-2025/Bogazici University Factsheet 2024-2025.pdf","data/raw/factsheets/Bogazici/2026-2027/Fact sheet 2026-2027.pdf"]', '[]', 'Boğaziçi University', NULL, 'Turkey', NULL, 'Istanbul', 'Europe', 'active', '["UG","GR"]', 'Must be nominated by home university; Boğaziçi reviews applications and individual academic units decide on admission (exchange students must take at least one course from their registered host department).', 'University-wide', '["ALL"]', '["ALL"]', NULL, NULL, '["English","Turkish"]', 'full', 'Non-native English speakers must provide proof of CEFR B2 or higher: TOEFL iBT 79+ (Writing 22+), IELTS 6.5+, Cambridge Assessment English C1, OR a formal signed B2/C1 certification letter from the home university (no explicit RHET 1020 exemption stated).', 'None required for English-medium coursework; Turkish applies only to certain courses in Law and Turkish Language and Literature (credited Turkish language courses are offered to exchange students).', '["Fall","Spring","Summer"]', 'Fall Semester (AY 2026-2027): Online pre-registration deadline Aug 20, 2026; Orientation Sep 14, 2026; Online course registration Sep 15-17, 2026; Classes Sep 21 – Dec 11, 2026; Final exams through Dec 22, 2026 (Make-up exams Dec 23-25, 2026).', 'Spring Semester (AY 2026-2027): Online pre-registration deadline Dec 25, 2026; Orientation Jan 12, 2027; Online course registration Jan 13-15, 2027; Classes Jan 18 – Apr 22, 2027; Final exams Apr 25 – May 4, 2027.', NULL, NULL, 'auc_exchange_waiver', NULL, NULL, NULL, NULL, 'unknown', 'Boğaziçi University has no separate institutional health insurance requirement, but Turkish law requires valid health insurance covering the full stay for the mandatory Student Residence Permit (EU reciprocity public insurance or private health insurance purchased in Turkey).', 'off_campus_only', 'AY 2026-2027 Fact Sheet p.10 states Boğaziçi University does not offer on-campus housing for incoming students; students must arrange their own off-campus accommodation (contact residencepermit@bogazici.edu.tr for recommendations).', NULL, NULL, 'Nationalities eligible for touristic entry may enter Türkiye with an e-Visa or passport entry stamp and complete university registration; other nationalities must obtain a Student Visa (not an internship visa) from a Turkish embassy/consulate beforehand. All students must enter with a valid passport (not national ID) and apply for a Turkish Student Residence Permit after arrival with valid health insurance and proof of accommodation.', 'http://bogazici.edu.tr/', 'https://intl.bogazici.edu.tr/', 'http://registration.bogazici.edu.tr/schedule.htm', NULL, 'Boğaziçi credit-hour system (typical course is 3-4 credits / 5-7 ECTS); incoming exchange students take 4-6 courses totaling 17-21 Boğaziçi credits (~20-30 ECTS) per semester. Grading scale: AA (4.0) to DD (1.0) pass, F (0.0) fail.', 'Exchange students must take at least 1 course from their registered host department (Erasmus >=2); application course lists are provisional and finalized during registration subject to quotas and instructor consent. Some Law and Turkish Language & Literature courses are taught in Turkish.', '["Home university nomination (via Google Form or EWP)","Official academic transcript in English","Provisional course list (at least 1 course in host department)","Statement of Purpose","One letter of recommendation from a university instructor (English or Turkish)","Proof of English proficiency (CEFR B2+ certificate or home university letter)"]', '100% English-medium Turkish public research university offering 34 UG programs across 7 faculties and 7 graduate institutes; American-style credit-hour system requiring academic advisor course approval at registration.', NULL, 'multi_campus', NULL, 'Mandatory orientation covering course registration, campus life, and procedures; Office of International Relations incoming advising and Residence Permit Operations team; 40+ student clubs, sports centers, cultural series, and credited Turkish language courses.', 'Spring 2027: Nomination Sep 15, 2026, Application Oct 15, 2026; Fall / Full Year 2027-2028: Nomination Apr 15, 2027, Application May 15, 2027; Spring 2028: Nomination Sep 15, 2027, Application Oct 15, 2027.', '{}', '{"academic_style":{"notes":"Program listing on pp.5-7; advisor approval during registration on p.8.","source_ref":"data/raw/factsheets/Bogazici/2026-2027/Fact sheet 2026-2027.pdf#page=4","source_type":"fact_sheet","status":"verified","value":"100% English-medium Turkish public research university offering 34 UG programs across 7 faculties and 7 graduate institutes; American-sty