exemption.', 'English proficiency required; no secondary language requirement.', '["Fall","Spring"]', 'AY 2026-2027: Classes Aug 26 - Dec 3, 2026; Study Days Dec 4 & Dec 7; Final Exams Dec 8 - Dec 16, 2026 (late August arrival/mandatory orientation).', 'AY 2026-2027: Classes Jan 19 - May 6, 2027; Study Day May 7; Final Exams May 10 - May 18, 2027 (early January arrival/mandatory orientation).', NULL, NULL, 'auc_exchange_waiver', 'USD', 2304, 2304, 11520.0, 'partial', 'AY 2026-2027 estimated per semester: Mandatory Health Insurance $3,917 and Visa fees $400; mandatory on-campus housing & meal plan included in $10,422 Room & Board estimate.', 'guaranteed', 'Typically 2-6 person suites with single bedrooms (~80-100 sq ft), shared bathrooms, and common space (Ziv suite + All Access + 5 Meal Plan modeled at $10,422/sem for 2026-27).', NULL, NULL, 'J-1 Exchange Visitor visa sponsorship (Form DS-2019) coordinated by Brandeis ISSO via electronic VIDOF (Visa Information/Declaration of Finances) portal requiring proof of liquid financial support for full exchange duration; 2026-27 Fact Sheet p.6 estimates ~$400 visa fees.', 'http://www.brandeis.edu/', 'https://www.brandeis.edu/abroad/study-at-brandeis/incoming-exchange/index.html', 'https://www.brandeis.edu/registrar/registration/schedule.html', NULL, 'US semester credits (most courses 4 credits). Exchange students must take 12 credits min, up to 20 credits max with permission; typical load 16 credits (4 courses).', 'Graduate-level courses are closed to undergraduate exchange students; Business and Economics courses are high-demand and difficult to register for; some courses require instructor/prerequisite review; add/drop spans first 2 weeks.', '["Online Application (Personal & Academic Info, Emergency Contact, Personal Statement, Profile Photo, Passport photo page)","Official Transcript","TOEFL/English proficiency proof (if applicable)"]', 'US liberal arts seminar/lecture participation model: class attendance often counts toward final grades, continuous multi-assignment assessment throughout semester, active class discussion.', NULL, NULL, NULL, 'Office of Study Abroad, ISSO visa advising, mandatory Orientation, Brandeis Counseling Center, BUGS peer tutoring, Brandeis Writing Center, Spiritual Life chapels/Muslim prayer room, 250+ clubs, Gosman Sports Center.', 'Fall/Academic Year: Partner Nomination Apr 1 (apps open Feb 1), Student Application May 1. Spring: Partner Nomination Sep 15 (apps open Aug 1), Student Application Oct 15.', '{}', '{"academic_style":{"notes":null,"source_ref":"data/raw/factsheets/Brandeis/2026-2027/FactSheet_26-27.pdf#page=8","source_type":"fact_sheet","status":"verified","value":"US liberal arts seminar/lecture participation model: class attendance often counts toward final grades, continuous multi-assignment assessment throughout semester, active class discussion."},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:14","source_type":"excel_list","status":"verified","value":"University-wide"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:14","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:14","source_type":"excel_list","status":"verified","value":["UG"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:14","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":"brandeis.edu describes Waltham campus as ~10 miles outside downtown Boston without explicit suburban/urban classification label in verified excerpts.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{