INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('copenhagen-business-school', '[24]', 1, 'matched', '["data/raw/factsheets/Copenhagen Business School/2024-2025/Copenhagan Business School.pdf","data/raw/factsheets/Copenhagen Business School/2025-2026/Promotional Toolkit for CBS Exchange _ CBS - Copenhagen Business School.docx"]', '[]', 'Copenhagen Business School', 'CBS', 'Denmark', NULL, 'Copenhagen', 'Europe', 'active', '["UG","GR"]', 'Undergraduate exchange courses are open to Bachelor students; graduate exchange courses require a completed relevant Bachelor''s degree (or equivalent >=3 years university study).', 'Business Administration', '["BUS"]', '["Business Administration"]', NULL, NULL, '["English"]', 'full', 'Incoming exchange students must document English proficiency (no explicit RHET 1020 exemption stated). CBS English Proficiency FAQ specifies IELTS Academic 7.0, TOEFL iBT 94 (Home Edition accepted; selective graduate courses may expect higher), Cambridge CAE >=185 / CPE, or Duolingo 130 unless exempt via full English-taught degree in an accepted English-speaking country (Denmark excluded).', 'None required for English-taught exchange courses. CBS offers an optional pre-semester Danish crash course (https://www.studieskolen.dk/en/cbs/crashcourse) and a credit-bearing semester Danish language course.', '["Fall","Spring"]', 'Autumn semester (AY 2026-2027): 1 Sep 2026 - 31 Jan 2027 (Danish crash course 17-21 Aug 2026; latest arrival 24 Aug 2026; mandatory Introduction Programme 25-28 Aug 2026; exams Oct-Dec/Jan).', 'Spring semester (AY 2026-2027): 1 Feb 2027 - 30 Jun 2027 (Danish crash course 18-22 Jan 2027; latest arrival 25 Jan 2027; mandatory Introduction Programme 26-29 Jan 2027; exams Mar-Jun).', NULL, NULL, 'auc_exchange_waiver', NULL, NULL, NULL, NULL, 'unknown', NULL, 'assisted', 'Limited amount of non-guaranteed housing for incoming exchange students via CBS Housing Department (privately owned dorms; link sent via email to registered exchange students; apply late May for Autumn / mid-Nov for Spring via cbs.dk/housing). Private housing supplement facilitated in Autumn semester only.', NULL, NULL, 'Non-EU/EEA citizens must have their Danish student residence permit processed prior to arrival (unless eligible for visa-free travel to Denmark). EU/EEA citizens apply for a residence certificate if staying >3 months; Nordic citizens need no residence permit.', 'https://www.cbs.dk/en', 'https://www.cbs.dk/en/study/internationals/exchange-students', 'https://www.cbs.dk/en/international-opportunities/international-students/guestexchange-student/undergraduate-courses', NULL, 'ECTS; normal full-time semester workload is 30 ECTS (4 courses x 7.5 ECTS = ~825 total study hours).', 'Autumn course catalog publishes mid-March and Spring catalog mid-September; course selection occurs late April (Autumn) / late October (Spring). Graduate courses require completed Bachelor''s degree.', '["Home university nomination (via CBS form to inboundexchange@cbs.dk)","Updated university transcript in English","Proof of English proficiency","Resume/CV in English","Copy of passport (photo page only)"]', NULL, NULL, 'urban', NULL, 'Mandatory Introduction Week, optional pre-semester Danish crash course (https://www.studieskolen.dk/en/cbs/crashcourse), and Buddy Programme with airport pick-up.', 'Autumn/Full Year: Nomination 15 April; Exchange application & course selection late April; Accommodation late May. Spring: Nomination 15 October; Application & course selection late October; Accommodation mid-November (2024 cycle dates in PDF #page=4).', '{}', '{"academic_style":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:24","source_type":"excel_list","status":"verified","value":"Business Administration"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:24","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:24","source_type":"excel_list","status":"verified","value":["UG","GR"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:24","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":"Fact Sheet #page=2 states: ''CBS has an urban campus in Frederiksberg, an integrated part of Copenhagen.''","source_ref":"data/raw/factsheets/Copenhagen Business School/2024-2025/Copenhagan Business School.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"urban"},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:24","source_type":"excel_list","status":"verified","value":"Copenhagen"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:24","source_type":"excel_list","status":"verified","value":"Denmark"},"course_catalog_url":{"notes":"Graduate exchange catalog at https://www.cbs.dk/en/international-opportunities/international-students/guestexchange-student/graduate-courses.","source_ref":"data/raw/factsheets/Copenhagen Business School/2025-2026/Promotional Toolkit for CBS Exchange _ CBS - Copenhagen Business School.docx","source_type":"fact_sheet","status":"verified","value":"https://www.cbs.dk/en/international-opportunities/international-students/guestexchange-student/undergraduate-courses"},"course_restrictions_note":{"notes":null,"source_ref":"data/raw/factsheets/Copenhagen Business School/2024-2025/Copenhagan Business School.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"Autumn course catalog publishes mid-March and Spring catalog mid-September; course selection occurs late April (Autumn) / late October (Spring). Graduate courses require completed Bachelor''s degree."},"credit_system_and_load":{"notes":null,"source_ref":"data/raw/factsheets/Copenhagen Business School/2024-2025/Copenhagan Business School.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"ECTS; normal full-time semester workload is 30 ECTS (4 courses x 7.5 ECTS = ~825 total study hours)."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Mapped from Excel agreement scope ''Business Administration'' to AUC School of Business (BUS).","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:24","source_type":"excel_list","status":"partial","value":["BUS"]},"eligible_majors":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:24","source_type":"excel_list","status":"verified","value":["Business Administration"]},"english_course_availability":{"notes":null,"source_ref":"data/raw/factsheets/Copenhagen Business School/2024-2025/Copenhagan Business School.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"full"},"english_course_list_url":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":"Verbatim PDF URL extracted from CBS 2025-2026 Promotional Toolkit DOCX; documentation requirement also in Fact Sheet #page=4.","source_ref":"https://www.cbs.dk/files/cbs.dk/english_proficiency_faq.pdf","source_type":"official_web","status":"verified","value":"Incoming exchange students must document English proficiency (no explicit RHET 1020 exemption stated). CBS English Proficiency FAQ specifies IELTS Academic 7.0, TOEFL iBT 94 (Home Edition accepted; selective graduate courses may expect higher), Cambridge CAE >=185 / CPE, or Duolingo 130 unless exempt via full English-taught degree in an accepted English-speaking country (Denmark excluded)."},"est_monthly_living_local":{"notes":"CBS fact sheet and retrieved cbs.dk pages list living expenses as a topic without publishing an official CBS monthly DKK/EUR total budget; non-CBS third-party estimates excluded.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"excel_rows":[24],"exchange_page_url":{"notes":null,"source_ref":"data/raw/factsheets/Copenhagen Business School/2025-2026/Promotional Toolkit for CBS Exchange _ CBS - Copenhagen Business School.docx","source_type":"fact_sheet","status":"verified","value":"https://www.cbs.dk/en/study/internationals/exchange-students"},"excluded_majors":{"notes":null,"source