"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"shard":1,"short_name":{"notes":null,"source_ref":"data/raw/factsheets/Copenhagen Business School/2024-2025/Copenhagan Business School.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"CBS"},"slug":"copenhagen-business-school","spring_term_dates":{"notes":null,"source_ref":"https://www.cbs.dk/exchange","source_type":"official_web","status":"verified","value":"Spring semester (AY 2026-2027): 1 Feb 2027 - 30 Jun 2027 (Danish crash course 18-22 Jan 2027; latest arrival 25 Jan 2027; mandatory Introduction Programme 26-29 Jan 2027; exams Mar-Jun)."},"state_or_province":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"tuition_model":{"notes":"Nominated exchange students from official CBS partner universities do not pay tuition fees to CBS (pay regular tuition to home institution); distinct from fee-paying freemovers.","source_ref":"https://www.cbs.dk/exchange","source_type":"official_web","status":"verified","value":"auc_exchange_waiver"},"visa_lead_time_and_financial_proof":{"notes":"Danish SIRI financial proof requirement is DKK 7,426/month (DKK 89,112/year) per https://www.nyidanmark.dk/en-GB/You-want-to-apply/Study/Higher-education.","source_ref":"data/raw/factsheets/Copenhagen Business School/2024-2025/Copenhagan Business School.pdf#page=4","source_type":"fact_sheet","status":"verified","value":"Non-EU/EEA citizens must have their Danish student residence permit processed prior to arrival (unless eligible for visa-free travel to Denmark). EU/EEA citizens apply for a residence certificate if staying >3 months; Nordic citizens need no residence permit."}}');
INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('cornell-university', '[25]', 4, 'none', '[]', '[]', 'Cornell University', NULL, 'United States', 'New York', 'Ithaca', 'North America', 'active', '["UG"]', 'Must have completed at least 2 full-time university semesters prior to exchange and be nominated by home institution.', 'University-wide', '["ALL"]', '["ALL"]', NULL, 3.0, '["English"]', 'full', 'Minimum TOEFL iBT 100, IELTS Academic 7.5, or Duolingo English Test 130 (exempt for native speakers or applicants studying at an institution where English is the official language).', 'None (instruction is in English)', '["Fall","Spring"]', 'AY 2026-2027 Fall: Instruction Aug 24 – Dec 4, 2026; Final Exams Dec 11–19, 2026.', 'AY 2026-2027 Spring: Instruction Jan 25 – May 11, 2027; Final Exams May 15–22, 2027.', NULL, NULL, 'auc_exchange_waiver', 'USD', 2292, 2292, 11460.0, 'partial', 'Mandatory Bursar charges: Cornell Student Health Plan (2026-2027: $4,092/year; Fall new $1,705; Spring new $2,046), Student Health Fee ($300/semester 2026-2027), and Student Activity Fee.', 'assisted', 'On-campus housing is limited and NOT guaranteed for incoming exchange students; if assigned on-campus housing or meal plan, fees appear on the Cornell Bursar bill.', NULL, NULL, 'Accepted international exchange students must submit Declaration of Finances and bank documentation for J-1/F-1 immigration processing (reference UG living expense budget $27,507/year).', 'https://www.cornell.edu/', 'https://abroad.globallearning.cornell.edu/incoming-students/international-exchange', 'https://courses.cornell.edu/', NULL, 'US credit hours; full-time exchange students must complete a minimum of 12 credits per semester with a 2.0+ term GPA to maintain good academic standing.', 'Students are placed into an undergraduate Cornell college/school covered by the partner agreement based on proposed major; enrollment subject to prerequisites, class size, instructor consent, and college-specific restrictions (major-only capstones, first-year writing seminars, and independent study/lab research typically closed).', '["Statement of purpose","List of Cornell courses of interest","Official transcripts (undergraduate and graduate if applicable)","Proof of English language proficiency"]', 'US-style liberal arts', NULL, NULL, NULL, NULL, 'Fall: Nomination Mar 1 / Application Mar 15; Spring: Nomination Sep 1 / Application Sep 15.', '{}', '{"academic_style":{"notes":"US research university with credit-hour system and college-based undergraduate distribution.","source_ref":"https://courses.cornell.edu/","source_type":"official_web","status":"verified","value":"US-style liberal arts"},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:25","source_type":"excel_list","status":"v