INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('east-carolina-university', '[28]', 5, 'unmatched_here', '[]', '[]', 'East Carolina University', 'ECU', 'United States', 'North Carolina', 'Greenville', 'North America', 'active', '["UG","GR"]', NULL, 'University-wide', '["ALL"]', '["ALL"]', NULL, NULL, '["English"]', 'full', 'Incoming exchange online application requires uploading ''proof of English language proficiency if applicable''; specific exchange test cutoffs and RHET 1020 equivalency are not stated on the incoming exchange portal.', 'English (proof of English language proficiency required in the incoming application if applicable).', '["Fall","Spring"]', 'Fall 2026: All residence halls open Aug 15 (move-in Aug 12-14); Classes Aug 17 - Nov 30, 2026; Fall Break Oct 3-6; Final Exams Dec 2-9, 2026; Residence halls close Dec 10, 2026.', 'Spring 2027: Residence halls reopen Jan 7, 2027; Classes Jan 11 - Apr 27, 2027; Spring Break Mar 6-14, 2027; Final Exams Apr 29 - May 6, 2027; Residence halls close May 7, 2027.', NULL, NULL, NULL, 'USD', 1140.1, 1222.0, 5905.25, 'partial', 'J-1 exchange visitors are federally required to carry J-1 compliant medical insurance for the full DS-2019 period (home country policies are generally not accepted; enrollment in an ECU/UNC-approved plan is mandatory; degree-seeking Student Blue SHIP is estimated at $1,312/sem UG or $2,366.50/sem GR). On-campus residents are typically required to carry a residential meal plan (Purple plans $2,517+tax/semester).', 'guaranteed', 'Incoming exchange students are required to live on campus in designated reserved spots and may move in one day prior to orientation. ECU residence hall rates range ~$3,046.50 (standard) to $3,576.00/semester (College Hill Suites), plus required residential meal plans (~$2,517+tax/semester).', NULL, NULL, 'Requires J-1 Exchange Visitor visa with Form DS-2019 issued by ECU Office of Global Affairs after acceptance and verification of financial means (30-day post-program grace period applies; additional financial/insurance proof required for J-2 dependents).', 'https://www.ecu.edu/', 'https://global-affairs.ecu.edu/incoming-exchange-students/', 'https://catalog.ecu.edu/undergraduate/', 'https://catalog.ecu.edu/undergraduate/', NULL, NULL, '["Home university official nomination","Completed ECU online incoming exchange application (via emailed link)","Passport biographical page copy","Current official academic transcripts","Proof of English language proficiency (if applicable)","Proof of financial means","List of intended courses"]', NULL, NULL, NULL, NULL, 'ECU Office of Global Affairs (https://global-affairs.ecu.edu/) manages incoming exchange onboarding, DS-2019 sponsorship, mandatory international student orientation, J-1 insurance compliance, and reserved on-campus housing coordin