INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('ecole-de-management-de-normandie-em-normandie', '[31]', 5, 'matched', '["data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf"]', '[]', 'Ecole de Management de Normandie (EM Normandie)', 'EM Normandie', 'France', NULL, 'Le Havre', 'Europe', 'active', '["UG","GR"]', NULL, 'Business Administration', NULL, '["Business Administration"]', NULL, NULL, '["English","French"]', 'full', 'For English-taught programmes (waived for native English speakers; home university certificates accepted): UG requires CEFR B2 (TOEFL iBT 72, IELTS 5.5, TOEIC 750); GR requires CEFR B2 (TOEFL iBT 83, IELTS 6.0, TOEIC 790). RHET 1020 waiver not mentioned.', 'French CEFR B2 (DELF/TCF scores) required only for French-taught programmes; waived for English-taught tracks and native speakers.', '["Fall","Spring","Summer"]', 'Fall semester: Early September to late December (exams included; exact dates vary by chosen programme and campus).', 'Spring semester: Early January to April/May (exams included; Year 3 students start late January; exact dates depend on programme and campus).', NULL, NULL, 'auc_exchange_waiver', 'EUR', 800.0, 800.0, 4420.8, 'partial', 'In France, French Social Security registration is mandatory and free of charge (EU students bring EHIC; supplementary private coverage recommended, promo code 76EMN-10 for Studcorp/Heyme). UK/Ireland/UAE campuses require local/home private medical insurance or UAE residence permit insurance. Optional Student Concierge Club membership is EUR 150 for 6 months.', 'assisted', 'No on-campus housing offered; students use the Studapart housing platform partnered with EM Normandie (property owners, student residences, agencies) once admitted.', NULL, NULL, 'EM Normandie issues an official acceptance letter upon complete application for visa purposes (Campus France / Etudes en France and VLS-TS long-stay student visa apply for non-EU students in France; UK/Ireland/UAE rules vary by chosen campus).', 'http://www.em-normandie.fr/', 'https://en.em-normandie.com/em-normandie-experience/open-world-studying-abroad/exchange-programmes', 'https://en.em-normandie.com/em-normandie-experience/open-world-studying-abroad/exchange-programmes', 'https://en.em-normandie.com/em-normandie-experience/open-world-studying-abroad/exchange-programmes', 'ECTS credit system; minimum requirement of 15 ECTS credits per semester for exchange students.', 'Access to the 6 campuses (Le Havre, Caen, Paris, Dublin, Oxford, Dubai) depends on study level; students may change campuses during a full-year exchange (except dual-degree).', '["Home university online nomination","Online exchange application form","Language certificate from home university or TOEFL/IELTS/TOEIC/DELF/TCF scores"]', NULL, NULL, 'multi_campus', NULL, 'International Affairs team (incoming@em-normandie.fr), Studapart housing support (accommodation@em-normandie.fr), complimentary French classes for English-taught programmes, and optional Student Concierge Club.', '2024-25 Fact Sheet: Fall/Full Year nomination Apr 15, application Apr 30; Spring nomination Oct 15, application Oct 31 (later cycles note up to May 15/30).', '{}', '{"academic_style":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:31","source_type":"excel_list","status":"verified","value":"Business Administration"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:31","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:31","source_type":"excel_list","status":"verified","value":["UG","GR"]},"available_terms":{"notes":"Fall/Spring/Summer","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:31","source_type":"excel_list","status":"verified","value":["Fall","Spring","Summer"]},"campus_type":{"notes":"6 campuses across Caen, Le Havre, Paris (Clichy), Dublin, Oxford, and Dubai.","source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"multi_campus"},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:31","source_type":"excel_list","status":"verified","value":"Le Havre"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:31","source_type":"excel_list","status":"verified","value":"France"},"course_catalog_url":{"notes":"Hosts downloadable ''Course Offer - Exchange & Free Movers Students 2026-27'' and Road Map PDFs.","source_ref":"https://en.em-normandie.com/em-normandie-experience/open-world-studying-abroad/exchange-programmes","source_type":"official_web","status":"partial","value":"https://en.em-normandie.com/em-normandie-experience/open-world-studying-abroad/exchange-programmes"},"course_restrictions_note":{"notes":null,"source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"Access to the 6 campuses (Le Havre, Caen, Paris, Dublin, Oxford, Dubai) depends on study level; students may change campuses during a full-year exchange (except dual-degree)."},"credit_system_and_load":{"notes":null,"source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=2","source_type":"fact_sheet","status":"partial","value":"ECTS credit system; minimum requirement of 15 ECTS credits per semester for exchange students."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Excel agreement scope specifies ''Business Administration'' major/field rather than an AUC school code.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_majors":{"notes":"Excel agreement scope states ''Business Administration''.","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:31","source_type":"excel_list","status":"verified","value":["Business Administration"]},"english_course_availability":{"notes":"Undergraduate and graduate business tracks available fully in English across campuses.","source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"full"},"english_course_list_url":{"notes":"Course offer PDFs include English-taught undergraduate and graduate business tracks.","source_ref":"https://en.em-normandie.com/em-normandie-experience/open-world-studying-abroad/exchange-programmes","source_type":"official_web","status":"partial","value":"https://en.em-normandie.com/em-normandie-experience/open-world-studying-abroad/exchange-programmes"},"english_proficiency_and_rhet1020":{"notes":null,"source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"For English-taught programmes (waived for native English speakers; home university certificates accepted): UG requires CEFR B2 (TOEFL iBT 72, IELTS 5.5, TOEIC 750); GR requires CEFR B2 (TOEFL iBT 83, IELTS 6.0, TOEIC 790). RHET 1020 waiver not mentioned."},"est_monthly_living_local":{"notes":"2024-25 Fact Sheet p.3 lists monthly expense estimate for primary campus Le Havre (and Caen) as approx. EUR 800/month. Other campuses listed on p.3: Paris approx. EUR 1,200/month, Oxford approx. GBP 1,000/month, Dublin approx. EUR 1,600/month, Dubai approx. EUR 1,700/month.","source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=3","source_type":"fact_sheet","status":"verified","value":{"currency":"EUR","max":800.0,"min":800.0}},"excel_rows":[31],"exchange_page_url":{"notes":"Confirmed live exchange programmes & 2026-27 course offer downloads hub.","source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"https://en.em-normandie.com/em-normandie-experience/open-world-studying-abroad/exchange-programmes"},"excluded_majors":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"ext":{},"fact_sheet_status":{"drive_links":["https://drive.google.com/drive/folders/1Yx-wbVUZMdpLolPbOjhFAohvsuWXLMO_?usp=drive_link","https://drive.google.com/drive/folders/1Yx-wbVUZMdpLolPbOjhFAohvsuWXLMO_"],"extracted_files":["data/raw/extracted/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf.txt"],"local_files":["data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf"],"match_status":"matched","notes":null},"fall_term_dates":{"notes":null,"source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=1","source_type":"fact_sheet","status":"partial","value":"Fall semester: Early September to late December (exams included; exact dates vary by chosen programme and campus)."},"final_semester_allowed":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_grants_or_stipends":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_language_requirement":{"notes":null,"source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"French CEFR B2 (DELF/TCF scores) required only for French-taught programmes; waived for English-taught tracks and native speakers."},"housing_availability":{"notes":"No on-campus dormitories; EM Normandie partners with Studapart online housing platform (accessible once school login is issued; email accommodation@em-normandie.fr).","source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"assisted"},"housing_notes":{"notes":null,"source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"No on-campus housing offered; students use the Studapart housing platform partnered with EM Normandie (property owners, student residences, agencies) once admitted."},"instruction_languages":{"notes":"Undergraduate and graduate programmes offered fully in English or fully in French.","source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=2","source_type":"fact_sheet","status":"verified","value":["English","French"]},"international_support_services":{"notes":"Concierge Club and Studapart details on p.3.","source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"International Affairs team (incoming@em-normandie.fr), Studapart housing support (accommodation@em-normandie.fr), complimentary French classes for English-taught programmes, and optional Student Concierge Club."},"living_cost_usd_est":{"notes":"Le Havre primary campus EUR 800.00/month * 5 months = EUR 4,000.00; converted at ECB 2026-11-13 rate (collected 2026-11-15) 1 EUR = 1.1052 USD (https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html) = 4,420.80 USD (higher for Paris/Dublin/Dubai campuses).","source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=3","source_type":"fact_sheet","status":"partial","value":4420.8},"mandatory_host_fees_and_insurance":{"notes":null,"source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=3","source_type":"fact_sheet","status":"partial","value":"In France, French Social Security registration is mandatory and free of charge (EU students bring EHIC; supplementary private coverage recommended, promo code 76EMN-10 for Studcorp/Heyme). UK/Ireland/UAE campuses require local/home private medical insurance or UAE residence permit insurance. Optional Student Concierge Club membership is EUR 150 for 6 months."},"min_gpa_host":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"min_standing_note":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"nomination_deadlines":{"notes":null,"source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=1","source_type":"fact_sheet","status":"partial","value":"2024-25 Fact Sheet: Fall/Full Year nomination Apr 15, application Apr 30; Spring nomination Oct 15, application Oct 31 (later cycles note up to May 15/30)."},"official_name":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:31","source_type":"excel_list","status":"verified","value":"Ecole de Management de Normandie (EM Normandie)"},"official_website_url":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:31","source_type":"excel_list","status":"verified","value":"http://www.em-normandie.fr/"},"region":{"notes":"From normalized manifest country/region mapping","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:31","source_type":"excel_list","status":"verified","value":"Europe"},"required_application_docs":{"notes":"Language certificate rule on p.2; full document checklist provided inside online application portal.","source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=1","source_type":"fact_sheet","status":"partial","value":["Home university online nomination","Online exchange application form","Language certificate from home university or TOEFL/IELTS/TOEIC/DELF/TCF scores"]},"schema_version":"1.0.0","seat_quota":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"shard":5,"short_name":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:31","source_type":"excel_list","status":"verified","value":"EM Normandie"},"slug":"ecole-de-management-de-normandie-em-normandie","spring_term_dates":{"notes":null,"source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=1","source_type":"fact_sheet","status":"partial","value":"Spring semester: Early January to April/May (exams included; Year 3 students start late January; exact dates depend on programme and campus)."},"state_or_province":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"tuition_model":{"notes":"Official EM Normandie exchange guidelines confirm nominated partner exchange students are exempt from EM Normandie tuition fees (free-movers pay EUR 3,500-4,000/semester).","source_ref":"https://en.em-normandie.com/em-normandie-experience/open-world-studying-abroad/exchange-programmes","source_type":"official_web","status":"verified","value":"auc_exchange_waiver"},"visa_lead_time_and_financial_proof":{"notes":null,"source_ref":"data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=3","source_type":"fact_sheet","status":"partial","value":"EM Normandie issues an official acceptance letter upon complete application for visa purposes (Campus France / Etudes en France and VLS-TS long-stay student visa apply for non-EU students in France; UK/Ireland/UAE rules vary by chosen campus)."}}');
INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('edhec-business-school', '[32]', 6, 'matched', '["data/raw/factsheets/EDHEC Business School/2024-2025/Factsheet_EDHEC_BBA_2024-2025_2.pdf","data/raw/factsheets/EDHEC Business School/Factsheet_EDHEC_BBA_25-26.pdf","data/raw/factsheets/EDHEC Business School/Factsheet_Master_2025-26.pdf"]', '[]', 'EDHEC Business School', NULL, 'France', NULL, 'Nice', 'Europe', 'active', '["UG","GR"]', NULL, 'Business Administration', '["BUS"]', '["Business Administration"]', NULL, NULL, '["English","French"]', 'full', 'No official English test score required for Simple Exchange partner students; Double Degree applicants require TOEFL/TOEIC/IELTS + GMAT (#page=4). No RHET 1020 waiver stated.', NULL, '["Fall","Spring"]', NULL, NULL, NULL, NULL, 'auc_exchange_waiver', NULL, NULL, NULL, NULL, 'unknown', 'EU citizens: EHIC or private insurance. Non-EU: 1-semester stays require comprehensive private health insurance; 2-semester stays register for free French Social Security. Personal & civil liability insurance mandatory for all students.', 'assisted', 'Lille Campus: on-campus accommodation in the EDHEC residence (kots and private studios) plus off-campus offers via ISO when available; Nice Campus: off-campus accommodation only; first-come, first-served allocation (#page=5).', NULL, NULL, 'Non-EU/EEA students require a VLS-TS long-stay student visa supported by EDHEC ISO acceptance/enrollment documentation.', 'https://www.edhec.edu/en', 'https://www.edhec.edu/en/student-experience/international-experience/studying-abroad', NULL, NULL, 'ECTS; BBA regular/max 30 ECTS per semester (no EDHEC minimum for visiting BBA); Master (#page=8) minimum 20 ECTS, regular/max 30 ECTS. French 0–20 scale (10/20 pass).', 'Cannot combine courses across different levels/programmes; MSc Data Science & AI Fall only (exceptional); MSc Financial Engineering restricted to QTEM/Double Degree; MSc finance tracks have strict prerequisites/excellence screening; Learning Agreement locked after add/drop/start.', '["Learning Agreement / OLA","Headshot photo","Academic transcript in English","Passport or ID card copy","CV and Bachelor''s degree certificate (Master/MSc tracks, Master Fact Sheet #page=4)"]', 'Mandatory class attendance; personal laptop required (tablets/Chromebooks incompatible with exam software; Windows preferred at Master level).', NULL, 'multi_campus', NULL, 'EDHEC International Students Office (ISO, https://www.edhec.edu/en/iso/international-student-office) provides pre-arrival, visa documentation, housing guidance, and campus sports access.', 'BBA: Fall Nom Apr 3 / App Apr 25; Spring Nom end Sept / App mid Oct. Master (#page=3): Fall Nom Apr 3 / App Apr 25; Spring Nom Sep 29 / App Oct 10.', '{}', '{"academic_style":{"notes":"Also in Factsheet_Master_2025-26.pdf#page=8.","source_ref":"data/raw/factsheets/EDHEC Business School/Factsheet_EDHEC_BBA_25-26.pdf#page=6","source_type":"fact_sheet","status":"verified","value":"Mandatory class attendance; personal laptop required (tablets/Chromebooks incompatible with exam software; Windows preferred at Master level)."},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:32","source_type":"excel_list","status":"verified","value":"Business Administration"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:32","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:32","source_type":"excel_list","status":"verified","value":["UG","GR"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:32","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":"Nice and Lille campuses (Master #page=1/5 also covers Jean Arnault campus).","source_ref":"data/raw/factsheets/EDHEC Business School/Factsheet_EDHEC_BBA_25-26.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"multi_campus"},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:32","source_type":"excel_list","status":"verified","value":"Nice"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:32","source_type":"excel_list","status":"verified","value":"France"},"course_catalog_url":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"course_restrictions_note":{"notes":"Also detailed on #page=6.","source_ref":"data/raw/factsheets/EDHEC Business School/Factsheet_Master_2025-26.pdf#page=4","source_type":"fact_sheet","status":"verified","value":"Cannot combine courses across different levels/programmes; MSc Data Science & AI Fall only (exceptional); MSc Financial Engineering restricted to QTEM/Double Degree; MSc finance tracks have strict prerequisites/excellence screening; Learning Agreement locked after add/drop/start."},"credit_system_and_load":{"notes":"Master workload on Factsheet_Master_2025-26.pdf#page=8.","source_ref":"data/raw/factsheets/EDHEC Business School/Factsheet_EDHEC_BBA_25-26.pdf#page=6","source_type":"fact_sheet","status":"verified","value":"ECTS; BBA regular/max 30 ECTS per semester (no EDHEC minimum for visiting BBA); Master (#page=8) minimum 20 ECTS, regular/max 30 ECTS. French 0–20 scale (10/20 pass)."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Mapped from Excel scope ''Business Administration''.","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:32","source_type":"excel_list","status":"verified","value":["BUS"]},"eligible_majors":{"notes":"Verified via Excel scope.","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:32","source_type":"excel_list","status":"verified","value":["Business Administration"]},"english_course_availability":{"notes":"Full English-taught business exchange tracks at both BBA and Master levels.","source_ref":"data/raw/factsheets/EDHEC Business School/Factsheet_EDHEC_BBA_25-26.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"full"},"english_course_list_url":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":null,"source_ref":"data/raw/factsheets/EDHEC Business School/Factsheet_Master_2025-26.pdf#page=4","source_type":"fact_sheet","status":"partial","value":"No official English test score required for Simple Exchange partner students; Double Degree applicants require TOEFL/TOEIC/IELTS + GMAT (#page=4). No RHET 1020 waiver stated."},"est_monthly_living_local":{"notes":"EDHEC International Students Office portal (https://www.edhec.edu/en/iso/international-student-office) publishes housing and living-cost guidance (e.g., rent starting €550/mo Lille, €600/mo Nice, ~€80/mo utilities, 1-2 months deposit, ~€50 Assurance Habitation) without stating an official combined monthly min-max figure in the BBA/Master fact sheets.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"excel_rows":[32],"exchange_page_url":{"notes":"ISO portal at https://www.edhec.edu/en/iso/international-student-office.","source_ref":"data/raw/factsheets/EDHEC Business School/Factsheet_EDHEC_BBA_25-26.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"https://www.edhec.edu/en/student-experience/international-experience/studying-abroad"},"excluded_majors":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"ext":{},"fact_sheet_status":{"drive_links":["https://drive.google.com/open?id=17l6hJ3PEVazSKO3CDNkVNY4CLY8MNjAW","https://drive.google.com/drive/folders/19NqIX4-rGNaTRaXlEPC-Z3OCEJC9t2V9"],"extracted_files":["data/raw/extracted/EDHEC Business School/2024-2025/Factsheet_EDHEC_BBA_2024-2025_2.pdf.txt","data/raw/extracted/EDHEC Business School/Factsheet_EDHEC_BBA_25-26.pdf.txt","data/raw/extracted/EDHEC Business School/Factsheet_Master_2025-26.pdf.txt"],"local_files":["data/raw/factsheets/EDHEC Business School/2024-2025/Factsheet_EDHEC_BBA_2024-2025_2.pdf","data/raw/factsheets/EDHEC Business School/Factsheet_EDHEC_BBA_25-26.pdf","data/raw/factsheets/EDHEC Business School/Factsheet_Master_2025-26.pdf"],"match_status":"matched","notes":"Col H link (17l6hJ3PEVazSKO3CDNkVNY4CLY8MNjAW) unreachable (error_html_response: Drive return