INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('emlyon-business-school', '[34]', 8, 'matched', '["data/raw/factsheets/Emlyon Business School/2024-2025/Factsheet_GBBA_2024-2025.pdf","data/raw/factsheets/Emlyon Business School/2024-2025/Fiche_Factsheet_MSc-Management_2024-2025.pdf","data/raw/factsheets/Emlyon Business School/2024-2025/Partners_user_guide_-_nominations.pdf","data/raw/factsheets/Emlyon Business School/Factsheet_GBBA_2025_-_2026_V.2.pdf","data/raw/factsheets/Emlyon Business School/Factsheet_MiM_2025_-_2026_V.1_3_.pdf","data/raw/factsheets/Emlyon Business School/GBBA outline courses AY 2025-2026.pptx"]', '[]', 'Emlyon Business School', 'emlyon', 'France', NULL, 'Lyon', 'Europe', 'active', '["UG","GR"]', NULL, 'Business Administration', '["BUS"]', '["Business Administration"]', NULL, NULL, '["English","French"]', 'substantial', 'B2 CEFR level in English required for English-taught tracks (standard benchmarks: IELTS >= 6.0 / TOEFL iBT >= 80, or equivalent TOEIC/Cambridge/partner confirmation). RHET 1020 waiver not stated.', 'French not required for English-taught exchange tracks; B2 French recommended if selecting French-taught courses.', '["Fall","Spring"]', 'Early September to late December (exact semester dates vary by GBBA vs MiM)', 'Early January/February to late April/May (exact semester dates vary by GBBA vs MiM)', NULL, NULL, 'auc_exchange_waiver', 'EUR', 1000, 1000, 5526.0, 'partial', 'Bilateral exchange students are EXEMPT from the French CVEC student life fee (obtain free exemption certificate at cvec.etudiant.gouv.fr per Campus France/etudiant.gouv.fr). Registration for French Sécurité Sociale (etudiant-etranger.ameli.fr) is mandatory for stays >3 months, plus third-party civil liability insurance (~EUR 10).', 'assisted', 'Off-campus/private residences supported via emlyon''s Studapart portal and partner residence networks in Lyon.', NULL, NULL, 'Non-EU students staying >90 days must obtain a French VLS-TS long-stay student visa via Etudes en France (pastel.diplomatie.gouv.fr/etudesenfrance) / France-Visas before departure. Effective August 1, 2026, Décret n° 2026-526 increased minimum student financial proof from EUR 615/mo to EUR 877.50/month (EUR 10,530/year; 47% of gross SMIC).', 'http://www.em-lyon.com/', 'https://em-lyon.com/en/incoming-students', NULL, NULL, 'ECTS system. Global BBA exchange: 25–35 ECTS per semester (Year 3/4 courses). Master in Management (MiM): 2 to 6 graduate elective courses per semester (standard 5 ECTS / 24 contact hours each, ~27.5–30 ECTS full load).', 'Undergraduate exchange students select from Global BBA Year 3 or Year 4 courses; graduate exchange students select from MiM electives (2–6 courses).', NULL, NULL, NULL, 'urban', NULL, 'Incoming Students desk, Studapart housing portal, First Steps in France visa/Sécurité Sociale onboarding support.', 'Fall Semester: partner nomination May 1, student application May 15. Spring Semester: partner nomination October 1, student application October 10.', '{}', '{"academic_style":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:34","source_type":"excel_list","status":"verified","value":"Business Administration"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:34","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:34","source_type":"excel_list","status":"verified","value":["UG","GR"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:34","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":"Urban Lyon Gerland campus located at 144 avenue Jean Jaurès, 69007 Lyon.","source_ref":"https://em-lyon.com/en/campus/lyon","source_type":"official_web","status":"verified","value":"urban"},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:34","source_type":"excel_list","status":"verified","value":"Lyon"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:34","source_type":"excel_list","status":"verified","value":"France"},"course_catalog_url":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"course_restrictions_note":{"notes":null,"source_ref":"https://em-lyon.com/en/exchange-students-global-bba","source_type":"official_web","status":"verified","value":"Undergraduate exchange students select from Global BBA Year 3 or Year 4 courses; graduate exchange students select from MiM electives (2–6 courses)."},"credit_system_and_load":{"notes":"MiM rules confirmed on https://em-lyon.com/en/exchange-students-master-management.","source_ref":"https://em-lyon.com/en/exchange-students-global-bba","source_type":"official_web","status":"verified","value":"ECTS system. Global BBA exchange: 25–35 ECTS per semester (Year 3/4 courses). Master in Management (MiM): 2 to 6 graduate elective courses per semester (standard 5 ECTS / 24 contact hours each, ~27.5–30 ECTS full load)."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Excel agreement_scope_raw is ''Business Administration'', corresponding to AUC''s Onsi Sawiris School of Business.","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:34","source_type":"excel_list","status":"verified","value":["BUS"]},"eligible_majors":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:34","source_type":"excel_list","status":"verified","value":["Business Administration"]},"english_course_availability":{"notes":"English-taught tracks and electives are widely offered across Global BBA and Master in Management exchange programs alongside French-taught offerings (https://em-lyon.com/en/exchange-students-master-management).","source_ref":"https://em-lyon.com/en/exchange-students-global-bba","source_type":"official_web","status":"partial","value":"substantial"},"english_course_list_url":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":null,"source_ref":"https://em-lyon.com/en/exchange-students-global-bba","source_type":"official_web","status":"partial","val