INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('heilbronn-university-of-applied-sciences-faculty-of-international-business', '[39]', 3, 'matched', '["data/raw/factsheets/Heilbronn University of Applied Sciences/Information Sheet HHN WS2024-25 for Incomings.pdf"]', '[]', 'Heilbronn University of Applied Sciences, Faculty of International Business', 'HHN', 'Germany', NULL, 'Heilbronn-Sontheim', 'Europe', 'active', '["UG","GR"]', NULL, 'Business Administration', '["BUS"]', '["Business Administration"]', NULL, NULL, '["English","German"]', 'substantial', 'B2 English required for Bachelor exchange courses (Master requirements vary); consult HHN application page regarding TOEFL/IELTS vs home-partner certification.', 'None required for English-taught international programmes; German C1 needed only for regular German-taught modules.', '["Fall","Spring"]', 'Winter Semester runs September-February (exact WS2024-25 orientation/exam dates per annual academic calendar).', 'Summer Semester runs March-July.', NULL, NULL, 'auc_exchange_waiver', 'EUR', 934, 934, 5161, 'partial', 'Mandatory student contribution fee EUR 94/semester for partner exchange students in WS2024-25 (regular fee EUR 188/semester per HHN site) plus mandatory health insurance (~EUR 120/month unless EU EHIC exempt).', 'assisted', 'Dormitories ~EUR 350/month (supply < demand); assisted private rooms EUR 350-600/month.', NULL, NULL, 'Non-EU students should apply for a German student visa 5-6 months prior (fact sheet p.4); HHN incoming web page specifies EUR 992/month financial proof (blocked account/scholarship).', 'https://www.hs-heilbronn.de/en', 'https://www.hs-heilbronn.de/en/incoming-general-information', 'https://www.hs-heilbronn.de/international-course-offer', 'https://www.hs-heilbronn.de/international-course-offer', NULL, 'AUC agreement covers Business Administration (IB/WI programmes at Bildungscampus Heilbronn); combining modules across faculties possible upon request.', NULL, 'University of Applied Sciences (Hochschule für angewandte Wissenschaften) offering practice-oriented International Business modules.', NULL, 'multi_campus', NULL, 'Introductory days, intensive German courses (pre-semester and semester), and student tutor assistance for private housing.', 'Winter Semester (Fall): nomination May 1, application May 15; Summer Semester (Spring): nomination Nov 15, application Dec 1.', '{}', '{"academic_style":{"notes":null,"source_ref":"data/raw/factsheets/Heilbronn University of Applied Sciences/Information Sheet HHN WS2024-25 for Incomings.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"University of Applied Sciences (Hochschule für angewandte Wissenschaften) offering practice-oriented International Business modules."},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:39","source_type":"excel_list","status":"verified","value":"Business Administration"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:39","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:39","source_type":"excel_list","status":"verified","value":["UG","GR"]},"available_terms":{"notes":"Fall/ Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:39","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":"Four campuses: Bildungscampus Heilbronn (IB, WI), Heilbronn-Sontheim (TE, IT), Schwäbisch Hall (MV), and Künzelsau (TW).","source_ref":"data/raw/factsheets/Heilbronn University of Applied Sciences/Information Sheet HHN WS2024-25 for Incomings.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"multi_campus"},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:39","source_type":"excel_list","status":"verified","value":"Heilbronn-Sontheim"},"city_tier":{"notes":"Heilbronn city scale not explicitly categorized into schema city_tier options in fact sheet.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:39","source_type":"excel_list","status":"verified","value":"Germany"},"course_catalog_url":{"notes":null,"source_ref":"data/raw/factsheets/Heilbronn University of Applied Sciences/Information Sheet HHN WS2024-25 for Incomings.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"https://www.hs-heilbronn.de/international-course-offer"},"course_restrictions_note":{"notes":n