f":null,"source_type":"unknown","status":"unknown","value":null},"min_standing_note":{"notes":"Aero 3/4/5 tracks also specified in 20260902_Factsheet_IPSA.pdf#page=2.","source_ref":"https://www.ipsa.fr/en/programmes/exchange-programs/","source_type":"official_web","status":"verified","value":"Minimum 2 years of undergraduate study in Aerospace, Mechanical, Electronics Engineering, Robotics, or related fields required; home university nomination required (Aero 3 UG, Aero 4 Spring GR, Aero 5 Fall GR)."},"nomination_deadlines":{"notes":null,"source_ref":"data/raw/factsheets/IPSA France/20260902_Factsheet_IPSA.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"Fall 2026: Nomination Apr 15, 2026, Application May 15, 2026; Spring 2027: Nomination Oct 15, 2026, Application Nov 15, 2026."},"official_name":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:46","source_type":"excel_list","status":"verified","value":"Institut Polytechnique de Sciences Avancees (IPSA)"},"official_website_url":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:46","source_type":"excel_list","status":"verified","value":"https://www.ipsa.fr/en/"},"region":{"notes":"From normalized manifest country/region mapping","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:46","source_type":"excel_list","status":"verified","value":"Europe"},"required_application_docs":{"notes":null,"source_ref":"data/raw/factsheets/IPSA France/20260902_Factsheet_IPSA.pdf#page=1","source_type":"fact_sheet","status":"verified","value":["Home university nomination (via IPSA online form)","IPSA application form + Learning Agreement","Copy of passport","Academic transcripts (previous years + current year)","Proof of language proficiency (test certificate or home university letter)"]},"schema_version":"1.0.0","seat_quota":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"shard":1,"short_name":{"notes":"Official acronym used across 2026-2027 Fact Sheet p.1 and ipsa.fr.","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:46","source_type":"excel_list","status":"verified","value":"IPSA"},"slug":"institut-polytechnique-de-sciences-avancees-ipsa","spring_term_dates":{"notes":null,"source_ref":"data/raw/factsheets/IPSA France/20260902_Factsheet_IPSA.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"Spring 2027: Orientation days 1 week before program start; Undergraduate (Aero 3) mid-January – end of May; Graduate (Aero 4) February – June."},"state_or_province":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"tuition_model":{"notes":"AY 2026-2027 Fact Sheet p.2 Budget table explicitly lists Tuition fee: Waived for exchange students.","source_ref":"data/raw/factsheets/IPSA France/20260902_Factsheet_IPSA.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"auc_exchange_waiver"},"visa_lead_time_and_financial_proof":{"notes":null,"source_ref":"data/raw/factsheets/IPSA France/20260902_Factsheet_IPSA.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"Non-EU students staying 4 months to 1 year require a French VLS-TS long-stay student visa (50 EUR fee; official portal https://france-visas.gouv.fr/en/web/france-visas/). Processing lead time and exact EUR/month solvency proof vary by country/consulate via France-Visas."}}');
INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('institute-barcelona-d-estudis-internacionals-ibei', '[47]', 2, 'matched', '["data/raw/factsheets/IBEI/2021_2022/Academic_Calendar_21-22.pdf","data/raw/factsheets/IBEI/IBEI_ExchangeFactSheet_2021.pdf","data/raw/factsheets/IBEI/Institute Barcelona d''Estudis Internacionals 2023-24.pdf"]', '[]', 'Institute Barcelona d''Estudis Internacionals (IBEI)', 'IBEI', 'Spain', NULL, 'Barcelona', 'Europe', 'active', '["GR"]', 'Master/graduate-level exchange only; requires completed undergraduate degree / diploma and undergraduate + current graduate transcript.', 'GAPP only', '["GAPP"]', NULL, '["Core/Compulsory degree courses"]', NULL, '["English","Spanish"]', 'substantial', 'TOEFL iBT 90 (institution code 6567), IELTS 6.5, or Cambridge C1/C2. Exempt if native speaker or prior undergraduate degree was taught completely in English.', 'Spanish required only if selecting Spanish-taught electives.', '["Fall","Spring"]', 'AY 2026-2027 Semester 1: Welcome Day Sep 14, Shopping Week Sep 15-18, Semester Sep 23, 2026 - Jan 15, 2027 (Exams Jan 11-15, 2027).', 'AY 2026-2027 Semester 2: Jan 25 - May 28, 2027 (Exams May 24-28, 2027).', NULL, NULL, 'auc_exchange_waiver', 'EUR', 900, 1000, 5249.7, 'partial', 'Non-EU students must obtain private international medical insurance before travelling to Spain (EU students need EHIC).', 'assisted', 'Shared apartment rooms average EUR 450-650/month; partner discount options listed on ibei.org/en/accommodation-99859.', NULL, NULL, 'Non-EU exchange students require a Spanish Type D student visa for stays >90 days (up to 180 days visa; TIE card if >180 days); official details at https://www.ibei.org/en/visa-non-eu-students_125018.', 'http://www.ibei.org/', 'https://www.ibei.org/en/incoming-exchange-students-361952', 'https://www.ibei.org/en/elective-courses-for-exchange-students-361953', 'https://www.ibei.org/en/elective-courses-for-exchange-students-361953', 'ECTS credit system; full-time load approx. 10-20 ECTS per semester; electives carry 3-4 ECTS each (2-4 weekly teaching hrs); 0-10 grading scale (5.0 pass).', 'Restricted to IBEI graduate elective courses only (no compulsory core modules); requires course presentations + personal tutor approval; enrollment closes end of week 1.', '["Home university email nomination","Undergraduate diploma","Undergraduate academic transcript","Current academic transcript","Proof of English language proficiency","Brief motivation letter","CV","Passport","Photo"]', 'Small specialized graduate institute in International Affairs/Security/Public Policy on UPF Ciutadella campus; seminar courses assessed on 0-10 Spanish scale (5.0 pass).', NULL, NULL, NULL, 'International Mobility Office advising, Welcome Day & course shopping presentations, UPF language center link, and partner housing/in