INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('leiden-university', '[61]', 4, 'matched', '["data/raw/factsheets/Leiden University/1-Uniwide Leiden University Info Sheet 2024-2025.pdf","data/raw/factsheets/Leiden University/2-Process overview partner (1).pdf","data/raw/factsheets/Leiden University/3-Leiden University Nomination Instructions1.pdf","data/raw/factsheets/Leiden University/4-Application guidelines student.pdf","data/raw/factsheets/Leiden University/5-Brochure Study Abroad at Leiden University (4).pdf"]', '[]', 'Leiden University', NULL, 'Netherlands', NULL, 'Leiden', 'Europe', 'active', '["UG","GR"]', 'Must have completed at least 2 years of university education at partner institution and possess relevant academic background for chosen courses.', 'Faculty of Social and Behavioral Science, Faculty of Governance and Global Affairs and Faculty' || char(10) || 'of Humanities. Jul 15,2027', '["HUSS","GAPP"]', '["ALL"]', NULL, 3.2, '["Dutch","English"]', 'substantial', 'Minimum TOEFL iBT 90 or IELTS Academic 6.5 (Leiden University College The Hague requires TOEFL iBT 100 or IELTS 7.0); AUC''s Egyptian degree does not meet secondary-school native-English country exemptions.', 'None for English-taught courses; CEFR B2 Dutch required for Dutch-taught courses.', '["Fall","Spring"]', 'Fall / Semester 1: September – January (exact block/exam dates vary by faculty; consult faculty academic calendar).', 'Spring / Semester 2: February – June/July (exact block/exam dates vary by faculty; consult faculty academic calendar).', NULL, NULL, 'auc_exchange_waiver', 'EUR', 968, 1338, 6371.48, 'partial', 'Non-refundable €285 housing application fee (if applying for university housing); Dutch IND entry visa/residence permit processing fee applies to non-EU/EEA students (€210 on 2024-2025 Info Sheet, updated annually); compulsory health insurance required.', 'assisted', 'Limited DUWO accommodation (€425–€1,200/month incl. utilities), NOT guaranteed; €285 non-refundable application fee; apply by Apr 1 (Fall) or Oct 15 (Spring).', NULL, NULL, 'Leiden University submits residence permit/MVV applications on behalf of admitted non-EU/EEA students; 2026 Dutch IND proof-of-funds minimum is €1,150/month plus applicable IND fees.', 'https://www.universiteitleiden.nl/', 'https://www.universiteitleiden.nl/en/education/study-abroad-and-exchange', 'https://studiegids.universiteitleiden.nl/en/search?for=courses&q=exchange&edition', NULL, 'ECTS credit system; full-time workload is 30 ECTS per semester (minimum 15 ECTS; Faculty of Law capped at 15 ECTS).', 'Agreement scope limited to Faculties of Social and Behavioural Sciences, Governance and Global Affairs, and Humanities (through Jul 15, 2027); Law capped at 15 EC (outside scope); Psychology exams held in February with no alternative arrangements.', '["Online Leiden portal application","Supporting academic documents / official transcript","English proficiency proof (if required)","Course selection requests"]', 'Dutch/European research university (ECTS)', NULL, 'multi_campus', NULL, 'Schiphol airport Warm Welcome Service, OWL/HOP introduction weeks, Residence Life Assistants, Plexus (Leiden) & Beehive (The Hague) Student Centres, international student advisers, student psychologists, and Fenestra Disability Centre.', 'Fall / Full Year: Nomination Jan 1 – Mar 1 / Application Apr 1; Spring: Nomination Jul 15 – Sep 15 / Application Oct 15.', '{}', '{"academic_style":{"notes":null,"source_ref":"data/raw/factsheets/Leiden University/5-Brochure Study Abroad at Leiden University (4).pdf#page=2","source_type":"fact_sheet","status":"verified","value":"Dutch/European research university (ECTS)"},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:61","source_type":"excel_list","status":"verified","value":"Faculty of Social and Behavioral Science, Faculty of Governance and Global Affairs and Faculty\nof Humanities. Jul 15,2027"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:61","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:61","source_type":"excel_list","status":"verified","value":["UG","GR"]},"available_terms":{"notes":"Semester I: 31 August 2026 – 31 January 2027\nSemester II: 1 February 2027 – 4 July 2027 | Semester I: 31 August 2026 – 31 January 2027 Semester II: 1 February 2027 – 4 July 2027","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:61","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":"Brochure pages 1–2 state Leiden University is not campus-based and buildings/housing are spread across two cities: Leiden and The Hague.","source_ref":"data/raw/factsheets/Leiden University/5-Brochure Study Abroad at Leiden University (4).pdf#page=2","source_type":"fact_sheet","status":"verified","value":"multi_campus"},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:61","source_type":"excel_list","status":"verified","value":"Leiden"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:61","source_type":"excel_list","status":"verified","value":"Netherlands"},"course_catalog_url":{"notes":"Leiden Prospectus / Studiegids exchange course search URL from PDF annotation page 7.","source_ref":"data/raw/factsheets/Leiden University/1-Uniwide Leiden University Info Sheet 2024-2025.pdf#page=7","source_type":"fact_sheet","status":"verified","value":"https://studiegids.universiteitleiden.nl/en/search?for=courses&q=exchange&edition"},"course_restrictions_note":{"notes":"Academic constraints from 1-Uniwide Leiden University Info Sheet 2024-2025.pdf.","source_ref":"data/raw/partner_list_extracted.json#row=61","source_type":"excel_list","status":"verified","value":"Agreement scope limited to Faculties of Social and Behavioural Sciences, Governance and Global Affairs, and Humanities (through Jul 15, 2027); Law capped at 15 EC (outside scope); Psychology exams held in February with no alternative arrangements."},"credit_system_and_load":{"notes":"30 EC per semester max also noted on Leiden exchange tuition-fee page.","source_ref":"data/raw/factsheets/Leiden University/1-Uniwide Leiden University Info Sheet 2024-2025.pdf","source_type":"fact_sheet","status":"verified","value":"ECTS credit system; full-time workload is 30 ECTS per semester (minimum 15 ECTS; Faculty of Law capped at 15 ECTS)."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Excel row 61 specifies Faculty of Social and Behavioral Science, Faculty of Governance and Global Affairs, and Faculty of Humanities (Jul 15, 2027), mapping to AUC''s HUSS and GAPP.","source_ref":"data/raw/partner_list_extracted.json#row=61","source_type":"excel_list","status":"verified","value":["HUSS","GAPP"]},"eligible_majors":{"notes":"All majors eligible for coursework within Leiden''s agreed Faculties of Social and Behavioural Sciences, Governance and Global Affairs, and Humanities (valid until Jul 15, 2027), subject to academic background relevance and prerequisites.","source_ref":"data/raw/partner_list_extracted.json#row=61","source_type":"excel_list","status":"partial","value":["ALL"]},"english_course_availability":{"notes":"Wide selection of English-taught exchange courses alongside Dutch-taught degree offerings.","source_ref":"data/raw/factsheets/Leiden University/1-Uniwide Leiden University Info Sheet 2024-2025.pdf","source_type":"fact_sheet","status":"verified","value":"substantial"},"english_course_list_url":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":"90 TOEFL / 6.5 IELTS in Brochure page 1; LUC higher requirement and exemption rule in 1-Uniwide Info Sheet 2024-2025.pdf.","source_ref":"data/raw/factsheets/Leiden University/5-Brochure Study Abroad at Leiden University (4).pdf#page=1","source_type":"fact_sheet","status":"verified","value":"Minimum TOEFL iBT 90 or IELTS Academic 6.5 (Leiden University College The Hague requires TOEFL iBT 100 or IELTS 7.0); AUC''s Egyptian degree does not meet secondary-school native-English country exemptions."},"est_monthly_living_local":{"notes":"1-Uniwide Info Sheet 2024-2025 estimates €968–€1,338/month; note Leiden''s 2026 Dutch IND proof-of-funds