INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('louvain-school-of-management-uc-louvain', '[64,65]', 7, 'matched', '["data/raw/factsheets/UC Louvain/Partners_MOL_Guide.pdf"]', '[]', 'Louvain School of Management (UC Louvain)', 'UC Louvain', 'Belgium', NULL, 'Louvain-la-Neuve', 'Europe', 'active', '["GR"]', 'Graduate-level Master''s exchange (4th-5th university year) in Management and Business Engineering at Louvain School of Management.', 'Management and Business Administration', NULL, NULL, NULL, NULL, '["English","French"]', 'substantial', 'CEFR B2 level in English strongly recommended; accepted proofs include TOEFL, IELTS, OLS, or a home-university language center certificate (generally max 3 years old). RHET 1020 waiver not explicitly named.', 'No French proficiency required for English-taught LSM tracks; B2 French recommended if selecting French-taught courses. Free ILV French courses (up to 2 courses / max 8 ECTS) available.', '["Fall","Spring"]', 'LSM Fall Term: Mid-September to late January (Mandatory Orientation Day mid-September; 2026-2027 UCLouvain exchange schedule shows welcome week Sep 7-11, Orientation Sep 10, classes Sep 14-Dec 19, exams Jan 4-23, 2027).', 'LSM Spring Term: Late January / early February to late June (2026-2027 UCLouvain exchange schedule shows welcome week Jan 25-28, Orientation Jan 29, classes Feb 1-May 15, exams May 31-Jun 26/27, resits Aug 13-Sep 3, 2027).', NULL, NULL, 'auc_exchange_waiver', NULL, NULL, NULL, NULL, 'unknown', 'Tuition waived; mandatory EHIC (EU) or private international health insurance covering healthcare and medical repatriation in Belgium for non-EU students. Optional Sports Affiliation €60.', 'assisted', 'University rooms (LOGE): approx. €295/month; private 1-bedroom flats €600-€800/month (2-bedroom €750-€900/month). General non-rent expenses estimated at €350+/month (per uclouvain.be).', NULL, NULL, 'Non-EU/EEA nationals require a Belgian Long-stay Type D Student Visa using UCLouvain''s enrollment authorization; 2026-2027 statutory Belgian financial solvency minimum is €1,062 net/month (€12,744/12 months + admin fees via blocked account, scholarship, or Annex 32 guarantor).', 'https://uclouvain.be/en/faculties/lsm', 'https://uclouvain.be/en/colleges-institutes/lsm/incoming-exchange-students.html', 'https://uclouvain.be/en/edugo/catalogue-des-cours.html', NULL, 'ECTS credit system: standard full-time load is 30 ECTS per semester (typically up to 6 courses of 5 ECTS each; max 2 free ILV French courses totaling up to 8 ECTS).', NULL, '["Home university nomination in Mobility-Online","Online Mobility-Online application & Learning Agreement","Language proficiency proof (B2 English recommended)","Passport / ID copy","Health insurance proof (EHIC or non-EU repatriation policy)"]', 'Graduate management training combining lectures with group project work, continuous evaluation, and mandatory attendance in LSM Master''s courses.', NULL, NULL, NULL, 'Mandatory LSM Orientation Day, Welcome Weeks, free ILV French language courses (up to 8 ECTS), and UCLouvain mobility coordinators (https://uclouvain.be/en/study/les-coordonnateurs-de-mobilite-a-l-ucl.html).', 'LSM incoming exchange nomination/registration deadlines: May 15 (Fall Term / Full Academic Year); Nov 15 (Spring Term).', '{}', '{"academic_style":{"notes":null,"source_ref":"https://uclouvain.be/en/colleges-institutes/lsm/incoming-exchange-students.html","source_type":"official_web","status":"verified","value":"Graduate management training combining lectures with group project work, continuous evaluation, and mandatory attendance in LSM Master''s courses."},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:64,65","source_type":"excel_list","status":"verified","value":"Management and Business Administration"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:64,65","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:64,65","source_type":"excel_list","status":"verified","value":["GR"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:64,65","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:64,65","source_type":"excel_list","status":"verified","value":"Louvain-la-Neuve"},"city_tier":{"notes":null,"sour