INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('maastricht-university-school-of-business-and-economics', '[67]', 5, 'blocked', '[]', '[]', 'Maastricht University, School of Business and Economics', 'Maastricht University SBE', 'Netherlands', NULL, 'Maastricht', 'Europe', 'active', '["UG","GR"]', NULL, 'BUS', '["BUS"]', NULL, NULL, NULL, '["English"]', 'full', NULL, NULL, '["Fall","Spring"]', 'Fall Semester 2026: Period 1 Aug 31 - Oct 23, 2026; Period 2 Oct 26 - Dec 18, 2026; Period 3 (skills period) Jan 4 - Jan 29, 2027.', 'Spring Semester 2027: Period 4 Feb 1 - Apr 2, 2027; Period 5 Apr 5 - Jun 4, 2027 (select faculties start Period 5 Mar 29; Period 6 follows in June).', NULL, NULL, 'auc_exchange_waiver', 'EUR', 1306.0, 1462.0, 7647.98, 'partial', 'Tuition fees are waived for nominated partner exchange students (non-partner fee-paying freemover exchange is not permitted at SBE). Non-EEA visa/residence permit applicants incur Dutch IND administrative fees (est. ~EUR 250+). Health insurance coverage is mandatory (UM Nibud table cites EUR 156/month; semester optional insurance/books/misc noted at ~EUR 300-500).', 'assisted', 'UM Guesthouse offers furnished single/double rooms and studios (minimum 3-month stay for exchange students; semester housing estimates ~EUR 3,600-6,200) via https://www.maastrichtuniversity.nl/about-um/um-guesthouse-and-maastrichthousingcom. Reservations require a 30-day rent down payment and one-time cleaning fee of EUR 60, EUR 75, or EUR 100.', NULL, NULL, 'Non-EU/EEA students staying >90 days require an MVV entry visa and/or VVR residence permit submitted by Maastricht University as recognized IND sponsor (visa@maastrichtuniversity.nl). Applicants must show financial proof of EUR 1,250/month (e.g., EUR 6,250 for 5 months; EUR 15,000 for 12 months) via bank statements, scholarship, sponsorship, or refundable UM living-allowance deposit.', 'https://www.maastrichtuniversity.nl/about-um/faculties/school-business-and-economics', 'https://www.maastrichtuniversity.nl/education/exchange/sbe', 'https://www.maastrichtuniversity.nl/sbe/course-descriptions-application', 'https://www.maastrichtuniversity.nl/sbe/course-descriptions-application', 'ECTS credit system; standard full-time semester workload at Maastricht University is 30 ECTS across modular periods.', 'Only students officially nominated by an active SBE partner university may attend SBE on exchange (freemover / non-partner fee-paying study abroad students cannot enroll at SBE).', '["Home university official partner nomination","SBE online exchange registration/application"]', 'Small-group Problem-Based Learning (PBL) tutorial system (~12-15 students per group) emphasizing active discussion, case work, and modular 8-week periods plus optional 2-week skills periods.', NULL, NULL, NULL, 'UM Visa Office (visa@maastrichtuniversity.nl), SBE International Relations Office, and UM Guesthouse / Maastricht Housing services.', 'Fall semester: Nomination April 15; Application May 1. Spring semester: Nomination September 15; Application October 1.', '{}', '{"academic_style":{"notes":null,"source_ref":"https://www.maastrichtuniversity.nl/education/exchange/sbe","source_type":"official_web","status":"verified","value":"Small-group Problem-Based Learning (PBL) tutorial system (~12-15 students per group) emphasizing active discussion, case work, and modular 8-week periods plus optional 2-week skills periods."},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:67","source_type":"excel_list","status":"verified","value":"BUS"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:67","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:67","source_type":"excel_list","status":"verified","value":["UG","GR"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:67","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:67","source_type":"excel_list","status":"verified","value":"Maastricht"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:67","source_type":"excel_list","status":"verified","value":"Netherlands"},"course_catalog_url":{"notes":null,"source_ref":"https://www.maastrichtuniversity.nl/sbe/course-descriptions-application","source_type":"official_web","status":"verified","value":"https://www.maastrichtuniversity.nl/sbe/course-descriptions-application"},"course_restrictions_note":{"notes":null,"source_ref":"https://www.maastrichtuniversity.nl/education/bachelor/exchanges-sbe","source_type":"official_web","status":"partial","value":"Only students officially nominated by an active SBE partner university may attend SBE on exchange (freemover / non-partner fee-paying study abroad students cannot enroll at SBE)."},"credit_system_and_load":{"notes":null,"source_ref":"https://www.maastrichtuniversity.nl/education/exchange/sbe","source_type":"official_web","status":"partial","value":"ECTS credit system; standard full-time semester workload at Maastricht University is 30 ECTS across modular periods."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Excel agreement scope states ''BUS''.","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:67","source_type":"excel_list","status":"verified","value":["BUS"]},"eligible_majors":{"notes":"Excel agreement scope specifies AUC School ''BUS'' rather than specific majors.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_course_availability":{"notes":"SBE exchange curriculum is taught in English via Problem-Based Learning (PBL).","source_ref":"https://www.maastrichtuniversity.nl/education/exchange/sbe","source_type":"official_web","status":"verified","value":"full"},"english_course_list_url":{"notes":"Filter by SBE / Non-Degree / Exchange tracks in the UM Course Descriptions Application.","source_ref":"https://www.maastrichtuniversity.nl/sbe/course-descriptions-application","source_type":"official_web","status":"verified","value":"https://www.maastrichtuniversity.nl/sbe/course-descriptions-application"},"english_proficiency_and_rhet1020":{"notes":"SBE utilizes English-taught Problem-Based Learning tutorials requiring strong English proficiency, but exact official SBE numeric test cutoffs or RHET 1020 waiver rules are not directly published on https://www.maastrichtuniversity.nl/education/exchange/sbe (local Drive fact sheet folder is blocked).","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"est_monthly_living_local":{"notes":"Derived from UM official Nibud monthly student expense breakdown: Rent EUR 561 + Groceries EUR 272 + Books/materials EUR 53 + Transport EUR 67 + Leisure/sports EUR 238 + Clothing EUR 60 + Phone/internet EUR 55 = EUR 1,306/month excluding health insurance, or EUR 1,462/month including EUR 156/month health insurance. Separately, Dutch IND visa proof of means is EUR 1,250/month.","source_ref":"https://www.maastrichtuniversity.nl/support/your-studies-begin/cost-studying-financial-assistance","source_type":"official_web","status":"partial","value":{"currency":"EUR","max":1462.0,"min":1306.0}},"excel_rows":[67],"exchange_page_url":{"notes":"See also SBE Bachelor exchange overview: https://www.maastrichtuniversity.nl/education/bachelor/exchanges-sbe.","source_ref":"https://www.maastrichtuniversity.nl/education/exchange/sbe","source_type":"official_web","status":"verified","value":"https://www.maastrichtuniversity.nl/education/exchange/sbe"},"excluded_majors":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"ext":{},"fact_sheet_status":{"drive_links":["https://drive.google.com/open?id=1lYmu7tfrCQ-Eldk1XI3N-5qGBMqfy4FQ"],"extracted_files":[],"local_files":[],"match_status":"blocked","notes":"Col H link (1lYmu7tfrCQ-Eldk1XI3N-5qGBMqfy4FQ) unreachable (error_html_response: Drive returned HTML page instead of document payload)"},"fall_term_dates":{"notes":null,"source_ref":"https://www.maastrichtuniversity.nl/sites/default/files/2026-08/Student%20handbook%202026-2027.pdf","source_type":"official_web","status":"verified","value":"Fall Semester 2026: Period 1 Aug 31 - Oct 23, 2026; Period 2 Oct 26 - Dec 18, 2026; Period 3 (skills period) Jan 4 - Jan 29, 2027."},"final_semester_allowed":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_grants_or_stipends":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_language_requirement":{"notes":"Classes are taught in English; no official Dutch language requirement stated for SBE exchange.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"housing_availability":{"notes":"Students book furnished short-stay UM Guesthouse rooms or private rooms through Maastricht Housing portal on a first-come, first-served basis.","source_ref":"https://www.maastrichtuniversity.nl/support/um-guesthouse","source_type":"official_web","status":"verified","value":"assisted"},"housing_notes":{"notes":null,"source_ref":"https://www.maastrichtuniversity.nl/support/um-guesthouse","source_type":"official_web","status":"verified","value":"UM Guesthouse offers furnished single/double rooms and studios (minimum 3-month stay for exchange students; semester housing estimates ~EUR 3,600-6,200) via https://www.maastrichtuniversity.nl/about-um/um-guesthouse-and-maastrichthousingcom. Reservations require a 30-day rent down payment and one-time cleaning fee of EUR 60, EUR 75, or EUR 100."},"instruction_languages":{"notes":null,"source_ref":"https://www.maastrichtuniversity.nl/education/exchange/sbe","source_type":"official_web","status":"verified","value":["English"]},"international_support_services":{"notes":null,"source_ref":"https://www.maastrichtuniversity.nl/support/your-studies-begin/coming-maastricht-university-abroad/visa-and-residence-permit","source_type":"official_web","status":"partial","value":"UM Visa Office (visa@maastrichtuniversity.nl), SBE International Relations Office, and UM Guesthouse / Maastricht Housing services."},"living_cost_usd_est":{"notes":"Midpoint EUR 1,384.00/month (EUR 1,306 excl. insurance to EUR 1,462 incl. EUR 156/mo health insurance from UM Nibud breakdown) * 5 months = EUR 6,920.00; converted at ECB 2026-11-13 rate (collected 2026-11-15) 1 EUR = 1.1052 USD (https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html) = 7,647.98 USD.","source_ref":"https://www.maastrichtuniversity.nl/support/your-studies-begin/cost-studying-financial-assistance","source_type":"official_web","status":"partial","value":7647.98},"mandatory_host_fees_and_insurance":{"notes":"Nibud health insurance reference from https://www.maastrichtuniversity.nl/support/your-studies-begin/cost-studying-financial-assistance.","source_ref":"https://www.maastrichtuniversity.nl/education/exchange/sbe","source_type":"official_web","status":"partial","value":"Tuition fees are waived for nominated partner exchange students (non-partner fee-paying freemover exchange is not permitted at SBE). Non-EEA visa/residence permit applicants incur Dutch IND administrative fees (est. ~EUR 250+). Health insurance coverage is mandatory (UM Nibud table cites EUR 156/month; semester optional insurance/books/misc noted at ~EUR 300-500)."},"min_gpa_host":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"min_standing_note":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"nomination_deadlines":{"notes":null,"source_ref":"https://www.maastrichtuniversity.nl/education/exchange/sbe","source_type":"official_web","status":"verified","value":"Fall semester: Nomination April 15; Application May 1. Spring semester: Nomination September 15; Application October 1."},"official_name":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:67","source_type":"excel_list","status":"verified","value":"Maastricht University, School of Business and Economics"},"official_website_url":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:67","source_type":"excel_list","status":"verified","value":"https://www.maastrichtuniversity.nl/about-um/faculties/school-business-and-economics"},"region":{"notes":"From normalized manifest country/region mapping","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:67","source_type":"excel_list","status":"verified","value":"Europe"},"required_application_docs":{"notes":"Local Drive fact sheet folder is blocked; full checklist is sent post-nomination.","source_ref":"https://www.maastrichtuniversity.nl/education/exchange/sbe","source_type":"official_web","status":"partial","value":["Home university official partner nomination","SBE online exchange registration/application"]},"schema_version":"1.0.0","seat_quota":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"shard":5,"short_name":{"notes":null,"source_ref":"https://www.maastrichtuniversity.nl/sbe","source_type":"official_web","status":"verified","value":"Maastricht University SBE"},"slug":"maastricht-university-school-of-business-and-economics","spring_term_dates":{"notes":null,"source_ref":"https://www.maastrichtuniversity.nl/sites/default/files/2026-08/Student%20handbook%202026-2027.pdf","source_type":"official_web","status":"verified","value":"Spring Semester 2027: Period 4 Feb 1 - Apr 2, 2027; Period 5 Apr 5 - Jun 4, 2027 (select faculties start Period 5 Mar 29; Period 6 follows in June)."},"state_or_province":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"tuition_model":{"notes":"Incoming exchange students officially nominated by a partner university do not pay tuition fees to Maastricht University''s SBE and continue paying tuition to their home university.","source_ref":"https://www.maastrichtuniversity.nl/education/exchange/sbe","source_type":"official_web","status":"verified","value":"auc_exchange_waiver"},"visa_lead_time_and_financial_proof":{"notes":null,"source_ref":"https://www.maastrichtuniversity.nl/support/your-studies-begin/coming-maastricht-university-abroad/visa-and-residence-permit","source_type":"official_web","status":"verified","value":"Non-EU/EEA students staying >90 days require an MVV entry visa and/or VVR residence permit submitted by Maastricht University as recognized IND sponsor (visa@maastrichtuniversity.nl). Applicants must show financial proof of EUR 1,250/month (e.g., EUR 6,250 for 5 months; EUR 15,000 for 12 months) via bank statements, scholarship, sponsorship, or refundable UM living-allowance deposit."}}');
INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('marquette-university', '[68]', 1, 'matched', '["data/raw/factsheets/Marquette University/2020_2021/Marquette University.docx","data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx"]', '[]', 'Marquette University', NULL, 'United States', 'Wisconsin', 'Milwaukee', 'North America', 'active', '["UG","GR"]', 'Official partner nomination required; GPA requirement depends upon field of study and home country grading system. Students living in traditional residence halls are preferred to be <=20 years old and within their first two years of university study.', 'University-wide', '["ALL"]', '["ALL"]', '["Law (restricted to law school exchange programs)","AFAS / Air Force Aerospace Studies","Dentistry / Dental specialties (DECS, DEDS, DEGD, DEIN, DENT, DESS)","Military & Naval Science (MISL, MLSC, NASC)","Physician Assistant Studies & Physical Therapy (PHAS, PHTH)","EXBU, FIAR, LEAD courses"]', NULL, '["English"]', 'full', 'Undergraduate exchange: TOEFL iBT >=80 (min 18/section), IELTS >=6.5 (min 6.5/section), TOEFL ITP >=550 (min 50/section), Cambridge B2/C1/C2 (R/L/S 180, W 175), Duolingo >=115 (min 110 subscore), OR home-university documentation that >=50% of university-level coursework was instructed in English (or objective home-university proficiency letter on case-by-case basis). Graduate requirements vary by program. RHET 1020 not mentioned; AUC''s >=50% English instruction documentation satisfies the UG waiver rule.', NULL, '["Fall","Spring"]', 'Fall 2026: Arrival 20–23 Aug 2026; Mandatory International Orientation 24–26 Aug 2026; UG/Grad classes start 31 Aug 2026; Fall Break 22–23 Oct; Thanksgiving Break 25–27 Nov; Final Exams 14–19 Dec 2026 (Law: orientation 20–21 Aug, classes 24 Aug, exams 7–18 Dec 2026).', 'Spring 2027: Arrival 7–12 Jan 2027; Mandatory Orientation 13–15 Jan 2027; UG/Grad/Law classes start 19 Jan 2027; Spring & Easter Break 22–29 Mar 2027 (Law: 8–14 Mar); Final Exams 10–15 May 2027 (Law: 3–14 May 2027).', NULL, NULL, NULL, 'USD', 2772, 2772, 13861.11, 'partial', 'Mandatory Marquette University health insurance: all exchange students are automatically enrolled and billed for their entire period of study (AY 2026-27 Fact Sheet; waivers strictly restricted per https://www.marquette.edu/oie/health-insurance.php; OIE notes ~USD 250/month baseline plan cost, included in OIE living budget alongside 2-term student fees with city bus pass).', 'assisted', 'Rank preferences inside online application by application deadline (Mar 15 Fall / Oct 15 Spring); first-choice not guaranteed. Options: (1) Global Village / Campus Town Apartments (https://www.marquette.edu/residence-life/apartments-global-village.php) — furnished 2BR/4-student shared apartments, heat/water included, UG priority, more available in Spring; (2) Residence Halls (https://www.marquette.edu/residence-life/residence-halls.php) — mandatory meal plan, preferred <=20 yrs & first 2 yrs; (3) Off-campus assistance near campus (https://www.marquette.edu/offcampus/).', NULL, NULL, 'J-1 student visa documents are emailed after acceptance, typically after April 1 (Fall) or November 1 (Spring) (AY 2026-27 Fact Sheet; http://www.marquette.edu/oie/admitted-students/visa.shtml). Financial sponsorship form and support proof uploaded in https://studyabroad.marquette.edu/?go=incoming; OIE 2026-27 annual living expense basis for F-1/J-1 certification is USD 24,950 (+ USD 12,000 spouse / USD 6,000 per child) per https://www.marquette.edu/international-education/tuition-and-costs.php.', 'http://www.marquette.edu/', 'https://studyabroad.marquette.edu/?go=incoming', 'https://bulletin.marquette.edu/azindex/', NULL, 'US semester hours on 4.0 GPA scale (A=4.0, A-=3.67, B+=3.33, B=3.00, etc.). Full-time load: UG & Law 12–18 credits/semester (Business exchange students should only take 3-credit courses); Graduate 7–9 credits/semester.', 'Enrolled by respective college from application Course Approval Form (not guaranteed); add/drop needs prerequisite verification or permission via OIE (Tammy.Meyers@marquette.edu). Excluded: AFAS, DECS, DEDS, DEGD, DEIN, DENT, DESS, EXBU, FIAR, LEAD, MISL, MLSC, NASC, PHAS, PHTH; LAW restricted to law exchange; Business students restricted to 3-credit courses.', '["Online application at https://studyabroad.marquette.edu/?go=incoming","Courses of interest / Course Approval Form","Proof of English language proficiency","Financial sponsorship form and support documentation","Academic transcripts (per OIE application portal)","Housing preference ranking"]', 'US comprehensive Catholic/Jesuit research university (~7,600 UG, ~3,700 graduate/professional students) on 4.0 grading scale; internships/Academic Training possible; official digital transcript sent automatically ~2 weeks after semester grades post.', NULL, NULL, NULL, 'Mandatory International Orientation (https://www.marquette.edu/oie/admitted-students/orientation.php), OIE (https://www.marquette.edu/oie/index.php) advising & J-1 Responsible Officer (Michael Groen), Medical Clinic (https://www.marquette.edu/medical-clinic/), Counseling Center (https://www.marquette.edu/counseling-center/), Disability Services (https://www.marquette.edu/disability-services/), Campus Police (https://www.marquette.edu/mupd/), Student Organizations (https://marquette.presence.io/organizations), Service Learning (https://www.marquette.edu/service-learning/).', 'Application deadlines: Fall semester 15 March; Spring semester 15 October (exceptions case-by-case).', '{}', '{"academic_style":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"US comprehensive Catholic/Jesuit research university (~7,600 UG, ~3,700 graduate/professional students) on 4.0 grading scale; internships/Academic Training possible; official digital transcript sent automatically ~2 weeks after semester grades post."},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:68","source_type":"excel_list","status":"verified","value":"University-wide"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:68","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:68","source_type":"excel_list","status":"verified","value":["UG","GR"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:68","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:68","source_type":"excel_list","status":"verified","value":"Milwaukee"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:68","source_type":"excel_list","status":"verified","value":"United States"},"course_catalog_url":{"notes":"Specific term offerings at https://bulletin.marquette.edu/class-search/; college/department sites at https://www.marquette.edu/academics/","source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"https://bulletin.marquette.edu/azindex/"},"course_restrictions_note":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"Enrolled by respective college from application Course Approval Form (not guaranteed); add/drop needs prerequisite verification or permission via OIE (Tammy.Meyers@marquette.edu). Excluded: AFAS, DECS, DEDS, DEGD, DEIN, DENT, DESS, EXBU, FIAR, LEAD, MISL, MLSC, NASC, PHAS, PHTH; LAW restricted to law exchange; Business students restricted to 3-credit courses."},"credit_system_and_load":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"US semester hours on 4.0 GPA scale (A=4.0, A-=3.67, B+=3.33, B=3.00, etc.). Full-time load: UG & Law 12–18 credits/semester (Business exchange students should only take 3-credit courses); Graduate 7–9 credits/semester."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Excel agreement_scope_raw is ''University-wide''; AY 2026-27 Fact Sheet excludes specific course codes (AFAS, DECS, DEDS, DEGD, DEIN, DENT, DESS, EXBU, FIAR, LEAD, MISL, MLSC, NASC, PHAS, PHTH) and restricts LAW to law exchange students.","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:68","source_type":"excel_list","status":"partial","value":["ALL"]},"eligible_majors":{"notes":"University-wide agreement subject to AY 2026-27 Fact Sheet excluded course prefixes and Law exchange restrictions.","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:68","source_type":"excel_list","status":"partial","value":["ALL"]},"english_course_availability":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"full"},"english_course_list_url":{"notes":"Instruction is in English; term course offerings searchable at https://bulletin.marquette.edu/class-search/.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"Undergraduate exchange: TOEFL iBT >=80 (min 18/section), IELTS >=6.5 (min 6.5/section), TOEFL ITP >=550 (min 50/section), Cambridge B2/C1/C2 (R/L/S 180, W 175), Duolingo >=115 (min 110 subscore), OR home-university documentation that >=50% of university-level coursework was instructed in English (or objective home-university proficiency letter on case-by-case basis). Graduate requirements vary by program. RHET 1020 not mentioned; AUC''s >=50% English instruction documentation satisfies the UG waiver rule."},"est_monthly_living_local":{"notes":"Derived from Marquette OIE 2026-27 Fall & Spring (2 terms, 9 months) Living Expenses estimate of USD 24,950 (shared residence hall, meals, 12-mo mandatory health insurance, books, 9-mo personal, 2-term fees incl. bus pass) divided by 9 months = USD 2,772.22/month.","source_ref":"https://www.marquette.edu/international-education/tuition-and-costs.php","source_type":"official_web","status":"partial","value":{"currency":"USD","max":2772,"min":2772}},"excel_rows":[68],"exchange_page_url":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"https://studyabroad.marquette.edu/?go=incoming"},"excluded_majors":{"notes":"AY 2026-27 Fact Sheet lists exact prohibited course prefixes and Law restriction; older 2020-21 Fact Sheet also noted Dentistry and Nursing unavailable and Health Science/Grad School limited.","source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":["Law (restricted to law school exchange programs)","AFAS / Air Force Aerospace Studies","Dentistry / Dental specialties (DECS, DEDS, DEGD, DEIN, DENT, DESS)","Military & Naval Science (MISL, MLSC, NASC)","Physician Assistant Studies & Physical Therapy (PHAS, PHTH)","EXBU, FIAR, LEAD courses"]},"ext":{},"fact_sheet_status":{"drive_links":["https://drive.google.com/drive/folders/1Rv4Bcv1ReGyPF-xeukkS9jontDpQ5GZ_"],"extracted_files":["data/raw/extracted/Marquette University/2020_2021/Marquette University.docx.txt","data/raw/extracted/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx.txt"],"local_files":["data/raw/factsheets/Marquette University/2020_2021/Marquette University.docx","data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx"],"match_status":"matched","notes":null},"fall_term_dates":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"Fall 2026: Arrival 20–23 Aug 2026; Mandatory International Orientation 24–26 Aug 2026; UG/Grad classes start 31 Aug 2026; Fall Break 22–23 Oct; Thanksgiving Break 25–27 Nov; Final Exams 14–19 Dec 2026 (Law: orientation 20–21 Aug, classes 24 Aug, exams 7–18 Dec 2026)."},"final_semester_allowed":{"notes":"Not stated in AY 2026-27 Fact Sheet.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_grants_or_stipends":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_language_requirement":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"housing_availability":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"assisted"},"housing_notes":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"Rank preferences inside online application by application deadline (Mar 15 Fall / Oct 15 Spring); first-choice not guaranteed. Options: (1) Global Village / Campus Town Apartments (https://www.marquette.edu/residence-life/apartments-global-village.php) — furnished 2BR/4-student shared apartments, heat/water included, UG priority, more available in Spring; (2) Residence Halls (https://www.marquette.edu/residence-life/residence-halls.php) — mandatory meal plan, preferred <=20 yrs & first 2 yrs; (3) Off-campus assistance near campus (https://www.marquette.edu/offcampus/)."},"instruction_languages":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":["English"]},"international_support_services":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"Mandatory International Orientation (https://www.marquette.edu/oie/admitted-students/orientation.php), OIE (https://www.marquette.edu/oie/index.php) advising & J-1 Responsible Officer (Michael Groen), Medical Clinic (https://www.marquette.edu/medical-clinic/), Counseling Center (https://www.marquette.edu/counseling-center/), Disability Services (https://www.marquette.edu/disability-services/), Campus Police (https://www.marquette.edu/mupd/), Student Organizations (https://marquette.presence.io/organizations), Service Learning (https://www.marquette.edu/service-learning/)."},"living_cost_usd_est":{"notes":"5-month USD estimate derived from Marquette OIE 2026-27 9-month Fall & Spring Living Expenses USD 24,950 (USD 2,772.22/month x 5 = USD 13,861.11; 1-semester half share = USD 12,475), verified 2026-11-15 (USD local currency; no FX conversion).","source_ref":"https://www.marquette.edu/international-education/tuition-and-costs.php","source_type":"official_web","status":"partial","value":13861.11},"mandatory_host_fees_and_insurance":{"notes":"Additional details from https://www.marquette.edu/oie/health-insurance.php and https://www.marquette.edu/international-education/tuition-and-costs.php.","source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"Mandatory Marquette University health insurance: all exchange students are automatically enrolled and billed for their entire period of study (AY 2026-27 Fact Sheet; waivers strictly restricted per https://www.marquette.edu/oie/health-insurance.php; OIE notes ~USD 250/month baseline plan cost, included in OIE living budget alongside 2-term student fees with city bus pass)."},"min_gpa_host":{"notes":"AY 2026-27 Fact Sheet explicitly states ''GPA Requirement: This is dependent upon field of study and home country grading system'' (no universal numerical cutoff stated).","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"min_standing_note":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"Official partner nomination required; GPA requirement depends upon field of study and home country grading system. Students living in traditional residence halls are preferred to be <=20 years old and within their first two years of university study."},"nomination_deadlines":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"Application deadlines: Fall semester 15 March; Spring semester 15 October (exceptions case-by-case)."},"official_name":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:68","source_type":"excel_list","status":"verified","value":"Marquette University"},"official_website_url":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:68","source_type":"excel_list","status":"verified","value":"http://www.marquette.edu/"},"region":{"notes":"From normalized manifest country/region mapping","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:68","source_type":"excel_list","status":"verified","value":"North America"},"required_application_docs":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":["Online application at https://studyabroad.marquette.edu/?go=incoming","Courses of interest / Course Approval Form","Proof of English language proficiency","Financial sponsorship form and support documentation","Academic transcripts (per OIE application portal)","Housing preference ranking"]},"schema_version":"1.0.0","seat_quota":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"shard":1,"short_name":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"slug":"marquette-university","spring_term_dates":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"Spring 2027: Arrival 7–12 Jan 2027; Mandatory Orientation 13–15 Jan 2027; UG/Grad/Law classes start 19 Jan 2027; Spring & Easter Break 22–29 Mar 2027 (Law: 8–14 Mar); Final Exams 10–15 May 2027 (Law: 3–14 May 2027)."},"state_or_province":{"notes":"Normalized from country_raw ''Wisconson'' in Excel list; city ''Milwaukee'' confirmed in Fact Sheet OIE address Milwaukee, WI.","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:68","source_type":"excel_list","status":"verified","value":"Wisconsin"},"tuition_model":{"notes":"Neither the 2026-27 Fact Sheet nor retrieved marquette.edu student exchange pages explicitly publish incoming exchange tuition-waiver wording.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"visa_lead_time_and_financial_proof":{"notes":null,"source_ref":"data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx","source_type":"fact_sheet","status":"verified","value":"J-1 student visa documents are emailed after acceptance, typically after April 1 (Fall) or November 1 (Spring) (AY 2026-27 Fact Sheet; http://www.marquette.edu/oie/admitted-students/visa.shtml). Financial sponsorship form and support proof uploaded in https://studyabroad.marquette.edu/?go=incoming; OIE 2026-27 annual living expense basis for F-1/J-1 certification is USD 24,950 (+ USD 12,000 spouse / USD 6,000 per child) per https://www.marquette.edu/international-education/tuition-and-costs.php."}}');
