INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('middle-tennessee-state-university', '[73]', 7, 'none', '[]', '[]', 'Middle Tennessee State University', 'MTSU', 'United States', 'Tennessee', 'Murfreesboro', 'North America', 'active', '["UG"]', NULL, 'University-wide', '["ALL"]', '["ALL"]', NULL, 2.5, '["English"]', 'full', 'Official test scores must be sent directly by testing service (waived only if English is the native language of citizenship): UG TOEFL iBT 61 (ITP 500, Essentials 6.5), IELTS 5.5, or Duolingo 85; GR TOEFL iBT 71, IELTS 6.0, or Duolingo 95. No RHET 1020 waiver stated.', NULL, '["Fall","Spring"]', 'AY 2026-2027 Fall full-term classes begin Aug 24, 2026 (full-term runs Aug 24-Dec 10, 2026 per mtsu.edu Fee/Registration calendar).', 'AY 2026-2027 Spring: Jan 19-May 6, 2027 (Last day of classes Apr 28, 2027; Spring Break Mar 8-13, 2027).', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unknown', 'Mandatory J-1 health insurance required by US Dept of State regulations ($100,000+ medical benefits, $50,000 medical evacuation, $25,000 repatriation of remains) plus mandatory immunizations (MMR, Varicella, Meningitis under 22 on-campus, TB screening, Hepatitis B).', 'assisted', 'Incoming students complete the Residential Life online housing application as early as possible after admission; Campus Housing coordinates reserved spaces via Education Abroad (https://www.mtsu.edu/studyabroad/housing.php).', NULL, NULL, 'J-1 non-immigrant visa required for all incoming exchange students. Requires Financial Support Form + official bank verification proving >=$13,000/year ($6,500/semester) for Tuition-Only Exchange agreements (or >=$4,500/year, $2,500/semester for Full Exchange).', 'https://www.mtsu.edu/', 'https://www.mtsu.edu/programs/international/exchange-incoming.php', 'https://www.mtsu.edu/ucat/', 'https://www.mtsu.edu/ucat/', NULL, NULL, '["Home university nomination","MTSU Studio Abroad online application","Official transcript","Official English test score report (TOEFL/IELTS/Duolingo)","Financial Support Form + bank verification letter","Passport copy","Immunization records via MTSU Patient Portal","Residential Life Housing Application"]', NULL, NULL, NULL, NULL, NULL, 'Fall / Full Year: Nomination Mar 1, Application materials Apr 15; Spring: Nomination Oct 1, Application materials Oct 31.', '{}', '{"academic_style":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:73","source_type":"excel_list","status":"verified","value":"University-wide"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:73","source_type":"excel_list","status":"verified","value":"active"},"agreement_s