INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('north-carolina-state-university', '[77]', 7, 'matched', '["data/raw/factsheets/North Carolina State/2024-2025/AY 2024-2025 Fact Sheet - Incoming Exchange - Study Abroad Office.pdf"]', '[]', 'North Carolina State University', 'NC State', 'United States', 'North Carolina', 'Raleigh', 'North America', 'active', '["UG","GR"]', NULL, 'University-wide', '["ALL"]', '["ALL"]', '["Biomedical Engineering","Veterinary Medicine"]', NULL, '["English"]', 'full', 'TOEFL iBT 80 (min 18 subscores; MBA requires 100), IELTS 6.5 (min 6.0 UG / 6.5 GR; MBA 7.5), Duolingo 110, OR official home-university letter confirming completion of >=1 semester of English-taught study at a 4-year university (RHET 1020 not named specifically, but English-medium university instruction exemption explicitly applies).', NULL, '["Fall","Spring"]', 'AY 2026-2027 Fall: First day of classes Aug 17, 2026; Last day of classes Dec 1, 2026; Final exams Dec 3-9, 2026.', 'AY 2026-2027 Spring: First day of classes Jan 11, 2027; Last day of classes Apr 27, 2027; Final exams Apr 29-May 5, 2027.', NULL, NULL, 'auc_exchange_waiver', NULL, NULL, NULL, NULL, 'unknown', 'AY 2026-2027 incoming exchange costs: Mandatory Health Insurance $773.18/semester (Global Solutions Plan); SEVIS fee $220; ResNet internet $140 (on-campus residents); optional streaming/cable ~$35; Books $400-$600. Immunizations and HealthWeb compliance required.', 'assisted', 'AY 2026-2027 on-campus housing: $3,970/semester (shared residence hall room) to $4,780/semester (Wolf Village apartment); meal plans $800-$3,176/semester (apply via https://housing.dasa.ncsu.edu/).', NULL, NULL, 'J-1 visa ONLY (NC State does not issue F-1 visas for exchange students); submit DS-2019 request in Global Home with passport and official proof of funding covering living expenses, insurance, and fees. Mandatory OIS immigration check-in at orientation.', 'https://www.ncsu.edu/', 'https://studyabroad.ncsu.edu/incoming-exchange-student/', 'https://www.acs.ncsu.edu/php/coursecat/', 'https://www.acs.ncsu.edu/php/coursecat/', 'US credit hours: full-time minimum is 12 credits/semester (UG) or 9 credits/semester (GR). Grading A-F.', 'Excluded: College of Veterinary Medicine and Biomedical Engineering. Must declare a major field and take the majority of courses in that major. Final semester NOT recommended if specific required courses or thesis work are needed for graduation.', '["Home university nomination","Online NC State exchange application","Official English academic transcript","Passport copy","English proficiency proof (test score or home univ English-instruction letter)","DS-2019 request + proof of funding in Global Home (post-nomination)"]', 'Large public research university (>35,000 students in Raleigh, NC) using continuous semester coursework and A-F grading within a declared primary major.', NULL, NULL, NULL, 'Mandatory orientation and OIS immigration check-in; Study Abroad Office pre-arrival advising and MyPack/Global Home support.', 'Fall 2026: Nomination Feb 2-Mar 1, 2026; Application Mar 15, 2026. Spring 2027: Nomination Sep 1-Oct 1, 2026; Application Oct 15, 2026.', '{}', '{"academic_style":{"notes":null,"source_ref":"data/raw/factsheets/North Carolina State/2024-2025/AY 2024-2025 Fact Sheet - Incoming Exchange - Study Abroad Office.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"Large public research university (>35,000 students in Raleigh, NC) using continuous semester coursework and A-F grading within a declared primary major."},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:77","source_type":"excel_list","status":"verified","value":"University-wide"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:77","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:77","source_type":"excel_list","status":"verified","value":["UG","GR"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:77","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:77","source_type":"excel_list","status":"verified","value":"Raleigh"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_