INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('richmond-american-university-london-raul', '[95]', 5, 'matched', '["data/raw/factsheets/Richmond American University, London/2022/study-abroad-visiting-students-2022-web.pdf","data/raw/factsheets/Richmond American University, London/Fall 2026/FALL 2026 Course List.pdf","data/raw/factsheets/Richmond University/2024-2025/International Programmes VS Factsheet - Maggie Burton.docx","data/raw/factsheets/Richmond University/2024-2025/International Programmes VS Factsheet - Maggie Burton.pdf","data/raw/factsheets/Richmond University/2026-2027/Richmond Factsheet - STUDY ABROAD.docx"]', '[]', 'Richmond American University London (RAUL)', 'RAUL', 'United Kingdom', NULL, 'Richmond', 'Europe', 'active', '["UG","GR"]', NULL, 'University-wide', '["ALL"]', '["ALL"]', NULL, NULL, '["English"]', 'full', 'Required for non-native speakers per https://www.richmond.ac.uk/undergraduate-admissions/: IELTS Academic 5.5 (min 5.5 all 4 components), TOEFL iBT 72 (17L/18R/17W/20S), PTE Academic 51 (51 all components), Oxford ELLT B2 in all 4 components, or Cambridge Scale min 168 per skill (2024-25 Factsheet p.2). RHET 1020 waiver not explicitly mentioned.', 'English (CEFR B2 equivalent scores required for non-native English speakers).', '["Fall","Spring"]', 'Fall 2026: Orientation Sep 1-6, 2026; Classes Sep 7 - Dec 11, 2026 (Tutorial Week Oct 26 - Nov 1, no classes); Exams Dec 14-18, 2026.', 'Spring 2027: Orientation Jan 11-17, 2027; Classes Jan 18 - Apr 23, 2027 (Tutorial Week Mar 8-14, no classes); Exams Apr 26 - May 2, 2027.', NULL, NULL, 'fee_paying_study_abroad', NULL, NULL, NULL, NULL, 'unknown', '2026-27 Study Abroad tuition is GBP 6,300/semester (GBP 5,355/semester with partner discount); healthcare coverage guidance is linked inside the Study Abroad factsheet.', 'guaranteed', 'Partnered accommodation at The Stay Club North Acton (private en-suite single studios with kitchenettes, utilities, Wi-Fi, RA/RD support, optional meal plan). 2026-27 visitor rates incl. council tax: GBP 445/week (1-term, 16-week contract) or GBP 414/week (2-term, 35-week contract), plus GBP 250 deposit. Guarantee deadline Jun 1 (Fall) / Oct 11 (Spring).', NULL, NULL, 'Single-semester (<6 months) students enter as Standard Visitors and must obtain a UK Electronic Travel Authorization (ETA) before travel (or apply prior if visa-national). Stays >6 months require a UK Student Visa (no ETA needed; English proof requirements apply).', 'https://www.richmond.ac.uk/', 'https://www.richmond.ac.uk/', NULL, NULL, 'US credit system: all Study Abroad classes at RAUL are 4 US credits each.', 'Academic advisors verify prerequisites ahead of registration; students are advised to have 4 backup courses pre-approved for Add/Drop adjustments.', '["Home university nomination (sent to International Programmes team)","Online portal application","Scanned copies of all academic transcripts (in English)","Scanned English proficiency scores (for non-native speakers)","Colour scan of passport photo page"]', 'Dual US (Middle States) and UK (Taught Degree Awarding Powers) liberal arts university featuring small classes, US credit transferability, Tutorial Weeks, and optional 4-credit London internships.', NULL, NULL, NULL, 'International Programmes advising team (pre-arrival Teams course advising), Stay Club Resident Assistants/Resident Directors (RA/RD), Student Affairs wellbeing support (TalkCampus).', 'Fall 2026: Nomination May 15, Application Jun 1 (Housing guarantee Jun 1). Spring 2027: Nomination Oct 15, Application Nov 1 (Housing guarantee Oct 11).', '{}', '{"academic_style":{"notes":"Dual accreditation & 4-credit internship on p.4 & p.15; Tutorial Week in data/raw/factsheets/Richmond University/2026-2027/Richmond Factsheet - STUDY ABROAD.docx.","source_ref":"data/raw/factsheets/Richmond American University, London/2022/study-abroad-visiting-students-2022-web.pdf#page=4","source_type":"fact_sheet","status":"verified","value":"Dual US (Middle States) and UK (Taught Degree Awarding Powers) liberal arts university featuring small classes, US credit transferability, Tutorial Weeks, and optional 4-credit London internships."},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:95","source_type":"excel_list","status":"verified","value":"University-wide"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:95","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:95","source_type":"excel_list","status":"verified","value":["UG","GR"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Univ