INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('sciences-po-institute-d-etudes-politiques-de-paris', '[99]', 8, 'matched', '["data/raw/factsheets/Sciences Po/2024-2025/Sciences Po.pdf","data/raw/factsheets/Sciences Po/2025-2026/factsheet2025-2026.pdf","data/raw/factsheets/Sciences Po/Useful Info. Science Po.docx"]', '[]', 'Sciences Po (Institute d''Etudes Politiques de Paris)', 'Sciences Po', 'France', NULL, 'Paris', 'Europe', 'active', '["UG","GR"]', 'Undergraduate exchange: >=4 completed semesters of undergraduate study. Graduate exchange: Bachelor''s degree or >=6 semesters of undergraduate study.', 'University-wide  for UG -GR must notify science po in advance on their field as choices are limited', NULL, NULL, NULL, NULL, '["English","French"]', 'substantial', 'Undergraduate & Graduate English-track minimums: IELTS 6.5, TOEFL / TOEFL iBT Home Edition 100, Duolingo English Test 130, or Cambridge C1 (FCE/CAE/CPE); native English speakers exempt. RHET 1020 waiver not stated.', 'French not required for English-taught programs. For French-taught courses: UG requires TCF 400 or DELF/DALF B2; GR requires TCF 500 or DELF/DALF C1 (native French speakers exempt).', '["Fall","Spring"]', '2025-09-01 to 2025-12-19 (AY 2025-2026 Sem 1 classes incl. exams; Welcome Programme Aug 25–30, 2025; mandatory presence through last exam day)', '2026-01-24 to 2026-05-22 (AY 2025-2026 Sem 2 classes incl. exams; 2nd-yr Law School Jan 5–Apr 24; Welcome Jan 19–24, 2026)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unknown', 'Bilateral exchange students are exempt from paying the French CVEC student life contribution (obtain free exemption attestation per etudiant.gouv.fr and https://www.campusfrance.org/en/the-cvec-student-and-campus-life-contribution). Campus health center and student first-steps info at www.sciencespo.fr/students/en.html.', 'assisted', 'Housing support provided via Sciences Po Students website (https://www.sciencespo.fr/students/en/support/housing); regional campuses generally offer more affordable accommodation than Paris (`Useful Info. Science Po.docx`).', NULL, NULL, 'Non-EU/EEA/Swiss exchange students must obtain a French student visa before arrival even if already enrolled in an EU university (`factsheet2025-2026.pdf#page=2`). Effective August 1, 2026, Décret n° 2026-526 increased French VLS-TS student financial proof from EUR 615/mo to EUR 877.50/month (EUR 10,530/year; 47% of gross SMIC).', 'http://www.sciencespo.fr/', 'https://www.sciencespo.fr/college/en/academics/exchange/', NULL, NULL, 'ECTS: minimum 5 ECTS to maximum 30 ECTS per semester (up to 60 ECTS/year). Starting Sept 2025, language courses are 4 ECTS graded Pass/Fail (`Useful Info. Science Po.docx`); strict attendance policy allows max 2 absences per class.', 'Paris UG campus offers French OR English track (bilingual track discontinued); regional UG campuses feature specific geographical minors (max 2 campuses, 1–2 disciplines). GR students must enroll within one specific Master''s programme and may add up to 2 Common Academic Curriculum courses/sem.', '["CV","Personal statement","Photo ID","University transcripts","French and/or English language test results"]', NULL, NULL, 'multi_campus', NULL, 'Student Exchanges Team, optional Welcome Programme, Health Center, and Disability Support Service.', '2025-2026 cycle (`#page=1`): Autumn nomination Mar 4–26, student application Apr 2; Spring nomination Sep 23–Oct 7, student application Oct 9. Admitted students must accept offer within 15 days or forfeit spot (`Useful Info. Science Po.docx`).', '{}', '{"academic_style":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:99","source_type":"excel_list","status":"verified","value":"University-wide  for UG -GR must notify science po in advance on their field as choices are limited"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:99","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:99","source_type":"excel_list","status":"verified","value":["UG","GR"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:99","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":"Seven campuses: Paris (main/Saint-Guillaume) plus six UG regional campuses (Dijon, Le Havre, Menton, Nancy, Poitiers, Reims).","source_ref":"data/raw/factsheets/Sciences Po/2025-2026/factsheet2025-2026.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"multi_campus"},"citizens