INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('soka-university', '[100]', 1, 'matched', '["data/raw/factsheets/Soka University/Fact Sheet Spring semeter 2022_Soka University.docx","data/raw/factsheets/Soka University/Fact Sheet Spring semeter 2022_Soka University.pdf"]', '[]', 'Soka University', NULL, 'Japan', NULL, 'Hachioji, Tokyo', 'East Asia', 'active', '["UG"]', NULL, 'University-wide', '["ALL"]', '["ALL"]', NULL, NULL, '["English","Japanese"]', 'substantial', 'Students with TOEFL iBT 71 or above are eligible to enroll in elective undergraduate classes taught in English (2022 Fact Sheet #page=3). No RHET 1020 exemption stated.', 'JLPT N2 or above required for elective undergraduate courses taught in Japanese; no prior Japanese required for English-taught courses or beginner ES-E5 Japanese language classes (up to 8 credits/semester).', '["Fall","Spring"]', 'Fall semester (AY 2026-2027 reference): Orientation ~11 Sep 2026, classes begin ~12 Sep 2026, final exams late Jan 2027 (official term dates mid-Sep - late Jan).', 'Spring semester (AY 2026-2027 reference): Early Apr (e.g. 6 Apr) - late Jul; dorm move-out early Aug.', NULL, NULL, 'auc_exchange_waiver', NULL, NULL, NULL, NULL, 'unknown', NULL, 'assisted', 'International dormitories preferentially house exchange students (https://www.soka.ac.jp/en/admissions/accommodation): Takiyama International Dormitory (on campus, single rooms, JPY 224,000/sem), Hoyu Dormitory (male, ~20 min walk, twin rooms, JPY 184,000/sem), plus Cosmos / Yuko / Manyo dormitories for female students. Standard entrance fee JPY 50,000; bilateral agreements may waive dorm fees (2022 Fact Sheet #page=7 noted dormitories fee-exempt for exchange students). Optional dorm cafeteria meal plan (Mon-Sat breakfast & dinner): JPY 24,300/month on soka.ac.jp (JPY 22,500/month in 2022 Fact Sheet #page=7).', NULL, NULL, 'Requires Certificate of Eligibility (COE) processed via Soka University prior to Japanese embassy student visa application. Mandatory financial proof: bank statement showing >= JPY 300,000 (1 semester) or >= JPY 600,000 (2 semesters).', 'https://www.soka.ac.jp/', 'https://www.soka.ac.jp/en/admissions/exchange-program-inbound', NULL, NULL, 'Minimum load of 7 classes per week (at least 10 hours / 600 minutes per week, 90 min/class) required; each UG course is 2-4 credits and Japanese language courses are 1-2 credits (up to 8 credits/semester).', NULL, '["Home university nomination + online application (soka-exchange.campus-p.jp)","Official academic transcript","Certificate of enrollment from home institution","Faculty/staff letter of recommendation","Language proficiency certificate (TOEFL/IELTS for English track or JLPT N2 for Japanese track)","Financial support evidence (>= JPY 300,000 / 1 sem or JPY 600,000 / 2 sem)","Passport ID page copy & immigration headshot photo"]', NULL, NULL, NULL, NULL, NULL, 'Fall semester (Sep entry): Nomination 15 Mar, Application 31 Mar. Spring semester (Apr entry): Nomination 15 Oct, Application 31 Oct.', '{}', '{"academic_style":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:100","source_type":"excel_list","status":"verified","value":"University-wide"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:100","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:100","source_type":"excel_list","status":"verified","value":["UG"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:100","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:100","source_type":"excel_list","status":"verified","value":"Hachioji, Tokyo"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:100","source_type":"excel_list","status":"verified","value":"Japan"},"course_catalog_url":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"course_restrictions_note":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"credit_system_and_load":{"notes":null,"source_ref":"data/raw/