INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('st-olaf-college', '[101]', 2, 'matched', '["data/raw/factsheets/St. Olaf College/St. Olaf College.docx"]', '[]', 'St. Olaf College', NULL, 'United States', 'Minnesota', 'Northfield', 'North America', 'active', '["UG"]', 'Must be a continuing degree-seeking undergraduate in good academic standing nominated by a partner university; attends St. Olaf as a non-degree-seeking J-1 exchange student.', 'University-wide', '["ALL"]', '["ALL"]', '["Computer Science","Economics","Education","Mathematics","Music","Nursing","Social Work","Statistics"]', NULL, '["English"]', 'full', 'Standard international admissions benchmarks: TOEFL 90, Academic IELTS 6.5, or Duolingo English Test 120 (specific exchange partnership agreements may vary; verify partner waiver via Smith Center).', 'English only.', '["Fall","Spring"]', 'AY 2026-2027 Fall Semester: Sep 10 - Dec 15, 2026 (new international students arrive Sep 1, 2026; optional January J-Term Jan 4 - Jan 29, 2027).', 'AY 2026-2027 Spring Semester: Feb 10 - May 18, 2027 (note 4-1-4 calendar includes J-Term Jan 4 - 29, 2027).', NULL, NULL, NULL, 'USD', 1500, 1500, 7500.0, 'partial', 'J-1 exchange students are automatically enrolled (no waiver) in St. Olaf LewerMark J-1 health insurance at $1,000/yr (2026-27 billed in Fall/Spring installments), plus mandatory Minnesota immunizations (MMR & Td per St. Olaf DOCX).', 'guaranteed', '2026-27 billed rates: multiple-occupancy housing $3,575/sem ($7,150/yr) + meal plan $3,925/sem ($7,850/yr) per Student Accounts Comprehensive Fee schedule (see also https://wp.stolaf.edu/reslife/).', NULL, NULL, 'Requires J-1 student visa (DS-2019 issued upon admission via Taylor Center/Smith Center), International Student Certification of Finances, English proficiency proof, mandatory J-1 health insurance, Minnesota immunizations, and potential 2-year home residency rule (212(e)) disclosure.', 'https://wp.stolaf.edu/', 'https://wp.stolaf.edu/smithcenter/', 'https://www.stolaf.edu/catalog/', NULL, '4-1-4 academic calendar system (Fall semester - January Term - Spring semester); exact numeric exchange credit limits unverified on stolaf.edu.', 'Incoming exchange students cannot take courses in Computer Science, Economics, Education, Mathematics, Music, Nursing, Social Work, or Statistics.', '["Home university nomination","St. Olaf non-degree international application","Official academic transcript","International Student Certification of Finances form","English proficiency verification"]', 'Residential 4-1-4 liberal arts college curriculum in Northfield, Minnesota.', NULL, NULL, NULL, 'Smith Center for Global Engagement, Taylor Center for Equity & Inclusion (J-1/DS-2019 advising), Residential Life, and Student Health Service.', NULL, '{}', '{"academic_style":{"notes":null,"source_ref":"https://www.stolaf.edu/catalog/","source_type":"official_web","status":"partial","value":"Residential 4-1-4 liberal arts college curriculum in Northfield, Minnesota."},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:101","source_type":"excel_list","status":"verified","value":"University-wide"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:101","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:101","source_type":"excel_list","status":"verified","value":["UG"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:101","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":"300-acre hilltop setting overlooking Cannon River Valley (~45 min south of Minneapolis-Saint Paul on stolaf.edu), without explicit rural/suburban enum confirmation.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:101","source_type":"excel_list","status":"verified","value":"Northfield"},"city_tier":{"notes":"Northfield, MN; official population figures in search results came from Wikipedia/nse.org (excluded).","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:101","source_type":"excel_list","status":"verified","value":"United States"},"course_catalog_url":{"notes":null,"source_ref":"https://www.stolaf.edu/catalog/","source_type":"official_web","status":"verified","value":"https://www.stolaf.edu/catalog/"},"course_restrictions_note":{"notes":null,"source_ref":"https://wp.stolaf.edu/smithcenter/","source_type":"official_web","status":"verified","value":"Incoming exchange students cannot take courses in Computer Science, Economics, Education, Mathematics, Music, Nursing, Social Work, or Statistics."},"credit_system_and_load":{"notes":null,"source_ref":"https://wp.stolaf.edu/registrar/","source_type":"official_web","status":"partial","value":"4-1-4 academic calendar system (Fall semester - January Term - Spring semester); exact numeric exchange credit limits unverified on stolaf.edu."},"cross_references":[],"daily_life_english_friendliness":{"notes":"Not explicitly rated on stolaf.edu or DOCX (US English-speaking campus).","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Exact University-wide agreement scope.","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:101","source_type":"excel_list","status":"verified","value":["ALL"]},"eligible_majors":{"notes":"Exact University-wide agreement scope (note 8 departments excluded by St. Olaf policy).","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:101","source_type":"excel_list","status":"verified","value":["ALL"]},"english_course_availability":{"notes":"US liberal arts college operating in English.","source_ref":"https://www.stolaf.edu/catalog/","source_type":"official_web","status":"verified","value":"full"},"english_course_list_url":{"notes":"All courses in https://www.stolaf.edu/catalog/ are taught in English; no separate English-only filter URL.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":null,"source_ref":"https://wp.stolaf.edu/international-applications/","source_type":"official_web","status":"partial","value":"Standard international admissions benchmarks: TOEFL 90, Academic IELTS 6.5, or Duolingo English Test 120 (specific exchange partnership agreements may vary; verify partner waiver via Smith Center)."},"est_monthly_living_local":{"notes":"Derived monthly cost from St. Olaf AY 2026-2027 Student Accounts comprehensive fee schedule divided by 5 months: Multiple-occupancy housing $3,575/sem ($7,150/yr) + Meal Plan $3,925/sem ($7,850/yr) = $7,500/sem -> $1,500/mo. Excludes mandatory J-1 health insurance ($1,000/yr), $500 activities fee, books, and personal expenses.","source_ref":"https://wp.stolaf.edu/stuacct/comprehensive-fee/","source_type":"official_web","status":"partial","value":{"currency":"USD","max":1500,"min":1500}},"excel_rows":[101],"exchange_page_url":{"notes":null,"source_ref":"https://wp.stolaf.edu/smithcenter/","source_type":"official_web","status":"verified","value":"https://wp.stolaf.edu/smithcenter/"},"excluded_majors":{"notes":"St. Olaf Smith Center explicitly bars incoming exchange students from registering in Computer Science, Economics, Education, Mathematics, Music, Nursing, Social Work, and Statistics.","source_ref":"https://wp.stolaf.edu/smithcenter/","source_type":"official_web","status":"verified","value":["Computer Science","Economics","Education","Mathematics","Music","Nursing","Social Work","Statistics"]},"ext":{},"fact_sheet_status":{"drive_links":["https://drive.google.com/drive/folders/1JjBqs1Y0krydAeIM9G_TKVn5pQ47z1KF"],"extracted_files":["data/raw/extracted/St. Olaf College/St. Olaf College.docx.txt"],"local_files":["data/raw/factsheets/St. Olaf College/St. Olaf College.docx"],"match_status":"matched","notes":"Excel Col H blank, but matching public folder found in Drive master folder"},"fall_term_dates":{"notes":null,"source_ref":"https://wp.stolaf.edu/registrar/","source_type":"official_web","status":"verified","value":"AY 2026-2027 Fall Semester: Sep 10 - Dec 15, 2026 (new international students arrive Sep 1, 2026; optional January J-Term Jan 4 - Jan 29, 2027)."},"final_semester_allowed":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_grants_or_stipends":{"notes":"No St. Olaf incoming exchange stipend verified.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_language_requirement":{"notes":null,"source_ref":"https://wp.stolaf.edu/international-applications/","source_type":"official_web","status":"verified","value":"English only."},"housing_availability":{"notes":"Residential college: full-time and incoming exchange students are required to live in college-owned housing (2026-27 billed rates posted at https://wp.stolaf.edu/stuacct/comprehensive-fee/).","source_ref":"https://wp.stolaf.edu/smithcenter/","source_type":"official_web","status":"verified","value":"guaranteed"},"housing_notes":{"notes":null,"source_ref":"https://wp.stolaf.edu/stuacct/comprehensive-fee/","source_type":"official_web","status":"verified","value":"2026-27 billed rates: multiple-occupancy housing $3,575/sem ($7,150/yr) + meal plan $3,925/sem ($7,850/yr) per Student Accounts Comprehensive Fee schedule (see also https://wp.stolaf.edu/reslife/)."},"instruction_languages":{"notes":null,"source_ref":"https://www.stolaf.edu/catalog/","source_type":"official_web","status":"verified","value":["English"]},"international_support_services":{"notes":null,"source_ref":"data/raw/factsheets/St. Olaf College/St. Olaf College.docx","source_type":"fact_sheet","status":"verified","value":"Smith Center for Global Engagement, Taylor Center for Equity & Inclusion (J-1/DS-2019 advising), Residential Life, and Student Health Service."},"living_cost_usd_est":{"notes":"5-month estimate derived from monthly USD range 1,500/month. No FX conversion (1 USD = 1.0 USD; 5-month equivalent = 5 * 1,500.0 USD = 7,500.00 USD), calculated 2026-11-15.","source_ref":"https://wp.stolaf.edu/stuacct/comprehensive-fee/","source_type":"official_web","status":"partial","value":7500.0},"mandatory_host_fees_and_insurance":{"notes":null,"source_ref":"https://wp.stolaf.edu/international-applications/","source_type":"official_web","status":"partial","value":"J-1 exchange students are automatically enrolled (no waiver) in St. Olaf LewerMark J-1 health insurance at $1,000/yr (2026-27 billed in Fall/Spring installments), plus mandatory Minnesota immunizations (MMR & Td per St. Olaf DOCX)."},"min_gpa_host":{"notes":"Good academic standing vetted by home institution; no numeric GPA cutoff published by St. Olaf for exchange partners.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"min_standing_note":{"notes":null,"source_ref":"https://wp.stolaf.edu/smithcenter/","source_type":"official_web","status":"verified","value":"Must be a continuing degree-seeking undergraduate in good academic standing nominated by a partner university; attends St. Olaf as a non-degree-seeking J-1 exchange student."},"nomination_deadlines":{"notes":"Coordinated directly with partner schools via the Smith Center (Nov 1 / Jan 15 dates on stolaf.edu are degree admissions; third-party StudioAbroad portal excluded).","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"official_name":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:101","source_type":"excel_list","status":"verified","value":"St. Olaf College"},"official_website_url":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:101","source_type":"excel_list","status":"verified","value":"https://wp.stolaf.edu/"},"region":{"notes":"From normalized manifest country/region mapping","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:101","source_type":"excel_list","status":"verified","value":"North America"},"required_application_docs":{"notes":"See https://wp.stolaf.edu/international-applications/.","source_ref":"data/raw/factsheets/St. Olaf College/St. Olaf College.docx","source_type":"fact_sheet","status":"partial","value":["Home university nomination","St. Olaf non-degree international application","Official academic transcript","International Student Certification of Finances form","English proficiency verification"]},"schema_version":"1.0.0","seat_quota":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"shard":2,"short_name":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"slug":"st-olaf-college","spring_term_dates":{"notes":null,"source_ref":"https://wp.stolaf.edu/registrar/","source_type":"official_web","status":"verified","value":"AY 2026-2027 Spring Semester: Feb 10 - May 18, 2027 (note 4-1-4 calendar includes J-Term Jan 4 - 29, 2027)."},"state_or_province":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:101","source_type":"excel_list","status":"verified","value":"Minnesota"},"tuition_model":{"notes":"Smith Center site states incoming exchange students attend as non-degree students under their partner agreement, without publishing an explicit tuition-waiver quote on verified stolaf.edu pages (regular 2026-27 sticker tuition is $32,850/sem).","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"visa_lead_time_and_financial_proof":{"notes":null,"source_ref":"data/raw/factsheets/St. Olaf College/St. Olaf College.docx","source_type":"fact_sheet","status":"verified","value":"Requires J-1 student visa (DS-2019 issued upon admission via Taylor Center/Smith Center), International Student Certification of Finances, English proficiency proof, mandatory J-1 health insurance, Minnesota immunizations, and potential 2-year home residency rule (212(e)) disclosure."}}');
