INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('state-university-of-new-york-suny-at-new-paltz', '[103]', 4, 'matched', '["data/raw/factsheets/SUNY - New Paltz/Fall 2025/New Paltz Fact sheet Fall 2025.pdf","data/raw/factsheets/SUNY - New Paltz/Spring 2026/New Paltz Fact sheet Spring 2026.pdf"]', '[]', 'State University of New York (SUNY) at New Paltz', 'SUNY New Paltz', 'United States', 'New York', 'New Paltz', 'North America', 'active', '["UG"]', NULL, 'University-wide', '["ALL"]', '["ALL"]', '["Digital Media & Journalism"]', 2.5, '["English"]', 'full', 'TOEFL iBT 80 or IELTS 6.5 (no band score below 6.0); applicants who do not submit scores are tested upon arrival (ESL courses available).', 'None (instruction is in English)', '["Fall","Spring"]', 'Fall 2026: Classes begin Aug 24, 2026; Thanksgiving Break Nov 25–27, 2026; Last day of classes Dec 7, 2026; Final Exams Dec 11–17, 2026.', 'Spring 2026 (fact sheet): Airport pickup & move-in Jan 15, Orientation Jan 16, Classes Jan 21 – May 15, 2026 (Spring Break Mar 30 – Apr 3, 2026); Spring 2027 UG registration opens Nov 9, 2026.', NULL, NULL, 'auc_exchange_waiver', 'USD', 2256, 2256, 11280.0, 'partial', 'Spring 2026 / Fall 2025 billed non-tuition fees: Health Insurance $1,130/semester, Health Center Fee $170/semester, College Fee $30/semester, one-time Orientation Fee $150 (plus on-campus Room $5,880 and Food Service $2,960).', 'assisted', 'On-campus Residence Halls + meal plan strongly recommended ($5,880 room + $2,960 food service/semester in 2025-2026); university does not assist with off-campus housing.', NULL, NULL, 'J-1 Exchange Visitor visa required (unless US citizen); DS-2019 requires demonstrating $12,760 USD Personal Funds for 1 semester (~$25,520 for Academic Year) covering room, meal plan, fees, insurance, books, and personal expenses.', 'http://www.newpaltz.edu/', 'https://www.newpaltz.edu/international/partners/exchange/partner-fact-sheet/', 'https://www.newpaltz.edu/classes/', NULL, 'US credit hours; minimum 12 credits/semester required for full-time & international student status (15 credits standard; up to 19 credits permitted).', 'Department of Digital Media & Journalism is closed to exchange students; all other areas open provided prerequisites are evidenced on transcript (popular courses include POL370 UN Semester, THE209, SAB353).', NULL, 'US-style liberal arts', NULL, NULL, NULL, 'Official airport pick-up, mandatory Orientation, ESL courses, student organizations, and dedicated Inbound Exchange Advisor (pollardj@newpaltz.edu).', 'Fall: Nomination Mar 15 / Application Apr 15 (Fall 2025 sheet); Spring: Nomination Oct 15 / Application Nov 15 (Spring 2026 sheet; flexible by agreement).', '{}', '{"academic_style":{"notes":"SUNY comprehensive public liberal arts college.","source_ref":"data/raw/factsheets/SUNY - New Paltz/Spring 2026/New Paltz Fact sheet Spring 2026.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"US-style liberal arts"},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:103","source_type":"excel_list","status":"verified","value":"University-wide"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:103","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:103","source_type":"excel_list","status":"verified","value":["UG"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:103","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:103","source_type":"excel_list","status":"verified","value":"New Paltz"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:103","source_type":"excel_list","status":"verified","value":"United States"},"course_catalog_url":{"notes":"Also full course descriptions at https://www.newpaltz.edu/ugc/ucourses.html and programs at https://www.newpaltz.edu/ugc/programs.html.","source_ref":"data/raw/factsheets/SUNY - New Paltz/Spring 2026/New Paltz Fact sheet Spring 2026.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"https://www.newpaltz.edu/classes/"},"course_restrictions_note":{"notes":"Prerequisites & popular courses on page 2.","source_ref":"data/raw/factsheets/SUNY - New Paltz/Spring 2026/New Paltz Fact sheet Spring 2026.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"Department of Digital Media & Journalism is closed to exchange students; all other areas open provided prerequisites are evidenced on transcript (popular courses include POL370 UN Semester, THE209, SAB353)."},"credit_system_and_load":{"notes":"Confirmed on newpaltz.edu academic credit load policies.","source_ref":"https://www.newpaltz.edu/ugc/","source_type":"official_web","status":"verified","value":"US credit hours; minimum 12 credits/semester required for full-time & international student status (15 credits standard; up to 19 credits permitted)."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"University-wide UG exchange agreement (Fall/Spring).","source_ref":"data/raw/partner_list_extracted.json#row=103","source_type":"excel_list","status":"verified","value":["ALL"]},"eligible_majors":{"notes":"All majors except Digital Media & Journalism (subject to prerequisites on transcript).","source_ref":"data/raw/partner_list_extracted.json#row=103","source_type":"excel_list","status":"verified","value":["ALL"]},"english_course_availability":{"notes":"All courses taught in English (ESL courses also available).","source_ref":"data/raw/factsheets/SUNY - New Paltz/Spring 2026/New Paltz Fact sheet Spring 2026.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"full"},"english_course_list_url":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":null,"source_ref":"data/raw/factsheets/SUNY - New Paltz/Spring 2026/New Paltz Fact sheet Spring 2026.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"TOEFL iBT 80 or IELTS 6.5 (no band score below 6.0); applicants who do not submi