INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('technische-universiteit-eindhoven-tue', '[108]', 8, 'matched', '["data/raw/factsheets/Technische Universiteit Eindhoven (TUE)/Technische Universiteit Eindhoven (TUE).docx"]', '[]', 'Technische Universiteit Eindhoven (TUE)', 'TUE', 'Netherlands', NULL, 'Eindhoven', 'Europe', 'active', '["UG","GR"]', NULL, 'Industrial Engineering and Innovation Sciences', NULL, '["Industrial Engineering and Innovation Sciences"]', NULL, NULL, '["English","Dutch"]', 'substantial', 'Non-EEA students require TOEFL iBT >= 90 (min 21 per section; code 8615/dept 99), IELTS Academic >= 6.5 (min 6.0 per section), Cambridge C1 Advanced >= 176 (min 169) or C2 Proficiency >= 180 (min 169); scores <= 2 years old (exemptions only for citizens/degrees from AU, CA, IE, NZ, UK, US). RHET 1020 waiver not stated.', 'English proficiency required (B2/C1); Dutch not required for English-taught IE&IS courses.', '["Spring"]', NULL, '2027-02 to 2027-07-03 (AY 2026-2027 Semester B / Quartiles 3–4; Q3 exams Apr 5–17; Q4 classes Apr 19–Jun 18; Q4 exams Jun 21–Jul 3, 2027)', NULL, NULL, 'auc_exchange_waiver', 'EUR', 833, 1000, 5064.6, 'partial', 'Health and liability insurance are mandatory in the Netherlands (recommended Aon ICS Complete+ via www.aonstudentinsurance.com/tue for non-EU students unless home coverage meets equivalent Dutch terms).', 'assisted', 'Students look early via Vestide or private Eindhoven rentals (~EUR 400 room to EUR 700 studio/month per TU/e factsheet).', NULL, NULL, 'Non-EEA students require an MVV entry visa and/or VVR residence permit processed collectively through TU/e International Office with IND proof of sufficient monthly financial means (deposit to TU/e or full-cost scholarship).', 'https://www.tue.nl/en/', 'https://www.tue.nl/en/education/tue-graduate-school/exchange-ieis', NULL, NULL, NULL, 'Scoped to Department of Industrial Engineering and Innovation Sciences (IE&IS: Master courses in Operations Management & Logistics, Innovation Management, Innovation Sciences, or advanced 3rd-year Bachelor options).', NULL, NULL, NULL, NULL, NULL, 'TU/e International Programs Office, Mobility-Online nomination/application portal, collective IND immigration processing.', NULL, '{}', '{"academic_style":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:108","source_type":"excel_list","status":"verified","value":"Industrial Engineering and Innovation Sciences"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:108","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_lis