INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('the-manchester-metropolitan-university-mmu', '[114]', 6, 'matched', '["data/raw/factsheets/University of Manchester/Manchester Met Fact Sheet 2025-26.docx"]', '[]', 'The Manchester Metropolitan University (MMU)', 'MMU', 'United Kingdom', NULL, 'Manchester', 'Europe', 'active', NULL, NULL, 'NO for these: Acting, Architecture, Computing, Education, Engineering, Healthcare Science, Journalism, Maths and Sports Science.', NULL, NULL, '["Acting","Architecture","Computing","Education","Engineering","Healthcare Science","Journalism","Maths","Sports Science"]', NULL, '["English"]', 'full', 'Standard IELTS Academic 6.0 overall (minimum 5.5 in each component) or accepted equivalent if not previously taught in English; specific courses may require higher. No RHET 1020 waiver stated.', NULL, '["Fall","Spring","Academic Year"]', 'AY 2026-2027 Semester 1: Welcome Week Sep 28 – Oct 2, 2026; Teaching Oct 5 – Dec 18, 2026; Winter Break Dec 19 – Jan 10, 2027; Assessment Jan 11 – Jan 22, 2027.', 'AY 2026-2027 Semester Two: Future Me Week Jan 25 – Jan 29, 2027; Teaching Block 1 Feb 1 – Mar 19, 2027; Spring Break Mar 20 – Apr 11, 2027; Teaching Block 2 Apr 12 – May 7, 2027; Assessment May 10 – May 21, 2027.', NULL, NULL, 'auc_exchange_waiver', NULL, NULL, NULL, NULL, 'unknown', NULL, 'assisted', 'Full-year & Jan-start eligible to apply for on-campus accommodation (subject to availability); Sep-start 1-semester supported via Manchester Student Homes (https://www.manchesterstudenthomes.com/Accommodation) with details sent in offer letter.', NULL, NULL, '1-semester (<6 months): enter under UK Visitor rules without ATAS. Full-year: UK Student Visa required; UKVI outside-London financial proof is £1,171/month (up to 9 months = £10,539 held for 28 consecutive days unless nationality differentiation applies); ATAS not required for exchange.', 'https://www.mmu.ac.uk/', 'https://www.mmu.ac.uk/study/international/exchange-to-manchester-met', NULL, NULL, 'UK / Manchester Met credits: 60 MMU credits (= 30 ECTS) per semester; 120 MMU credits (= 60 ECTS) per academic year; includes optional free Uniwide Language unit (7.5 ECTS/term).', 'Excluded majors per agreement: Acting, Architecture, Computing, Education, Engineering, Healthcare Science, Journalism, Maths, Sports Science.', NULL, NULL, NULL, NULL, NULL, 'Study Abroad Team holds ''Welcome to Manchester Met'' session during Welcome Week plus department inductions and Manchester Student Homes short-term accommodation advising.', 'Fall: Nomination Apr 1, Application May 12; Spring: Nomination Oct 1, Application Oct 16.', '{}', '{"academic_style":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracte