INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('university-of-central-florida-ucf', '[132]', 8, 'matched', '["data/raw/factsheets/UCF/2024-2025/UCF Information Sheet 2024-2025.pdf","data/raw/factsheets/UCF/2025 - 2026/UCF Fact Sheet 2025-2026.pdf","data/raw/factsheets/UCF/2026-2027/UCF Fact Sheet 2026-2027.pdf"]', '[]', 'University of Central Florida (UCF)', 'UCF', 'United States', 'Florida', 'Orlando', 'North America', 'active', '["UG","GR"]', 'Nominated by home partner university; graduate exchange applicants must hold a bachelor''s degree or equivalent qualification.', 'University-wide', '["ALL"]', '["ALL"]', NULL, NULL, '["English"]', 'full', 'For non-English official/native-language citizens: TOEFL iBT 80, IELTS 6.5, Duolingo 120, OR signed official letter from home university confirming years of English study and college-level English proficiency. RHET 1020 waiver not stated.', 'English proficiency required for non-English native countries unless home-university English proficiency letter submitted.', '["Fall","Spring"]', '2026-08-24 to 2026-12-10 (classes Aug 24–Dec 3; exams Dec 4–10, 2026)', '2027-01-11 to 2027-05-04 (classes Jan 11–Apr 26; exams Apr 28–May 4, 2027)', NULL, NULL, 'auc_exchange_waiver', 'USD', 1350, 1650, 7500.0, 'partial', 'Mandatory adequate health insurance per Florida Board of Governors (UCF Health Insurance ~$500–$950/sem depending on coverage); mandatory immunizations prior to registration; International Fee $50, Transcript $18. Lynx Orlando buses and UCF Shuttle free with UCF ID.', 'assisted', 'Partnered off-campus/campus-adjacent options: The Verge (~$4,999/sem all-inclusive utilities, security/background fees waived), UnionWest (Downtown/Main), and Rosen College apartments (Hospitality); Housing instructions sent June (Fall) / Nov (Spring).', NULL, NULL, 'J-1 visa (Form DS-2019) required; must submit passport copy, English proficiency proof, financial documentation (abroad.ucf.edu notes $7,615/sem minimum proof), and Affidavit of Support.', 'https://www.ucf.edu/', 'https://abroad.ucf.edu/', NULL, NULL, 'US credit hours (standard course = 3 credits): UG min 12 credits, GR min 9 credits; maximum load covered by tuition waiver is 16 credits.', 'UG cannot enroll in 5000+ level courses; Master''s students limited to <=6000; PhD any level. Prerequisite courses require department approval contingent on transcript.', '["Non-Degree Seeking UCF Application + UCF Abroad online profile","Most recent official academic transcript (+ proof of current enrolled courses if absent)","Registration Worksheet signed by home/host academic advisor","Passport copy + English proficiency proof (or home-university letter)","Financial Documentation & Affidavit of Support for DS-2019"]', NULL, NULL, 'multi_campus', NULL, 'UCF Abroad advising, Global Knights Society student organization, UCF Health Center, SARC tutoring, CAPS, SAS accessibility, complimentary Lynx transit & campus shuttle.', 'Fall 2026: partner nomination March 1, student application June 1. Spring 2027: partner nomination September 1, student application October 30.', '{}', '{"academic_style":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:132","source_type":"excel_list","status":"verified","value":"University-wide"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:132","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:132","source_type":"excel_list","status":"verified","value":["UG","GR"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:132","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":"Three Orlando campuses open to exchange students: UCF Main Campus (East Orlando), UCF Downtown Campus, and Rosen College of Hospitality Management (West Orlando).","source_ref":"data/raw/factsheets/UCF/2026-2027/UCF Fact Sheet 2026-2027.pdf#page=4","source_type":"fact_sheet","status":"verified","value":"multi_campus"},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:132","source_type":"excel_list","status":"verified","value":"Orlando"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:132","source_type":"excel_list","status":"verified","value":"United States"},"course_catalog_url":{"notes":"Students search courses interactively via my.ucf.edu -> Class Search or Browse Course Catalog (`UCF Fact Sheet 2026-2027.pdf#page=3`).","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"course_restrictions_note":{"notes":null,"source_ref":"data/raw/factsheets/UCF/2026-2027/UCF Fact Sheet 2026-2027.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"UG cannot enroll in 5000+ level courses; Master''s students limited to <=6000; PhD any level. Prerequisite courses require department approval contingent on transcript."},"credit_system_and_load":{"notes":null,"source_ref":"data/raw/factsheets/UCF/2026-2027/UCF Fact Sheet 2026-2027.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"US credit hours (standard course = 3 credits): UG min 12 credits, GR min 9 credits; maximum load covered by tuition waiver is 16 credits."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Excel agreement_scope_raw is ''University-wide''.","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:132","source_type":"excel_list","status":"verified","value":["ALL"]},"eligible_majors":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:132","source_type":"excel_list","status":"verified","value":["ALL"]},"english_course_availability":{"notes":null,"source_ref":"data/raw/factsheets/UCF/2026-2027/UCF Fact Sheet 2026-2027.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"full"},"english_course_list_url":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":"Rule introduced on #page=6 and test cutoffs listed on #page=7.","source_ref":"data/raw/factsheets/UCF/2026-2027/UCF Fact Sheet 2026-2027.pdf#page=7","sour