)."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_majors":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_course_availability":{"notes":"~2,000 English-taught courses available across faculties alongside Danish-taught courses.","source_ref":"https://studies.ku.dk/exchange/course-information/","source_type":"official_web","status":"verified","value":"substantial"},"english_course_list_url":{"notes":"UCPH course catalog at https://kurser.ku.dk/ requires interactive language and block filtering; no static English-only course list URL.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":null,"source_ref":"https://studies.ku.dk/exchange/course-information/english-proficiency/","source_type":"official_web","status":"verified","value":"UCPH generally relies on home university nomination confirming sufficient English proficiency (recommending CEFR B2); specific departments or Master''s modules (e.g., English Studies) may request formal TOEFL/IELTS proof during course selection. No explicit RHET 1020 exemption stated."},"est_monthly_living_local":{"notes":"UCPH publishes accommodation price ranges (~DKK 4,000-10,000/month via Housing Foundation Copenhagen) and SIRI sets DKK 7,426/month visa proof, but no total official UCPH monthly living cost range is published.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"excel_rows":[133],"exchange_page_url":{"notes":null,"source_ref":"data/raw/factsheets/UoCopenhagen/University of Copenhagen- Details.docx","source_type":"fact_sheet","status":"verified","value":"https://studies.ku.dk/exchange/"},"excluded_majors":{"notes":null,"source_ref":null,"source_type":"unknown","stat