ce_type":"fact_sheet","status":"verified","value":["Mobility-Online application form","Academic transcript","B2 language certificate (if non-native speaker)","Passport copy","Seezeit €900 housing payment proof","Enrollment uploads: health insurance, social contribution fee proof, photo, visa/financial proof"]},"schema_version":"1.0.0","seat_quota":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"shard":6,"short_name":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"slug":"university-of-konstanz","spring_term_dates":{"notes":null,"source_ref":"data/raw/factsheets/Konstanz/UniKonstanz_Fact-Sheet_2026-27.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"AY 2026-2027 Summer Semester: Apr 1 – Sep 30, 2027; Lectures Apr 5 – Jul 17, 2027 (break May 24–30); Exams Jul + Aug."},"state_or_province":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"tuition_model":{"notes":"Fact Sheet 2026-27 does not explicitly confirm exchange waiver text; see official costs page https://www.uni-konstanz.de/en/international-office/study-in-konstanz/preparation/costs-associated-with-studying/.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"visa_lead_time_and_financial_proof":{"notes":"Also https://www.uni-konstanz.de/en/international-office/study-in-konstanz/preparation/visa-and-residence-permit/.","source_ref":"data/raw/factsheets/Konstanz/UniKonstanz_Fact-Sheet_2026-27.pdf#page=4","source_type":"fact_sheet","status":"verified","value":"Non-EU/non-exempt students require a German student visa valid through end of March/August (no 1-month extension) plus post-arrival Konstanz residence permit; financial proof requirement €992/month."}}');
INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('university-of-ljubljana', '[139]', 5, 'none', '[]', '[]', 'University of Ljubljana', 'University of Ljubljana', 'Slovenia', NULL, 'Ljubljana', 'Europe', 'active', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Slovenian","English"]', 'substantial', 'Non-native speakers taking English-taught courses must submit proof of minimum CEFR B2 English proficiency (home-institution language certificate, transcript of prior English-medium courses, or standardized test scores; specific faculty requirements vary and RHET 1020 waiver policy is not explicitly specified).', 'Minimum CEFR B2 proficiency in the language of instruction (English or Slovenian depending on chosen courses).', NULL, '2026-27 Winter Semester: Orientation Days Sep 28-30, 2026; Lectures Oct 1, 2026 - Jan 15, 2027 (Christmas break Dec 25 - Jan 3); Examination period Jan 18 - Feb 12, 2027.', '2026-27 Second (Summer) Semester: Lectures Feb 15 - Jun 2, 2027; Spring Examination Period Jun 3 - Jun 30, 2027 (Autumn exam period Aug 23 - Sep 17, 2027; individual faculty dates may vary slightly).', NULL, NULL, 'auc_exchange_waiver', 'EUR', 500.0, 700.0, 3315.6, 'partial', 'Exchange students are exempt from tuition fees. Valid health insurance covering Slovenia is mandatory for entry/residence permits for non-EU nationals (bilateral social-security holders must register locally upon arrival).', 'assisted', 'Limited dormitory spots for exchange students (shared double rooms, average EUR 197.44/mo, range EUR 119.28-230.89/mo plus ~EUR 30/mo expenses) allocated first-come, first-served; private rooms/apartments range EUR 200-500/mo.', NULL, NULL, 'EU/EEA nationals enter with passport/ID and register temporary residence for stays >90 days. Non-EU/EEA nationals require a Type D visa and/or temporary residence permit for study applied for in advance via a Slovenian embassy/consulate with valid health insurance.', 'https://www.uni-lj.si/en', 'https://www.uni-lj.si/en/study/exchanges/exchange-students', NULL, NULL, 'ECTS credit system (60 ECTS/academic year; standard semester load up to 30 ECTS at Bachelor level and up to 35 ECTS at Master level; typical course carries 6-7 ECTS).', NULL, '["Home university official nomination (EWP or email to intern.office@uni-lj.si / host faculty)","Online UL exchange application (no paper copies required)","Transcript of Records","Learning Agreement / Online Learning Agreement (OLA)","Language certificate (minimum CEFR B2 in English or Slovenian)","Copy of passport or personal ID card"]', NULL, NULL, 'multi_campus', NULL, 'Central Office of International Relations (intern.office@uni-lj.si), Info tujci international student info point, faculty international offices, and ŠOU v Ljubljani / ESN Ljubljana support.', 'Winter semester / Full academic year: May 15. Summer (Spring) semester: November 15.', '{}', '{"academic_style":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_scope_raw":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:139","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":"Blank in partner Excel agreement sheet; host offers Bachelor, Master, and Doctoral exchanges depending on faculty.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"available_terms":{"notes":"Blank in partner Excel agreement sheet; University of Ljubljana operates Winter (Fall) and Summer (Spring) semesters.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"campus_type":{"notes":"Decentralized layout across Ljubljana with 23 faculties and 3 art academies (https://www.uni-lj.si/en/university/faculties-and-academies).","source_ref":"https://www.uni-lj.si/en/university/about-us","source_type":"official_web","status":"verified","value":"multi_campus"},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:139","source_type":"excel_list","status":"verified","value":"Ljubljana"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:139","source_type":"excel_list","status":"verified","value":"Slovenia"},"course_catalog_url":{"notes":"No single central catalog covers all 23 faculties and 3 academies; consult host faculty portals (e.g. SEB LU https://www.ef.uni-lj.si/en/international-exchange/incoming-students, Arts https://www.ff.uni-lj.si/en/study/exchange-students/courses-english, Social Sciences https://www.fdv.uni-lj.si/en/study/exchange-programmes, Education https://www.pef.uni-lj.si/en/study/exchange-students/courses-in-english/).","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"course_restrictions_note":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"credit_system_and_load":{"notes":null,"source_ref":"https://www.uni-lj.si/en/study/international-students/exchange-students","source_type":"official_web","status":"verified","value":"ECTS credit system (60 ECTS/academic year; standard semester load up to 30 ECTS at Bachelor level and up to 35 ECTS at Master level; typical course carries 6-7 ECTS)."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Blank agreement scope in partner Excel list.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_majors":{"notes":"Blank agreement scope in partner Excel list.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_course_availability":{"notes":"Decentralized across 23 faculties and 3 academies, many publishing dedicated English course lists (e.g., SEB LU offers 120+ Bachelor/Master courses in English, plus Social Sciences, Arts, Education, Computer Science, Law).","source_ref":"https://www.ef.uni-lj.si/en/international-exchange/incoming-students","source_type":"official_web","status":"verified","value":"substantial"},"english_course_list_url":{"notes":"Published individually per faculty rather than one central URL (e.g. SEB LU https://www.ef.uni-lj.si/en/international-exchange/incoming-students).","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":null,"source_ref":"https://www.uni-lj.si/en/study/exchanges/exchange-students","source_type":"official_web","status":"partial","value":"Non-native speakers taking English-taught courses must submit proof of minimum CEFR B2 English proficiency (home-institution language certificate, transcript of prior English-medium courses, or standardized test scores; specific faculty requirements vary and RHET 1020 waiver policy is not explicitly specified)."},"est_monthly_living_local":{"notes":"Official UL living guide states approx. 500-700 EUR/month (dorms ~EUR 119.28-230.89 avg EUR 197.44 + ~EUR 30 expenses; private housing EUR 200-500; food EUR 200-300 with subsidized student ''boni'' meals; Urbana monthly bus pass EUR 20).","source_ref":"https://www.uni-lj.si/en/study/information-for-international-students/exchange-students/accommodation-cost-of-living-and-transport","source_type":"official_web","status":"verified","value":{"currency":"EUR","max":700.0,"min":500.0}},"excel_rows":[139],"exchange_page_url":{"notes":null,"source_ref":"https://www.uni-lj.si/en/study/exchanges/exchange-students","source_type":"official_web","status":"verified","value":"https://www.uni-lj.si/en/study/exchanges/exchange-students"},"excluded_majors":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"ext":{},"fact_sheet_status":{"drive_links":[],"extracted_files":[],"local_files":[],"match_status":"none","notes":null},"fall_term_dates":{"notes":null,"source_ref":"https://www.uni-lj.si/_files/129759/studijski-koledar-ul-2026-2027.pdf","source_type":"official_web","status":"verified","value":"2026-27 Winter Semester: Orientation Days Sep 28-30, 2026; Lectures Oct 1, 2026 - Jan 15, 2027 (Christmas break Dec 25 - Jan 3); Examination period Jan 18 - Feb 12, 2027."},"final_semester_allowed":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_grants_or_stipends":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_language_requirement":{"notes":null,"source_ref":"https://www.uni-lj.si/en/study/exchanges/exchange-students","source_type":"official_web","status":"verified","value":"Minimum CEFR B2 proficiency in the language of instruction (English or Slovenian depending on chosen courses)."},"housing_availability":{"notes":"UL does not own/manage dormitories directly, but a limited number of shared double rooms are allocated first-come, first-served based on timestamp (applications open mid-May); ŠOU assists with private rentals.","source_ref":"https://www.uni-lj.si/en/study/international-students/accommodation-and-transport","source_type":"official_web","status":"verified","value":"assisted"},"housing_notes":{"notes":null,"source_ref":"https://www.uni-lj.si/en/study/international-students/accommodation-and-transport","source_type":"official_web","status":"verified","value":"Limited dormitory spots for exchange students (shared double rooms, average EUR 197.44/mo, range EUR 119.28-230.89/mo plus ~EUR 30/mo expenses) allocated first-come, first-served; private rooms/apartments range EUR 200-500/mo."},"instruction_languages":{"notes":null,"source_ref":"https://www.uni-lj.si/en/study/exchanges/exchange-students","source_type":"official_web","status":"verified","value":["Slovenian","English"]},"international_support_services":{"notes":null,"source_ref":"https://www.uni-lj.si/en/study/exchanges/exchange-students","source_type":"official_web","status":"verified","value":"Central Office of International Relations (intern.office@uni-lj.si), Info tujci international student info point, faculty international offices, and ŠOU v Ljubljani / ESN Ljubljana support."},"living_cost_usd_est":{"notes":"Midpoint EUR 600.00/month (from official 500-700 EUR/month guide) * 5 months = EUR 3,000.00; converted at ECB 2026-11-13 rate (collected 2026-11-15) 1 EUR = 1.1052 USD (https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html) = 3,315.60 USD.","source_ref":"https://www.uni-lj.si/en/study/information-for-international-students/exchange-students/accommodation-cost-of-living-and-transport","source_type":"official_web","status":"partial","value":3315.6},"mandatory_host_fees_and_insurance":{"notes":"Tuition exemption sourced from https://www.uni-lj.si/study/international-students/tuition-fees-and-other-study-contributions.","source_ref":"https://www.uni-lj.si/en/study/international-students/entry-and-permits","source_type":"official_web","status":"partial","value":"Exchange students are exempt from tuition fees. Valid health insurance covering Slovenia is mandatory for entry/residence permits for non-EU nationals (bilateral social-security holders must register locally upon arrival)."},"min_gpa_host":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"min_standing_note":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"nomination_deadlines":{"notes":null,"source_ref":"https://www.uni-lj.si/en/study/exchanges/exchange-students","source_type":"official_web","status":"verified","value":"Winter semester / Full academic year: May 15. Summer (Spring) semester: November 15."},"official_name":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:139","source_type":"excel_list","status":"verified","value":"University of Ljubljana"},"official_website_url":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:139","source_type":"excel_list","status":"verified","value":"https://www.uni-lj.si/en"},"region":{"notes":"From normalized manifest country/region mapping","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:139","source_type":"excel_list","status":"verified","value":"Europe"},"required_application_docs":{"notes":null,"source_ref":"https://www.uni-lj.si/en/study/exchanges/exchange-students","source_type":"official_web","status":"verified","value":["Home university official nomination (EWP or email to intern.office@uni-lj.si / host faculty)","Online UL exchange application (no paper copies required)","Transcript of Records","Learning Agreement / Online Learning Agreement (OLA)","Language certificate (minimum CEFR B2 in English or Slovenian)","Copy of passport or personal ID card"]},"schema_version":"1.0.0","seat_quota":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"shard":5,"short_name":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:139","source_type":"excel_list","status":"verified","value":"University of Ljubljana"},"slug":"university-of-ljubljana","spring_term_dates":{"notes":null,"source_ref":"https://www.uni-lj.si/_files/129759/studijski-koledar-ul-2026-2027.pdf","source_type":"official_web","status":"verified","value":"2026-27 Second (Summer) Semester: Lectures Feb 15 - Jun 2, 2027; Spring Examination Period Jun 3 - Jun 30, 2027 (Autumn exam period Aug 23 - Sep 17, 2027; individual faculty dates may vary slightly)."},"state_or_province":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"tuition_model":{"notes":"Official UL policy states exchange students are exempt from paying tuition fees.","source_ref":"https://www.uni-lj.si/study/international-students/tuition-fees-and-other-study-contributions","source_type":"official_web","status":"verified","value":"auc_exchange_waiver"},"visa_lead_time_and_financial_proof":{"notes":null,"source_ref":"https://www.uni-lj.si/en/study/international-students/entry-and-permits","source_type":"official_web","status":"partial","value":"EU/EEA nationals enter with passport/ID and register temporary residence for stays >90 days. Non-EU/EEA nationals require a Type D visa and/or temporary residence permit for study applied for in advance via a Slovenian embassy/consulate with valid health insurance."}}');
INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('university-of-orleans', '[140]', 6, 'none', '[]', '[]', 'University of Orleans', NULL, 'France', NULL, 'Orléans', 'Europe', 'active', '["UG","GR"]', NULL, 'BUSSINES only', '["BUS"]', '["Business Administration"]', NULL, NULL, '["French","English"]', 'limited', NULL, 'Minimum B2 level generally required for regular faculty courses taught in French (TCF, DELF, etc.; lower levels via IDF French language institute).', '["Fall","Spring"]', NULL, NULL, NULL, NULL, 'auc_exchange_waiver', NULL, NULL, NULL, NULL, 'unknown', 'Students taking part in an international exchange program in France are exempt from paying the CVEC (Contribution Vie Etudiante et de Campus); EU students need EHIC and non-EU students affiliate with French social security (free online registration).', 'assisted', 'CROUS residences or host family options requested during online pre-inscription (limited spots, not guaranteed; apply immediately upon acceptance); free VISALE rental guarantor scheme recommended (<30 yrs).', NULL, NULL, 'Non-European students must apply for a student visa via Campus France / French consulate upon acceptance.', 'https://www.univ-orleans.fr', 'https://www.univ-orleans.fr/en/univ/international/venir-luniversite/etudiants-en-programme-dechange', 'https://www.univ-orleans.fr/fr/univ/formation/catalogue-des-formations', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Welcome Center / One-Stop Shop (Guichet Unique) at start of academic year (La Source campus, Amphithéâtre des Sciences) assists international students with registration, visas, health, and housing.', 'Semester 1 (Fall): Application Jun 1 (UFR nominations in May, e.g. May 20 at UFR LLSH); Semester 2 (Spring): Application Oct 15 (UFR nominations early Oct, e.g. Oct 1) via MoveOn portal; verify exact UFR BRI dates.', '{}', '{"academic_style":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:140","source_type":"excel_list","status":"verified","value":"BUSSINES only"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:140","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:140","source_type":"excel_list","status":"verified","value":["UG","GR"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:140","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:140","source_type":"excel_list","status":"verified","value":"Orléans"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:140","source_type":"excel_list","status":"verified","value":"France"},"course_catalog_url":{"notes":null,"source_ref":"https://www.univ-orleans.fr/fr/univ/formation/catalogue-des-formations","source_type":"official_web","status":"verified","value":"https://www.univ-orleans.fr/fr/univ/formation/catalogue-des-formations"},"course_restrictions_note":{"notes":"No minimum UFR module percentage quota verified directly on univ-orleans.fr (third-party partner sheets excluded).","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"credit_system_and_load":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Mapped from Excel scope ''BUSSINES only''.","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:140","source_type":"excel_list","status":"verified","value":["BUS"]},"eligible_majors":{"notes":"Excel scope ''BUSSINES only''; managed via UFR DEG (Law, Economics, Management / IAE Orleans).","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:140","source_type":"excel_list","status":"partial","value":["Business Administration"]},"english_course_availability":{"notes":"Regular university curriculum is primarily in French, with limited English-taught modules/tracks across specific UFRs (such as UFR DEG, Polytech Orléans, Sciences, INSPE).","source_ref":"https://www.univ-orleans.fr/en/university/international/coming-university/study-english","source_type":"official_web","status":"verified","value":"limited"},"english_course_list_url":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":"No standardized English test score minimum stated on univ-orleans.fr (regular French-taught faculty courses generally require B2 French; English-taught programs require appropriate English proficiency).","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"est_monthly_living_local":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"excel_rows":[140],"exchange_page_url":{"notes":"Faculty of Law, Economics and Management (UFR DEG) exchange page at https://www.univ-orleans.fr/en/deg/international/erasmus-and-international-exchange.","source_ref":"https://www.univ-orleans.fr/en/univ/international/venir-luniversite/etudiants-en-programme-dechange","source_type":"official_web","status":"verified","value":"https://www.univ-orleans.fr/en/univ/international/venir-luniversite/etudiants-en-programme-dechange"},"excluded_majors":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"ext":{},"fact_sheet_status":{"drive_links":[],"extracted_files":[],"local_files":[],"match_status":"none","notes":null},"fall_term_dates":{"notes":"Academic calendars vary by host faculty/UFR on univ-orleans.fr (https://www.univ-orleans.fr/fr/univ/etudiants/accueil-scolarite/calendrier-universitaire); partner-sheet monthly estimates excluded.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"final_semester_allowed":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_grants_or_stipends":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_language_requirement":{"notes":null,"source_ref":"https://www.univ-orleans.fr/en/univ/international/venir-luniversite/etudiants-en-programme-dechange","source_type":"official_web","status":"verified","value":"Minimum B2 level generally required for regular faculty courses taught in French (TCF, DELF, etc.; lower levels via IDF French language institute)."},"housing_availability":{"notes":"During online pre-inscription, exchange students can request CROUS residence housing or partner host family placement via International Relations; places are limited (apply early) and free VISALE guarantor scheme is recommended.","source_ref":"https://www.univ-orleans.fr/en/univ/international/venir-luniversite/etudiants-en-programme-dechange","source_type":"official_web","status":"verified","value":"assisted"},"housing_notes":{"notes":null,"source_ref":"https://www.univ-orleans.fr/en/univ/international/venir-luniversite/etudiants-en-programme-dechange","source_type":"official_web","status":"verified","value":"CROUS residences or host family options requested during online pre-inscription (limited spots, not guaranteed; apply immediately upon acceptance); free VISALE rental guarantor scheme recommended (<30 yrs)."},"instruction_languages":{"notes":"Regular courses are taught predominantly in French; selected modules and specialized programs/tracks are taught in English (including UG/Master Law & Economics classes in UFR DEG, Polytech packages, Sciences/Sport, INSPE ISTEP) or German/Spanish.","source_ref":"https://www.univ-orleans.fr/en/university/international/coming-university/study-english","source_type":"official_web","status":"partial","value":["French","English"]},"international_support_services":{"notes":"Pre-arrival practical guidance also via https://www.univ-orleans.fr/en/univ/international/venir-luniversite/etudiants-en-programme-dechange and https://www.univ-orleans.fr/en/deg/international/erasmus-and-international-exchange.","source_ref":"https://www.univ-orleans.fr","source_type":"official_web","status":"verified","value":"Welcome Center / One-Stop Shop (Guichet Unique) at start of academic year (La Source campus, Amphithéâtre des Sciences) assists international students with registration, visas, health, and housing."},"living_cost_usd_est":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"mandatory_host_fees_and_insurance":{"notes":null,"source_ref":"https://www.univ-orleans.fr/en/univ/international/venir-luniversite/etudiants-en-programme-dechange","source_type":"official_web","status":"verified","value":"Students taking part in an international exchange program in France are exempt from paying the CVEC (Contribution Vie Etudiante et de Campus); EU students need EHIC and non-EU students affiliate with French social security (free online registration)."},"min_gpa_host":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"min_standing_note":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"nomination_deadlines":{"notes":null,"source_ref":"https://www.univ-orleans.fr/en/univ/international/venir-luniversite/etudiants-en-programme-dechange","source_type":"official_web","status":"partial","value":"Semester 1 (Fall): Application Jun 1 (UFR nominations in May, e.g. May 20 at UFR LLSH); Semester 2 (Spring): Application Oct 15 (UFR nominations early Oct, e.g. Oct 1) via MoveOn portal; verify exact UFR BRI dates."},"official_name":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:140","source_type":"excel_list","status":"verified","value":"University of Orleans"},"official_website_url":{"notes":null,"source_ref":"https://www.univ-orleans.fr","source_type":"official_web","status":"verified","value":"https://www.univ-orleans.fr"},"region":{"notes":"From normalized manifest country/region mapping","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:140","source_type":"excel_list","status":"verified","value":"Euro