":{"notes":"Monthly NOK 7,500 housing estimate from https://www.uio.no/english/student-life/budget/.","source_ref":"https://www.uio.no/english/studies/admission/exchange/housing.html","source_type":"official_web","status":"verified","value":"Guaranteed SiO student housing for international exchange students applying before the deadline; UiO monthly budget estimates NOK 7,500/month for housing."},"instruction_languages":{"notes":null,"source_ref":"https://www.uio.no/english/studies/courses/matnat/math/index.html","source_type":"official_web","status":"verified","value":["Norwegian","English"]},"international_support_services":{"notes":null,"source_ref":"https://www.uio.no/english/studies/admission/exchange/","source_type":"official_web","status":"verified","value":"Knutepunktet International Student Reception at Blindern campus, welcome orientation, and SiO student welfare/housing support."},"living_cost_usd_est":{"notes":"Midpoint 15250 NOK/month * 5 months * 0.104565 USD/NOK = 7973.08 USD (1 EUR = 10.5695 NOK & 1 EUR = 1.1052 USD -> 1 NOK = 0.104565 USD; ECB reference rate dated 2026-11-13, collected 2026-11-15: https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html).","source_ref":"https://www.uio.no/english/student-life/budget/","source_type":"official_web","status":"partial","value":7973.08},"mandatory_host_fees_and_insurance":{"notes":null,"source_ref":"data/raw/factsheets/University of Oslo/University of Oslo Fact sheet.docx","source_type":"fact_sheet","status":"verified","value":"Tuition waived for exchange students; travel/health insurance strongly recommended by UiO (non-EU exchange students follow UDI study permit healthcare rules)."},"min_gpa_host":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"min_standing_note":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"nomination_deadlines":{"notes":null,"source_ref":"https://www.uio.no/english/studies/admission/exchange/","source_type":"official_web","status":"verified","value":"Application deadlines: May 1 (Autumn semester); Oct 15 (Spring semester) [2020-2021 DOCX listed Nov 1 Spring]."},"official_name":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:141","source_type":"excel_list","status":"verified","value":"University of Oslo"},"official_website_url":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:141","source_type":"excel_list","status":"verified","value":"https://www.uio.no/english/"},"region":{"notes":"From normalized manifest country/region mapping","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:141","source_type":"excel_list","status":"verified","value":"Europe"},"required_application_docs":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"schema_version":"1.0.0","seat_quota":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"shard":7,"short_name":{"notes":null,"source_ref":"https://www.uio.no/english/studies/admission/exchange/","source_type":"official_web","status":"verified","value":"UiO"},"slug":"university-of-oslo","spring_term_dates":{"notes":null,"source_ref":"https://www.uio.no/english/studies/about/calendar/","source_type":"official_web","status":"verified","value":"AY 2026-2027 Spring Semester: Jan 4-Jun 18, 2027 (orientation/instruction starts Mon Jan 11, 2027)."},"state_or_province":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"tuition_model":{"notes":"Confirmed on official uio.no: nominated exchange students under bilateral and Erasmus+ agreements are exempt from tuition fees at UiO.","source_ref":"https://www.uio.no/english/studies/admission/tuition-fees/","source_type":"official_web","status":"verified","value":"auc_exchange_waiver"},"visa_lead_time_and_financial_proof":{"notes":null,"sour