INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('university-of-palermo', '[153]', 7, 'none', '[]', '[]', 'University of Palermo', 'UniPa', 'Italy', NULL, 'Palermo', 'Europe', 'letter_of_intent', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Italian","English"]', 'substantial', 'English CEFR B2 proficiency proof (certificate or home university endorsement) generally required if taking English-taught courses; RHET 1020 not mentioned.', 'Italian proficiency required if selecting Italian-taught courses per Learning Agreement; ITASTRA / CLA provides Italian language courses for incoming students.', NULL, 'AY 2026-2027 1st Semester (Autumn): Classes run Sep 28 / Oct 1-Dec 22, 2026 (with catch-up windows into Jan 2027); Winter exam session Jan-Feb 2027.', 'AY 2026-2027 2nd Semester (Spring): Classes typically mid-Feb/Mar-May/Jun 2027; Summer exams Jun-Jul 2027; Autumn resits Sep 2027.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'unknown', NULL, 'assisted', 'Sturent partner platform for private rooms/flats (servizioalloggi@unipa.it; https://www.unipa.it/target/international-students/facilities/rooms-or-apartment-rentals.html); Santi Romano canteen meals ~€3.50.', NULL, NULL, 'Non-EU incoming students require an acceptance letter to apply for an Italian Study Visa (Type D) via Universitaly / Italian Embassy/Consulate, and must apply for Permesso di Soggiorno within 8 working days of arrival in Italy. Lead time/financial floor not specified.', 'https://www.unipa.it/', 'https://www.unipa.it/mobilita/en/incoming-students/incoming-erasmus-extra---eu/', 'https://www.unipa.it/target/international-students/international-course-offerings.html', 'https://www.unipa.it/mobilita/en/incoming-students/english-subjects.html', 'CFU (Crediti Formativi Universitari, 1:1 equivalent to ECTS): standard full-time load is 30 CFU per semester (60 CFU/year).', NULL, NULL, NULL, NULL, NULL, NULL, 'Welcome Office staff support for Permesso di Soggiorno, Sturent English-speaking housing advisors, Santi Romano student canteen (~€3.50/meal), and ITASTRA Italian language courses.', '1st Semester / Full Year nomination deadline: June 30; 2nd Semester nomination deadline: November 30 (sent to incoming.students@unipa.it).', '{}', '{"academic_style":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_scope_raw":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:153","source_type":"excel_list","status":"verified","value":"letter_of_intent"},"agreement_student_levels":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"available_terms":{"notes":null,"source_ref":null,"source_type":"unknown","stat