INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('university-of-pennsylvania', '[142]', 8, 'matched', '["data/raw/factsheets/UoPennsylvania/University of Pennsylvania.docx"]', '[]', 'University of Pennsylvania', NULL, 'United States', 'Pennsylvania', 'Philadelphia', 'North America', 'active', '["UG"]', 'Minimum 3.0 GPA equivalency with solid undergraduate academic preparation; official nomination from partner institution required.', 'University-wide', '["ALL"]', '["ALL"]', '["Law","Medicine","Dental Medicine","Veterinary Medicine"]', 3.0, '["English"]', 'full', 'Non-native English speakers must submit scores <=2 years old: TOEFL iBT >= 100 (DI code 3221), IELTS Academic >= 7.0, or Duolingo English Test >= 130. RHET 1020 waiver not stated.', 'English proficiency required for non-native English speakers (TOEFL 100 / IELTS 7.0 / DET 130).', '["Fall","Spring"]', '2026-08-25 to 2026-12-17 (classes Aug 25–Dec 7; Reading Days Dec 8–9; Final Exams Dec 10–17, 2026)', '2027-01-20 to 2027-05-17 (classes Jan 20–May 4; Reading Days May 5–6; Final Exams May 7–17, 2027)', NULL, NULL, 'auc_exchange_waiver', 'USD', 2060, 2060, 10302.0, 'partial', 'Mandatory Penn Student Insurance Plan (PSIP) unless approved comparable waiver (https://shs.wellness.upenn.edu/psipinsurance/), mandatory Immunization Record, Student Health Service Clinical Fee, and Incoming Exchange Orientation & Activities Fee (~$350 Fall/AY, ~$155 Spring in 2020-21 docx).', 'guaranteed', 'Mandatory on-campus Penn housing & dining plan (AY 2026-27 Penn Abroad estimates: Room $13,644/yr, Board $6,960/yr).', NULL, NULL, 'J-1 or F-1 student visa required via Penn ISSS (passport valid >=6 months past program end); must submit financial documentation for DS-2019/I-20 (historical 2020-21 docx threshold $13,972/sem or $27,944/2 sems; see global.upenn.edu/isss).', 'https://www.upenn.edu/', 'https://global.upenn.edu/pennabroad/incoming-exchange/application-financial-information', 'https://catalog.upenn.edu/', NULL, 'Penn Credit Units (c.u.): full-time exchange load requires minimum 4 credit units (typically 4 courses) per semester.', 'Undergraduate courses up to 499-level only. At least 2 of 4 courses (or 3 of 5) must be inside the admitting undergraduate school (CAS/Wharton/Engineering/Nursing); remaining may be in other UG schools. Nominated major must match admitting school. Graduate, Law, Medical, Dental, and Veterinary School courses are prohibited.', '["Penn Abroad online exchange application (post-nomination)","Official/unofficial undergraduate transcripts","Short essays","Passport biographical page scan (valid >=6 months past end of program)","Official TOEFL (100), IELTS (7.0), or Duolingo (130) English test score (if applicable)"]', NULL, NULL, NULL, NULL, 'Penn Abroad Global Programs Manager advising, admitting-school academic advisor, ISSS J-1/F-1 immigration support (iPenn), Penn Libraries, Weingarten/Writing Center, CAPS, and disability services.', 'Fall Semester / Academic Year: March 20. Spring Semester: September 20 (partner nomination required first; decisions issued ~1 month post-deadline).', '{}', '{"academic_style":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:142","source_type":"excel_list","status":"verified","value":"University-wide"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:142","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:142","source_type":"excel_list","status":"verified","value":["UG"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:142","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:142","source_type":"excel_list","status":"verified","value":"Philadelphia"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:142","source_type":"excel_list","status":"verified","value":"United States"},"course_catalog_url":{"notes":"Undergraduate majors list: https://admissions.upenn.edu/learning-at-penn/majors-minors (`University of Pennsylvania.docx`).","source_ref":"https://catalog.upenn.edu/","source_type":"official_web","status":"verified","value":"https://catalog.upenn.edu/"},"course_restrictions_note":{"notes":null,"source_ref":"data/raw/factsheets/UoPennsylvania/University of Pennsylvania.docx","source_type":"fact_sheet","status":"verified","value":"Undergraduate courses up to 499-level only. At least 2 of 4 courses (or 3 of 5) must be inside the admitting undergraduate school (CAS/Wharton/Engineering/Nursing); remaining may be in other UG schools. Nominated major must match admitting school. Graduate, Law, Medical, Dental, and Veterinary School courses are prohibited."},"credit_system_and_load":{"notes":null,"source_ref":"data/raw/factsheets/UoPennsylvania/University of Pennsylvania.docx","source_type":"fact_sheet","status":"verified","value":"Penn Credit Units (c.u.): full-time exchange load requires minimum 4 credit units (typically 4 courses) per semester."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Excel agreement_scope_raw is ''University-wide'' (exchange links to Penn''s 4 UG schools: College of Arts & Sciences, Wharton, Engineering, Nursing; Law/Med/Dental/Vet & grad courses excluded).","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:142","source_type":"excel_list","status":"verified","value":["ALL"]},"eligible_majors":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:142","source_type":"excel_list","status":"verified","value":["ALL"]},"english_course_availability":{"notes":null,"source_ref":"https://global.upenn.edu/pennabroad/incoming-exchange/application-financial-information","source_type":"official_web","status":"verified","value":"full"},"english_course_list_url":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":"Updated from 2020-21 docx IELTS 7.5 to 2026-27 Penn Abroad IELTS 7.0 + DET 130.","source_ref":"https://global.upenn.edu/pennabroad/incoming-exchange/application-financial-information","source_type":"official_web","status":"verified","value":"Non-native English speakers must submit scores <=2 years old: TOEFL iBT >= 100 (DI code 3221), IELTS Academic >= 7.0, or Duolingo English Test >= 130. RHET 1020 waiver not stated."},"est_monthly_living_local":{"notes":"Derived by dividing 1 semester (half of AY 2026-2027 Room $13,644 + Board $6,960 = $20,604/yr -> $10,302/semester) by 5 months = $2,060.40/mo (excludes Books & Supplies $1,412/yr, PSIP health insurance, Clinical Fee, Orientation Fee, and personal/local transit expenses; 2020-21 docx listed $13,972/sem ISSS visa asset proof).","source_ref":"https://global.upenn.edu/pennabroad/incoming-exchange/application-financial-information","source_type":"official_web","status":"partial","value":{"currency":"USD","max":2060,"min":2060}},"excel_rows":[142],"exchange_page_url":{"notes":null,"source_ref":"https://global.upenn.edu/pennabroad/incoming-exchange/application-financial-information","source_type":"official_web","status":"verified","value":"https://global.upenn.edu/pennabroad/incoming-exchange/application-financial-information"},"excluded_majors":{"notes":"Incoming UG exchange students are prohibited from taking graduate-level courses or courses in Penn''s Law, Medical, Dental, or Veterinary Schools.","source_ref":"data/raw/factsheets/UoPennsylvania/University of Pennsylvania.docx","source_type":"fact_sheet","status":"verified","value":["Law","Medicine","Dental Medicine","Veterinary Medicine"]},"ext":{},"fact_sheet_status":{"drive_links":["https://drive.google.com/drive/folders/1Svyw9SiRCO-4o2qUgPC3MZtaZMcXiK1t"],"extracted_files":["data/raw/extracted/UoPennsylvania/University of Pennsylvania.docx.txt"],"local_files":["data/raw/factsheets/UoPennsylvania/University of Pennsylvania.docx"],"match_status":"matched","notes":"Excel Col H blank, but matching public folder found in Drive master folder"},"fall_term_dates":{"notes":null,"source_ref":"https://almanac.upenn.edu/penn-academic-calendar","source_type":"official_web","status":"verified","value":"2026-08-25 to 2026-12-17 (classes Aug 25–Dec 7; Reading Days Dec 8–9; Final Exams Dec 10–17, 2026)"},"final_semester_allowed":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_grants_or_stipends":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_language_requirement":{"notes":null,"source_ref":"https://global.upenn.edu/pennabroad/incoming-exchange/application-financial-information","source_type":"official_web","status":"verified","value":"English proficiency required for non-native English speakers (TOEFL 100 / IELTS 7.0 / DET 130)."},"housing_availability":{"notes":"All exchange students are required to live on campus in Penn housing and purchase an on-campus dining plan (single bedrooms rarely available due to demand; https://www.upenn.edu/services/residential).","source_ref":"data/raw/factsheets/UoPennsylvania/University of Pennsylvania.docx","source_type":"fact_sheet","status":"verified","value":"guaranteed"},"housing_notes":{"notes":null,"source_ref":"https://global.upenn.edu/pennabroad/incoming-exchange/application-financial-information","source_type":"official_web","status":"verified","value":"Mandatory on-campus Penn housing & dining plan (AY 2026-27 Penn Abroad estimates: Room $13,644/yr, Board $6,960/yr)."},"instruction_languages":{"notes":null,"source_ref":"https://global.upenn.edu/pennabroad/incoming-exchange/application-financial-information","source_type":"official_web","status":"verified","value":["English"]},"international_support_services":{"notes":null,"source_ref":"https://global.upenn.edu/isss","source_type":"official_web","status":"verified","value":"Penn Abroad Global Programs Manager advising, admitting-school academic advisor, ISSS J-1/F-1 immigration support (iPenn), Penn Libraries, Weingarten/Writing Center, CAPS, and disability services."},"living_cost_usd_est":{"notes":"1-semester USD Room & Board baseline: half of AY 2026-2027 Room ($13,644) + Board ($6,960) = $10,302.00 USD (excludes Books $1,412/yr, PSIP insurance, Clinical Fee, Orientation Fee, and misc/transit; already in USD, recorded 2026-11-15).","source_ref":"https://global.upenn.edu/pennabroad/incoming-exchange/application-financial-information","source_type":"official_web","status":"partial","value":10302.0},"mandatory_host_fees_and_insurance":{"notes":"Clinical fee and orientation fee amounts from 2020-21 University of Pennsylvania.docx.","source_ref":"https://global.upenn.edu/pennabroad/incoming-exchange/application-financial-information","source_type":"official_web","status":"verified","value":"Mandatory Penn Student Insurance Plan (PSIP) unless approved comparable waiver (https://shs.wellness.upenn.edu/psipinsurance/), mandatory Immunization Record, Student Health Service Clinical Fee, and Incoming Exchange Orientation & Activities Fee (~$350 Fall/AY, ~$155 Spring in 2020-21 docx)."},"min_gpa_host":{"notes":null,"source_ref":"https://global.upenn.edu/pennabroad/incoming-exchange/application-financial-information","source_type":"official_web","status":"verified","value":3.0},"min_standing_note":{"notes":null,"source_ref":"https://global.upenn.edu/pennabroad/incoming-exchange/application-financial-information","source_type":"official_web","status":"verified","value":"Minimum 3.0 GPA equivalency with solid undergraduate academic preparation; official nomination from partner institution required."},"nomination_deadlines":{"notes":null,"source_ref":"https://global.upenn.edu/pennabroad/incoming-exchange/application-financial-information","source_type":"official_web","status":"verified","value":"Fall Semester / Academic Year: March 20. Spring Semester: September 20 (partner nomination required first; decisions issued ~1 month post-deadline)."},"official_name":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:142","source_type":"excel_list","status":"verified","value":"University of Pennsylvania"},"official_website_url":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:142","source_type":"excel_list","status":"verified","value":"https://www.upenn.edu/"},"region":{"notes":"From normalized manifest country/region mapping","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:142","source_type":"excel_list","status":"verified","value":"North America"},"required_application_docs":{"notes":"Transcript, essays, and >=6-month passport validity rules cross-referenced with data/raw/factsheets/UoPennsylvania/University of Pennsylvania.docx.","source_ref":"https://global.upenn.edu/pennabroad/incoming-exchange/application-financial-information","source_type":"official_web","status":"verified","value":["Penn Abroad online exchange application (post-nomination)","Official/unofficial undergraduate transcripts","Short essays","Passport biographical page scan (valid >=6 months past end of program)","Official TOEFL (100), IELTS (7.0), or Duolingo (130) English test score (if applicable)"]},"schema_version":"1.0.0","seat_quota":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"shard":8,"short_name":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"slug":"university-of-pennsylvania","spring_term_dates":{"notes":null,"source_ref":"https://almanac.upenn.edu/penn-academic-calendar","source_type":"official_web","status":"verified","value":"2027-01-20 to 2027-05-17 (classes Jan 20–May 4; Reading Days May 5–6; Final Exams May 7–17, 2027)"},"state_or_province":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:142","source_type":"excel_list","status":"verified","value":"Pennsylvania"},"tuition_model":{"notes":"Institutional tuition and academic fees are w