INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('university-of-st-andrews', '[144]', 2, 'matched', '["data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf","data/raw/factsheets/UoSt. Andrews/University of St Andrews.docx"]', '[]', 'University of St. Andrews', NULL, 'United Kingdom', NULL, 'St. Andrews', 'Europe', 'active', '["UG"]', 'Excel Row 144 Col E specifies: ''For St. Andrews 3rd year, For outgoing Aucian 2nd and 3rd year''.', 'Political Science', NULL, '["Political Science"]', '["Medicine","Evening degree courses","5000-level postgraduate taught courses (for UG)"]', 3.2, '["English"]', 'full', 'Non-native English speakers must meet official undergraduate English requirements at https://www.st-andrews.ac.uk/subjects/entry/language-requirements/undergraduate/ (accepted test tables hosted online; note unverified third-party IELTS 7.0 quotes excluded).', 'English only; non-credit English language support available (cannot satisfy entry requirement, p.3).', NULL, 'AY 2026-2027 Martinmas (Semester 1): Teaching Sep 14 - Dec 21, 2026 (2025-26 PDF pattern shows early-Sep Orientation & residence exit Dec 23).', 'AY 2026-2027 Candlemas (Semester 2): Teaching Jan 25 - May 22, 2027.', NULL, NULL, 'auc_exchange_waiver', 'GBP', 1779, 1779, 11765.05, 'partial', 'Student Visa (>6 mo) requires UK Immigration Health Surcharge (IHS) for NHS care; Standard Visitor/ETA (<=6 mo) does not pay IHS (may incur non-emergency NHS charges — private medical insurance advised).', 'guaranteed', 'University halls (£12,208 estimated 38-wk residence + food budget in 2026-27 per st-andrews.ac.uk Cost of Attendance); September confirmations issue in summer, January in December.', NULL, NULL, 'Short-term <6 mo: Electronic Travel Authorisation (ETA) for non-visa nationals or Standard Visitor Visa. Longer >6 mo: UK Student Visa + Immigration Health Surcharge (NHS access).', 'https://www.st-andrews.ac.uk/', 'https://www.st-andrews.ac.uk/study-abroad/', 'https://www.st-andrews.ac.uk/subjects/modules/', NULL, 'Scottish credit framework: standard full-time load is 60 credits (30 ECTS) per semester; 50-70 credits (25-35 ECTS) permitted with home university & Associate Dean approval (1 cr = 10 notional learning hrs).', 'School of Medicine, evening courses, and 5000-level PG modules (for UG) are excluded; subject-specific Political Science exchange students must take at least 1 module per semester in Political Science/International Relations; 3000-4000 Honours modules require prerequisites.', '["Coordinator email nomination (studyabroad@st-andrews.ac.uk)","Online application form","Recent academic transcript","Recent academic reference on letterheaded paper","Proof of English language proficiency (if applicable)"]', 'Traditional Scottish tutorial/seminar academic model with high independent workload (10 notional study hrs/credit) and compulsory matriculation; pre-advising 1 mo prior and online advising 1 wk prior.', NULL, NULL, NULL, 'Global Office (weekly Tue-Thu drop-ins, Student Mobility Officer appointments, social events), Student Immigration Service, Pre-advising/Advising, English language support, and Student Services.', 'For 2026 pattern (from 2025-26 partner sheet): January entry Nomination Sep 30, Application Sep 1 - Oct 31; September entry Nomination Apr 1, Application Feb 14 - Apr 15.', '{}', '{"academic_style":{"notes":null,"source_ref":"data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"Traditional Scottish tutorial/seminar academic model with high independent workload (10 notional study hrs/credit) and compulsory matriculation; pre-advising 1 mo prior and online advising 1 wk prior."},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:144","source_type":"excel_list","status":"verified","value":"Political Science"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:144","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:144","source_type":"excel_list","status":"verified","value":["UG"]},"available_terms":{"notes":"For St. ANdrews 3rd year, For outgoing Aucian 2nd and 3rd year","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"campus_type":{"notes":"Integrated university town/coastal setting descriptions came from third-party domains (studee.com); kept unknown.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:144","source_type":"excel_list","status":"verified","value":"St. Andrews"},"city_tier":{"notes":"St Andrews, Fife, Scotland; explicit population count not verified on st-andrews.ac.uk or Fact Sheet.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:144","source_type":"excel_list","status":"verified","value":"United Kingdom"},"course_catalog_url":{"notes":null,"source_ref":"https://www.st-andrews.ac.uk/subjects/modules/","source_type":"official_web","status":"verified","value":"https://www.st-andrews.ac.uk/subjects/modules/"},"course_restrictions_note":{"notes":null,"source_ref":"data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"School of Medicine, evening courses, and 5000-level PG modules (for UG) are excluded; subject-specific Political Science exchange students must take at least 1 module per semester in Political Science/International Relations; 3000-4000 Honours modules require prerequisites."},"credit_system_and_load":{"notes":null,"source_ref":"data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"Scottish credit framework: standard full-time load is 60 credits (30 ECTS) per semester; 50-70 credits (25-35 ECTS) permitted with home university & Associate Dean approval (1 cr = 10 notional learning hrs)."},"cross_references":[],"daily_life_english_friendliness":{"notes":"Not explicitly rated in Fact Sheet or st-andrews.ac.uk (UK English-speaking town & campus).","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Excel Col H specifies ''Political Science'' major rather than an AUC school code.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_majors":{"notes":"Excel scope specifies ''Political Science'' (housed in School of International Relations at St Andrews per st-andrews.ac.uk); subject-specific exchange requires >=1 module/sem in exchange subject (Fact Sheet p.3).","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:144","source_type":"excel_list","status":"verified","value":["Political Science"]},"english_course_availability":{"notes":"Scottish English-speaking university.","source_ref":"data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"full"},"english_course_list_url":{"notes":"All courses in https://www.st-andrews.ac.uk/subjects/modules/ are taught in English; no separate English-only URL.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":null,"source_ref":"https://www.st-andrews.ac.uk/subjects/entry/language-requirements/undergraduate/","source_type":"official_web","status":"partial","value":"Non-native English speakers must meet official undergraduate English requirements at https://www.st-andrews.ac.uk/subjects/entry/language-requirements/undergraduate/ (accepted test tables hosted online; note unverified third-party IELTS 7.0 quotes excluded)."},"est_monthly_living_local":{"notes":"Derived monthly cost from St Andrews official UG Cost of Attendance 9-month (38-wk) academic year budget divided by 9 months: University residence/utilities/food £12,208 + personal living expenses £3,800 = £16,008 / 9 = £1,778.67/month (~£1,779/mo; excludes ~£800 books/computer & travel). Note UKVI outside-London visa threshold is £1,171/mo (gov.uk).","source_ref":"https://www.st-andrews.ac.uk/study/fees-and-funding/undergraduate/cost-of-attendance/","source_type":"official_web","status":"partial","value":{"currency":"GBP","max":1779,"min":1779}},"excel_rows":[144],"exchange_page_url":{"notes":null,"source_ref":"https://www.st-andrews.ac.uk/study-abroad/","source_type":"official_web","status":"verified","value":"https://www.st-andrews.ac.uk/study-abroad/"},"excluded_majors":{"notes":"Exchange and ISAP students cannot take evening courses or School of Medicine modules; 5000-level PG modules closed to UG.","source_ref":"data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf#page=3","source_type":"fact_sheet","status":"verified","value":["Medicine","Evening degree courses","5000-level postgraduate taught courses (for UG)"]},"ext":{},"fact_sheet_status":{"drive_links":["https://drive.google.com/drive/folders/1STeYKk01QP6JZrXuhZgh5ZBETNGve5nn?usp=drive_link","https://drive.google.com/drive/folders/1HbwBGDWem64xnuD4qL5dHCq6o-WYHeLT","https://drive.google.com/drive/folders/1STeYKk01QP6JZrXuhZgh5ZBETNGve5nn"],"extracted_files":["data/raw/extracted/St. Andrews/Inbound Partner Factsheet.pdf.txt","data/raw/extracted/UoSt. Andrews/University of St Andrews.docx.txt"],"local_files":["data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf","data/raw/factsheets/UoSt. Andrews/University of St Andrews.docx"],"match_status":"matched","notes":null},"fall_term_dates":{"notes":null,"source_ref":"https://www.st-andrews.ac.uk/semester-dates/2026-2027/","source_type":"official_web","status":"verified","value":"AY 2026-2027 Martinmas (Semester 1): Teaching Sep 14 - Dec 21, 2026 (2025-26 PDF pattern shows early-Sep Orientation & residence exit Dec 23)."},"final_semester_allowed":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_grants_or_stipends":{"notes":"Note: China Scholarship Council guidance on p.2 applies to Chinese PhD/CSC candidates, not incoming AUC exchange.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_language_requirement":{"notes":null,"source_ref":"data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"English only; non-credit English language support available (cannot satisfy entry requirement, p.3)."},"housing_availability":{"notes":"Undergraduate exchange and study abroad students are guaranteed university accommodation if applying by Accommodation Services deadline (invitation arrives 48 hrs after offer acceptance).","source_ref":"data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"guaranteed"},"housing_notes":{"notes":null,"source_ref":"data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"University halls (£12,208 estimated 38-wk residence + food budget in 2026-27 per st-andrews.ac.uk Cost of Attendance); September confirmations issue in summer, January in December."},"instruction_languages":{"notes":null,"source_ref":"data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf#page=1","source_type":"fact_sheet","status":"verified","value":["English"]},"international_support_services":{"notes":null,"source_ref":"data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf#page=4","source_type":"fact_sheet","status":"verified","value":"Global Office (weekly Tue-Thu drop-ins, Student Mobility Officer appointments, social events), Student Immigration Service, Pre-advising/Advising, English language support, and Student Services."},"living_cost_usd_est":{"notes":"5-month estimate derived from monthly GBP range 1,779/month. ECB cross-rate 1 EUR = 1.1052 USD and 1 EUR = 0.83559 GBP -> 1 GBP = 1.322658 USD (2026-11-13, retrieved 2026-11-15 at https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html); 5-month USD est = 1,779.0 GBP * 5 * 1.322658 = 11,765.05 USD.","source_ref":"https://www.st-andrews.ac.uk/study/fees-and-funding/undergraduate/cost-of-attendance/","source_type":"official_web","status":"partial","value":11765.05},"mandatory_host_fees_and_insurance":{"notes":null,"source_ref":"data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf#page=2","source_type":"fact_sheet","status":"partial","value":"Student Visa (>6 mo) requires UK Immigration Health Surcharge (IHS) for NHS care; Standard Visitor/ETA (<=6 mo) does not pay IHS (may incur non-emergency NHS charges — private medical insurance advised)."},"min_gpa_host":{"notes":"Minimum average grade 3.2/4.0 GPA for undergraduate exchange applicants (PG: 3.3/4.0 US GPA / UK 2.1 / Europe 2.2 or B+, p.1).","source_ref":"data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf#page=1","source_type":"fact_sheet","status":"verified","value":3.2},"min_standing_note":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:144","source_type":"excel_list","status":"verified","value":"Excel Row 144 Col E specifies: ''For St. Andrews 3rd year, For outgoing Aucian 2nd and 3rd year''."},"nomination_deadlines":{"notes":null,"source_ref":"data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"For 2026 pattern (from 2025-26 partner sheet): January entry Nomination Sep 30, Application Sep 1 - Oct 31; September entry Nomination Apr 1, Application Feb 14 - Apr 15."},"official_name":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:144","source_type":"excel_list","status":"verified","value":"University of St. Andrews"},"official_website_url":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:144","source_type":"excel_list","status":"verified","value":"https://www.st-andrews.ac.uk/"},"region":{"notes":"From normalized manifest country/region mapping","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:144","source_type":"excel_list","status":"verified","value":"Europe"},"required_application_docs":{"notes":"Typical decision turnaround is 2-4 weeks (p.2).","source_ref":"data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf#page=1","source_type":"fact_sheet","status":"verified","value":["Coordinator email nomination (studyabroad@st-andrews.ac.uk)","Online application form","Recent academic transcript","Recent academic reference on letterheaded paper","Proof of English language proficiency (if applicable)"]},"schema_version":"1.0.0","seat_quota":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"shard":2,"short_name":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"slug":"university-of-st-andrews","spring_term_dates":{"notes":null,"source_ref":"https://www.st-andrews.ac.uk/semester-dates/2026-2027/","source_type":"official_web","status":"verified","value":"AY 2026-2027 Candlemas (Semester 2): Teaching Jan 25 - May 22, 2027."},"state_or_province":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"tuition_model":{"notes":"Official exchange students do not pay St Andrews tuition/programme fees (non-exchange ISAP students pay £11,975/sem or £23,950/yr in 2026-27).","source_ref":"https://www.st-andrews.ac.uk/study-abroad/inbound/fee-information/","source_type":"official_web","status":"verified","value":"auc_exchange_waiver"},"visa_lead_time_and_financial_proof":{"notes":"Note: UKVI outside-London financial threshold is £1,171/mo (https://www.st-andrews.ac.uk/study/support/student-immigration/).","source_ref":"data/raw/factsheets/St. Andrews/Inbound Partner Factsheet.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"Short-term <6 mo: Electronic Travel Authorisation (ETA) for non-visa nationals or Standard Visitor Visa. Longer >6 mo: UK Student Visa + Immigration Health Surcharge (NHS access)."}}');
INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('university-of-tartu', '[145]', 3, 'matched', '["data/raw/factsheets/University of Tartu/2025-2026/UT Information for Incoming Exchange Students 2025-26.pdf"]', '[]', 'University of Tartu', 'UT', 'Estonia', NULL, 'Tartu', 'Europe', 'active', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '["Estonian","English"]', 'substantial', 'Minimum B2 English required (TOEFL iBT 75, IELTS 5.5, or official home-institution letter; exempt if current degree at home university is taught in English).', 'None required for English-taught courses; free Estonian language courses offered.', NULL, 'AY 2025-2026 Autumn: Sep 1, 2025-Feb 1, 2026 (AY 2026-2027 Spring update published on ut.ee).', 'AY 2026-2027 Spring: Rec arrival Feb 3, Orientation Feb 4-5, Classes start Feb 8, 2027 (AY 2025-2026 Spring ran Feb 9-Jun 28, 2026 per PDF p.3).', NULL, NULL, NULL, 'EUR', 600, 800, 3868, 'partial', 'Mandatory valid health/travel medical insurance covering stay in Estonia.', 'lottery', 'Student Hostel (studenthostel.ee) applications open Jun 1-10 (Autumn) and Jan 2-10 (Spring), not guaranteed; twin rooms ~EUR 276-431/month (or dorms from ~EUR 175/mo; private EUR 300-700/mo).', NULL, NULL, 'Non-EU students require an Estonian Long-Stay (D) visa and mandatory travel medical insurance; consulate lead time and financial proof amounts not specified in fact sheet.', 'https://ut.ee/en', 'https://ut.ee/en/exchange-students', 'https://ut.ee/en/courses-taught-english-and-grading', NULL, 'ECTS credit system; minimum load 15 ECTS/semester for incoming exchange students.', 'Free course selection across faculties (subject to prerequisites and language level); min 15 ECTS/semester.', '["Official academic transcript in English","Passport or ID copy","B2 English proficiency proof (or English-medium letter)","Course list / Learning Agreement"]', NULL, NULL, NULL, NULL, 'Orientation course, free Estonian language courses, ESN & Buddy programme, counseling services, and Welcome Centre support.', 'Autumn / Academic Year: nomination Mar 31, application Apr 15; Spring: nomination Oct 15, application Nov 1.', '{}', '{"academic_style":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_scope_raw":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:145","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"available_terms":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"campus_type":{"notes":"Academic buildings distributed across Tartu; schema campus_type not explicitly stated in fact sheet.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:145","source_type":"excel_list","status":"verified","value":"Tartu"},"city_tier":{"notes":"Tartu city scale not explicitly categorized into schema city_tier options in fact sheet.","source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:145","source_type":"excel_list","status":"verified","value":"Estonia"},"course_catalog_url":{"notes":"Academic calendar and live catalog on https://ois2.ut.ee/#/dashboard.","source_ref":"data/raw/factsheets/University of Tartu/2025-2026/UT Information for Incoming Exchange Students 2025-26.pdf#page=4","source_type":"fact_sheet","status":"verified","value":"https://ut.ee/en/courses-taught-english-and-grading"},"course_restrictions_note":{"notes":null,"source_ref":"data/raw/factsheets/University of Tartu/2025-2026/UT Information for Incoming Exchange Students 2025-26.pdf#page=4","source_type":"fact_sheet","status":"verified","value":"Free course selection across faculties (subject to prerequisites and language level); min 15 ECTS/semester."},"credit_system_and_load":{"notes":null,"source_ref":"data/raw/factsheets/University of Tartu/2025-2026/UT Information for Incoming Exchange Students 2025-26.pdf#page=5","source_type":"fact_sheet","status":"verified","value":"ECTS credit system; minimum load 15 ECTS/semester for incoming exchange students."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Left blank in AUC partner Excel; confirm eligible schools with OIP.