INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('vienna-university-of-economics-and-business-wu', '[152]', 7, 'matched', '["data/raw/factsheets/Vienna University of Economics and Business/2026_2027/WU_Factsheet_2627.pdf","data/raw/factsheets/Vienna University of Economics and Business/2027-2028/WU_Factsheet_2728.pdf","data/raw/factsheets/Vienna University of Economics and Business/WU-Briefvorlage.pdf"]', '[]', 'Vienna University of Economics and Business (WU)', 'WU', 'Austria', NULL, 'Vienna', 'Europe', 'active', '["UG"]', NULL, 'BUSINESS', '["BUS"]', NULL, NULL, NULL, '["English","German"]', 'substantial', 'Minimum CEFR B2 English for Bachelor''s exchange (C1 for Master''s/PhD); WU does NOT require official language test certificates (home partner selection relied upon). RHET 1020 waiver not explicitly named, though certificate exemption simplifies eligibility.', 'None if taking English-taught courses; CEFR C1 German expected if selecting German-taught courses (no official certificate requested).', '["Fall","Spring","Summer"]', 'AY 2026-2027 Winter Semester: Pre-sem orientation Sep 7-8, 2026; Main Kickoff Sep 24-25, 2026; Teaching Oct 1, 2026-Jan 31, 2027.', 'AY 2026-2027 Summer Semester: Pre-sem orientation Feb 4-5, 2027; Main Kickoff Feb 22-23, 2027; Teaching Mar 1-Jun 27, 2027.', NULL, NULL, 'auc_exchange_waiver', 'EUR', 1250, 2050, 9117.9, 'partial', 'Mandatory Austrian Students'' Union (ÖH) dues: €25/semester (per Factsheet p. 5; ~€26 on wu.ac.at). Comprehensive health insurance required (ÖGK Student Self-Insurance ~€75/month per WU p. 5, €78.84/month per OeAD; entry travel insurance >=€30,000 needed for first month).', 'assisted', 'Off-campus student residences (OeAD Student Housing promo ''WUINCOMING'' waives registration fee per wu.ac.at) or private flats: €450-€900/month (from ~€437/month at OeAD).', NULL, NULL, 'Start 3-6 months prior (statutory decision period 90 days, extendable by 90 days). Non-EU stays up to 6 months require Visa D; >6 months require Residence Permit - Student. Monthly financial proof required by OeAD: €722.58/month (under age 24) or €1,308.39/month (age 24+), plus rent excess above €386.43/month.', 'https://www.wu.ac.at/io/en', 'https://www.wu.ac.at/en/programs/international-and-exchange-students/incoming-exchange-students', 'https://www.wu.ac.at/en/incoming-students/exchange-semester/academics/course-catalog/filter/95035/0/0/0/', 'https://www.wu.ac.at/en/incoming-students/exchange-semester/academics/course-catalog/filter/95035/0/0/0/', 'ECTS credit system: Bachelor load 24-30 ECTS/semester (Master 20-30 ECTS; max 36 ECTS excluding language courses). Austrian 1-5 grading scale (1 best, 5 fail).', 'Bachelor exchange students may ONLY take Bachelor-level courses (Master students only Master-level); online 3-phase registration with preference submission (spots not guaranteed).', '["Home university nomination","Online pre-enrollment & registration","Learning Agreement","Valid Passport / ID","Enrollment & arrival forms (post-acceptance)"]', 'Continuous-assessment ''PI'' (prüfungs­immanent) coursework with mandatory attendance and group/project assessments rather than a dedicated final exam week.', NULL, NULL, NULL, 'ÖH Buddy Network, Pre-semester German course (2 ECTS, free + €40 admin fee), semester German (€245), optional Orientation & Cultural Program (€350), and OeAD housing support.', 'Nominations: Winter May 1 (Full Year Apr 1), Summer Nov 1. Student pre-enrollment/application: Winter May 20, Summer Nov 20.', '{}', '{"academic_style":{"notes":null,"source_ref":"data/raw/factsheets/Vienna University of Economics and Business/2027-2028/WU_Factsheet_2728.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"Continuous-assessment ''PI'' (prüfungs­immanent) coursework with mandatory attendance and group/project assessments rather than a dedicated final exam week."},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:152","source_type":"excel_list","status":"verified","value":"BUSINESS"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:152","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:152","source_type":"excel_list","status":"verified","value":["UG"]},"available_terms":{"notes":"Fall/Spring/Summer","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:152","source_type":"excel_list","status":"verified","value":["Fall","Spring","Summer"]},"campus_type":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"