INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('virginia-polytechnic-institute-and-state-university-virginia-tech', '[154]', 8, 'matched', '["data/raw/factsheets/Virginia Tech/2026-2027/Inbound Exchange Fact Sheet 2026-27 (1).pdf","data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf","data/raw/factsheets/Virginia Tech/24-25 Virginia Tech (VT) fact sheet.pdf","data/raw/factsheets/Virginia Tech/Useful Info.docx"]', '[]', 'Virginia Polytechnic Institute and State University (Virginia Tech)', 'Virginia Tech', 'United States', 'Virginia', 'Blacksburg', 'North America', 'active', '["UG"]', 'Must be nominated by home partner university in good academic standing with limited or no failing grades or withdrawals; undergraduate exchange primarily (Master''s students accepted in special circumstances).', 'University-wide', '["ALL"]', '["ALL"]', '["Mechanical Engineering"]', NULL, '["English"]', 'full', 'UG minimums (`24-25 Fact Sheet#page=2`): IELTS 6.5 (no subscore <6.5), TOEFL iBT 80 (no subscore <16; CBT 233), Cambridge C1, or Duolingo 115. GR minimums: IELTS 6.5 (no subscore <6.5) or TOEFL iBT 90 (no subscore <20). For exchange only, 2026-27 Fact Sheet (#page=3) also accepts DAAD B2 in each category; native speakers and English-medium university students are exempt. RHET 1020 waiver not stated.', 'English proficiency required unless native speaker or enrolled at an English-medium university.', '["Fall","Spring"]', '2026-08-17 to 2026-12-16 (AY 2026-2027 Fall semester incl. required orientation and final exams; arrive by Aug 16, 2026)', '2027-01-11 to 2027-05-12 (AY 2026-2027 Spring semester incl. required orientation and final exams; arrive by Jan 10, 2027)', NULL, NULL, 'auc_exchange_waiver', 'USD', 2100, 2100, 10500.0, 'partial', 'Mandatory J-1 health insurance: VT Aetna plan (~$2,000/semester) or VT-approved comparable policy; VT Program Fee $75; visa/SEVIS ~$400. Note: Pamplin College of Business supplemental fee applies if taking 2+ business courses (~$1,275–$2,500/sem across 2026-27 factsheet variants). Required immunizations post-acceptance.', 'assisted', 'On-campus housing & standard meal plan ~$7,000/semester (not guaranteed); off-campus shared housing in Blacksburg $500–$1,200/month (VT does not arrange off-campus leases).', NULL, NULL, 'J-1 visa (Form DS-2019) required unless US citizen/LPR; passport must be valid >=6 months past program end (`#page=3`). Must document $10,500 USD per semester or $21,000 USD per academic year in personal or family/private sponsor liquid funds (`#page=4`).', 'http://www.vt.edu/', 'https://www.globaleducation.vt.edu/students/visiting-exchange.html', NULL, NULL, 'US credit hours: full-time UG minimum 12 credits/semester (with >=9 credits in-person; majority of courses within/pertaining to VT major for visa compliance). Letter grading 4.0 scale (A=90–100, C=70–79).', 'Mechanical Engineering excluded; taking 2+ courses (or 7+ credits) in Pamplin College of Business incurs a supplemental program fee (~$1,275–$2,500/sem); majority of courses must relate to student''s declared VT major.', '["VT Exchange Application (access emailed after partner nomination)","All post-secondary transcripts translated into English","Passport info page scan (valid >=6 months past program end)","Proof of English proficiency (unless native speaker or English-medium university)","List of 6–10 proposed VT courses","Financial proof for DS-2019 ($10,500/sem) & US green card copy if applicable"]', NULL, 'college_town', NULL, NULL, 'Global Education Office (GEO) pre-departure/J-1 advising, required week-long orientation, free airport pickup from Roanoke-Blacksburg Airport (ROA), Academic Advising, Writing Center, and Schiffert Health Center.', 'Fall Semester & Academic Year: nomination March 1, application April 1. Spring Semester: nomination September 1, application October 1.', '{}', '{"academic_style":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:154","source_type":"excel_list","status":"verified","value":"University-wide"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:154","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:154","source_type":"excel_list","status":"verified","value":["UG"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:154","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:154","source_type":"excel_list","status":"verified","value":"Blacksburg"},"city_tier":{"notes":"Blacksburg, Virginia described on VT pages as a classic college town.","source_ref":"https://www.globaleducation.vt.edu/students/visiting-exchange.html","source_type":"official_web","status":"verified","value":"college_town"},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:154","source_type":"excel_list","status":"verified","value":"United States"},"course_catalog_url":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"course_restrictions_note":{"notes":"Alternate Pamplin wording on #page=4.","source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"Mechanical Engineering excluded; taking 2+ courses (or 7+ credits) in Pamplin College of Business incurs a supplemental program fee (~$1,275–$2,500/sem); majority of courses must relate to student''s declared VT major."},"credit_system_and_load":{"notes":null,"source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"US credit hours: full-time UG minimum 12 credits/semester (with >=9 credits in-person; majority of courses within/pertaining to VT major for visa compliance). Letter grading 4.0 scale (A=90–100, C=70–79)."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"Excel agreement_scope_raw is ''University-wide'' (Mechanical Engineering excluded; Pamplin Business 2+ courses incur supplemental fee).","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:154","source_type":"excel_list","status":"verified","value":["ALL"]},"eligible_majors":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:154","source_type":"excel_list","status":"verified","value":["ALL"]},"english_course_availability":{"notes":null,"source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"full"},"english_course_list_url":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":"DAAD B2 and English-medium exemption confirmed in data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=3 and on https://www.globaleducation.vt.edu/students/visiting-exchange.html.","source_ref":"data/raw/factsheets/Virginia Tech/24-25 Virginia Tech (VT) fact sheet.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"UG minimums (`24-25 Fact Sheet#page=2`): IELTS 6.5 (no subscore <6.5), TOEFL iBT 80 (no subscore <16; CBT 233), Cambridge C1, or Duolingo 115. GR minimums: IELTS 6.5 (no subscore <6.5) or TOEFL iBT 90 (no subscore <20). For exchange only, 2026-27 Fact Sheet (#page=3) also accepts DAAD B2 in each category; native speakers and English-medium university students are exempt. RHET 1020 waiver not stated."},"est_monthly_living_local":{"notes":"Derived by dividing VT 2026-2027 1-semester DS-2019 proof-of-funding living cost ($10,500 USD/sem; $21,000/AY) by 5 months = $2,100/month. Factsheet itemizes on-campus housing & food ~$7,000/sem (off-campus shared rent $500–$1,200/mo) and mandatory Aetna health insurance ~$2,000/sem.","source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=4","source_type":"fact_sheet","status":"partial","value":{"currency":"USD","max":2100,"min":2100}},"excel_rows":[154],"exchange_page_url":{"notes":null,"source_ref":"https://www.globaleducation.vt.edu/students/visiting-exchange.html","source_type":"official_web","status":"verified","value":"https://www.globaleducation.vt.edu/students/visiting-exchange.html"},"excluded_majors":{"notes":"''Exchange students may take courses from all majors except Mechanical Engineering''.","source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=2","source_type":"fact_sheet","status":"verified","value":["Mechanical Engineering"]},"ext":{},"fact_sheet_status":{"drive_links":["https://drive.google.com/drive/folders/1tLHTTH7Pw49ukpbEb0Ua0XTEdhX3-_ZK"],"extracted_files":["data/raw/extracted/Virginia Tech/2026-2027/Inbound Exchange Fact Sheet 2026-27 (1).pdf.txt","data/raw/extracted/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf.txt","data/raw/extracted/Virginia Tech/24-25 Virginia Tech (VT) fact sheet.pdf.txt","data/raw/extracted/Virginia Tech/Useful Info.docx.txt"],"local_files":["data/raw/factsheets/Virginia Tech/2026-2027/Inbound Exchange Fact Sheet 2026-27 (1).pdf","data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf","data/raw/factsheets/Virginia Tech/24-25 Virginia Tech (VT) fact sheet.pdf","data/raw/factsheets/Virginia Tech/Useful Info.docx"],"match_status":"matched","notes":"Excel Col H blank, but matching public folder found in Drive master folder"},"fall_term_dates":{"notes":null,"source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"2026-08-17 to 2026-12-16 (AY 2026-2027 Fall semester incl. required orientation and final exams; arrive by Aug 16, 2026)"},"final_semester_allowed":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_grants_or_stipends":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"host_language_requirement":{"notes":null,"source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"English proficiency required unless native speaker or enrolled at an English-medium university."},"housing_availability":{"notes":"On-campus housing is NOT guaranteed for exchange students (may request during application; on-campus residents must purchase a meal plan; overflow lounge housing used in high-demand terms per Useful Info.docx). Off-campus shared rent ~$500–$1,200/mo.","source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=4","source_type":"fact_sheet","status":"verified","value":"assisted"},"housing_notes":{"notes":null,"source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=4","source_type":"fact_sheet","status":"verified","value":"On-campus housing & standard meal plan ~$7,000/semester (not guaranteed); off-campus shared housing in Blacksburg $500–$1,200/month (VT does not arrange off-campus leases)."},"instruction_languages":{"notes":null,"source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=3","source_type":"fact_sheet","status":"verified","value":["English"]},"international_support_services":{"notes":"Free ROA airport pickup confirmed in 24-25 VT Fact Sheet #page=4; Academic Advising & Writing Center on #page=2.","source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"Global Education Office (GEO) pre-departure/J-1 advising, required week-long orientation, free airport pickup from Roanoke-Blacksburg Airport (ROA), Academic Advising, Writing Center, and Schiffert Health Center."},"living_cost_usd_est":{"notes":"Official 2026-2027 1-semester exchange DS-2019 living budget / proof of funding ($10,500.00 USD per semester; $21,000 USD full year), already in USD (recorded 2026-11-15).","source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=4","source_type":"fact_sheet","status":"partial","value":10500.0},"mandatory_host_fees_and_insurance":{"notes":"Pamplin fee noted as ~$2,500 (2+ courses) on #page=2 and $1,275 on #page=4 ($1,275 for 7+ credits in alternate 2026-27 PDF copy); immunizations in 24-25 PDF #page=2.","source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=4","source_type":"fact_sheet","status":"verified","value":"Mandatory J-1 health insurance: VT Aetna plan (~$2,000/semester) or VT-approved comparable policy; VT Program Fee $75; visa/SEVIS ~$400. Note: Pamplin College of Business supplemental fee applies if taking 2+ business courses (~$1,275–$2,500/sem across 2026-27 factsheet variants). Required immunizations post-acceptance."},"min_gpa_host":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"min_standing_note":{"notes":"UG/special Master''s rule stated on #page=1.","source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"Must be nominated by home partner university in good academic standing with limited or no failing grades or withdrawals; undergraduate exchange primarily (Master''s students accepted in special circumstances)."},"nomination_deadlines":{"notes":null,"source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"Fall Semester & Academic Year: nomination March 1, application April 1. Spring Semester: nomination September 1, application October 1."},"official_name":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:154","source_type":"excel_list","status":"verified","value":"Virginia Polytechnic Institute and State University (Virginia Tech)"},"official_website_url":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:154","source_type":"excel_list","status":"verified","value":"http://www.vt.edu/"},"region":{"notes":"From normalized manifest country/region mapping","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:154","source_type":"excel_list","status":"verified","value":"North America"},"required_application_docs":{"notes":"Financial proof $10,500/sem detailed on #page=4.","source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=3","source_type":"fact_sheet","status":"verified","value":["VT Exchange Application (access emailed after partner nomination)","All post-secondary transcripts translated into English","Passport info page scan (valid >=6 months past program end)","Proof of English proficiency (unless native speaker or English-medium university)","List of 6–10 proposed VT courses","Financial proof for DS-2019 ($10,500/sem) & US green card copy if applicable"]},"schema_version":"1.0.0","seat_quota":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"shard":8,"short_name":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:154","source_type":"excel_list","status":"verified","value":"Virginia Tech"},"slug":"virginia-polytechnic-institute-and-state-university-virginia-tech","spring_term_dates":{"notes":null,"source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=2","source_type":"fact_sheet","status":"verified","value":"2027-01-11 to 2027-05-12 (AY 2026-2027 Spring semester incl. required orientation and final exams; arrive by Jan 10, 2027)"},"state_or_province":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:154","source_type":"excel_list","status":"verified","value":"Virginia"},"tuition_model":{"notes":"Incoming bilateral exchange students pay regular tuition to their home university (host tuition waived/adjusted), while covering VT Program Fee ($75), housing/food, health insurance, and Pamplin business fee if applicable.","source_ref":"https://www.globaleducation.vt.edu/students/visiting-exchange.html","source_type":"official_web","status":"verified","value":"auc_exchange_waiver"},"visa_lead_time_and_financial_proof":{"notes":null,"source_ref":"data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=4","source_type":"fact_sheet","status":"verified","value":"J-1 visa (Form DS-2019) required unless US citizen/LPR; passport must be valid >=6 months past program end (`#page=3`). Must document $10,500 USD per semester or $21,000 USD per academic year in personal or family/private sponsor liquid funds (`#page=4`)."}}');
INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('vrije-universiteit-amsterdam', '[155]', 1, 'matched', '["data/raw/factsheets/Vrije Universiteit Amsterdam/Vrije Universiteit Amsterdam.pdf"]', '[]', 'Vrije Universiteit Amsterdam', 'VU Amsterdam', 'Netherlands', NULL, 'Amsterdam', 'Europe', 'active', '["UG","GR"]', 'Students taking Master''s-level courses MUST hold a completed Bachelor''s degree prior to the start of exchange (Bachelor students are barred from MA courses).', 'University-wide', '["ALL"]', '["ALL"]', NULL, NULL, '["English","Dutch"]', 'substantial', 'CEFR C1 required (TOEFL iBT >=92, Academic IELTS >=6.5). Bachelor exchange: proficiency verified by home university. Master''s courses: formal test certificate mandatory unless student completed >=2 years of a fully English-taught programme within 2 years prior to exchange (no explicit RHET 1020 exemption stated; AUC English-medium proof aligns with 2-year exemption).', 'CEFR C1 Dutch (NT2) required only if taking Dutch-taught courses; optional Dutch NT2 courses available via https://vu.nl/en/education/vu-nt2.', '["Fall","Spring"]', 'Semester 1 (AY 2026-2027): Period 1 31 Aug - 23 Oct 2026; Period 2 26 Oct - 18 Dec 2026; Period 3 4 Jan - 29 Jan 2027 (Academic Opening 31 Aug 2026).', 'Semester 2 (AY 2026-2027): Period 4 1 Feb - 25 Mar 2027; Period 5 30 Mar - 28 May 2027; Period 6 31 May - 25 Jun 2027.', NULL, NULL, NULL, 'EUR', 1000, 2000, 8289.0, 'partial', 'EUR 250/semester housing handling fee if using VU accommodation service (first paid, first served). Health insurance is mandatory (AON recommended via https://www.students-insurance.eu/educationalinstitutions/en/; EHIC accepted for EU students).', 'assisted', 'Assisted VU accommodation (https://vu.nl/en/education/more-about/exchange-accommodation), limited and NOT guaranteed (first paid, first served; EUR 250/semester handling fee; strict application deadline for housing/visa; full-period rental contracts only).', NULL, NULL, 'Vrije Universiteit Amsterdam applies for the student''s visa and/or residence permit on their behalf.', 'https://vu.nl/nl', 'https://vu.nl/en/education/more-about/nomination-and-application', 'https://vu.nl/en/education/more-about/courses', NULL, 'ECTS (Dutch 1-10 grading scale; 6.0 minimum pass).', 'Psychology and School of Business & Economics (SBE) have limited exchange capacity (majors prioritized); Bachelor students are barred from taking Master''s courses.', '["Home university nomination + online application","Bachelor''s degree copy or completion confirmation statement (if taking Master''s courses)","Formal English test proof (if taking Master''s courses and not exempt)"]', NULL, NULL, NULL, NULL, 'Arrival & Introduction days, Dutch NT2 courses (https://vu.nl/en/education/vu-nt2), student counselling, and disability support.', 'Semest