INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('wellesley-college', '[161]', 4, 'matched', '["data/raw/factsheets/Wellesley College/2025-2026/[Wellesley] Factsheet for Exchange Students 2025-2026.pdf","data/raw/factsheets/Wellesley College/2026-2027/Factsheet for Exchange Students 2026-2027.pdf","data/raw/factsheets/Wellesley College/Wellesley College.docx"]', '[]', 'Wellesley College', NULL, 'United States', 'Massachusetts', 'Wellesley', 'North America', 'active', '["UG"]', 'Must be nominated by partner university (cannot transfer to Wellesley); women''s college gender policy considers applicants who consistently live and identify as women (cisgender, trans, and nonbinary students who consistently live and identify as women).', 'University-wide', '["ALL"]', '["ALL"]', '["Computer Science"]', NULL, '["English"]', 'full', 'Non-native English speakers must submit proof of English proficiency: TOEFL score of 100 or equivalent on a comparable test.', 'None (instruction is in English)', '["Fall","Spring"]', 'AY 2026-2027 Fall 2026: Arrival Aug 21, 2026; Classes Aug 31 – Dec 9, 2026; End of exam period Dec 17, 2026.', 'AY 2026-2027 Spring 2027: Arrival mid-January (TBA); Classes Jan 25 – May 5, 2027; End of exam period May 13, 2027.', NULL, NULL, 'auc_exchange_waiver', 'USD', 2525.6, 2525.6, 12628.0, 'partial', 'Mandatory Student Activity Fee ($360/year per SFS), Wellesley meal plan, automatic Wellesley Student Health Insurance Plan (unless waived with US-based MA/J-1 compliant plan), and Health History & Immunization Form.', 'guaranteed', 'Mandatory on-campus furnished residence hall (typically double occupancy) + automatic Wellesley meal plan (4 dining halls); room/board billed per semester ($12,020 housing + $11,186 meals/yr in 2026-2027).', NULL, NULL, 'J-1 DS-2019 requires Certification of Finances showing ~$14,000 USD/semester (inclusive of activity fee, housing, meal plan, and health insurance) plus $1,250 USD for books/supplies/personal expenses.', 'http://www.wellesley.edu/', 'https://www.wellesley.edu/interstudy/exchange/incoming', 'https://catalog.wellesley.edu/landing.php', NULL, 'Wellesley unit system: 1 Wellesley unit = 4 US credit hours = 7.5 ECTS (~12 hrs/week work); normal full load is 4 classes (~4 units); minimum 3 units required to maintain immigration status and housing.', 'Computer Science courses are NOT open to exchange students; cross-registration limited to max 1 course/semester at MIT, Olin College of Engineering, Babson College, or Brandeis University (MIT UROP excluded; single-semester students strongly encouraged to take all courses at Wellesley).', '["Online exchange application form","Photocopy of passport ID page","Official transcripts from all previous university coursework (English translation if applicable)","Proof of English proficiency (TOEFL 100 or equivalent, non-native speakers)","Certification of Finances & Health/Immunization Form (onboarding)"]', 'US-style liberal arts', NULL, NULL, NULL, 'Mandatory Orientation & Slater International Center J-1 check-in, Class Dean academic advising, and Accessibility & Disability Resources.', 'AY 2026-2027 Fall / Full Year: Nomination Feb 15, 2026 / Application Mar 15, 2026; Spring 2027: Nomination Sep 15, 2026 / Application Oct 1, 2026.', '{}', '{"academic_style":{"notes":null,"source_ref":"data/raw/factsheets/Wellesley College/2026-2027/Factsheet for Exchange Students 2026-2027.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"US-style liberal arts"},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:161","source_type":"excel_list","status":"verified","value":"University-wide"},"agreement_status":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:161","source_type":"excel_list","status":"verified","value":"active"},"agreement_student_levels":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:161","source_type":"excel_list","status":"verified","value":["UG"]},"available_terms":{"notes":"Fall/Spring","source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:161","source_type":"excel_list","status":"verified","value":["Fall","Spring"]},"campus_type":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"citizenship_restrictions":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"city":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:161","source_type":"excel_list","status":"verified","value":"Wellesley"},"city_tier":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"country":{"notes":null,"source_ref":"data/raw/partner_list_extracted.json#Universities List!rows:161","source_type":"excel_list","status":"verified","value":"United States"},"course_catalog_url":{"notes":"Course catalog link embedded on page 3 (also https://www.wellesley.edu/academics/catalog on page 1).","source_ref":"data/raw/factsheets/Wellesley College/2026-2027/Factsheet for Exchange Students 2026-2027.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"https://catalog.wellesley.edu/landing.php"},"course_restrictions_note":{"notes":null,"source_ref":"data/raw/factsheets/Wellesley College/2026-2027/Factsheet for Exchange Students 2026-2027.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"Computer Science courses are NOT open to exchange students; cross-registration limited to max 1 course/semester at MIT, Olin College of Engineering, Babson College, or Brandeis University (MIT UROP excluded; single-semester students strongly encouraged to take all courses at Wellesley)."},"credit_system_and_load":{"notes":null,"source_ref":"data/raw/factsheets/Wellesley College/2026-2027/Factsheet for Exchange Students 2026-2027.pdf#page=3","source_type":"fact_sheet","status":"verified","value":"Wellesley unit system: 1 Wellesley unit = 4 US credit hours = 7.5 ECTS (~12 hrs/week work); normal full load is 4 classes (~4 units); minimum 3 units required to maintain immigration status and housing."},"cross_references":[],"daily_life_english_friendliness":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"eligible_auc_schools":{"notes":"University-wide UG exchange agreement (Fall/Spring); note Wellesley women''s college gender policy in citizenship_restrictions.","source_ref":"data/raw/partner_list_extracted.json#row=161","source_type":"excel_list","status":"verified","value":["ALL"]},"eligible_majors":{"notes":"Open across 55 majors (~1,000+ courses) EXCEPT Computer Science.","source_ref":"data/raw/partner_list_extracted.json#row=161","source_type":"excel_list","status":"verified","value":["ALL"]},"english_course_availability":{"notes":null,"source_ref":"data/raw/factsheets/Wellesley College/2026-2027/Factsheet for Exchange Students 2026-2027.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"full"},"english_course_list_url":{"notes":null,"source_ref":null,"source_type":"unknown","status":"unknown","value":null},"english_proficiency_and_rhet1020":{"notes":null,"source_ref":"data/raw/factsheets/Wellesley College/2026-2027/Factsheet for Exchange Students 2026-2027.pdf#page=1","source_type":"fact_sheet","status":"verified","value":"Non-native English speakers must submit proof of English proficiency: TOEFL score of 100 or equivalent on a comparable test."},"est_monthly_living_local":{"notes":"Wellesley 2026-2027 SFS budget lists Academic Year Housing ($12,020) + Meals ($11,186) + Books ($800) + Personal Expenses ($1,250) = $25,256/year ($12,628/semester), prorated across a 5-month semester = $2,525.60 USD/month.","source_ref":"https://www.wellesley.edu/sfs/cost","source_type":"official_web","status":"partial","value":{"currency":"USD","max":2525.6,"min":2525.6}},"excel_rows":[161],"exchange_page_url":{"notes":null,"source_ref":"https://www.wellesley.edu/interstudy/exchange/incoming","source_type":"official_web","status":"verified","value":"https://www.wellesley.edu/interstudy/exchange/incoming"},"excluded_majors":{"notes":"2026-2027 Factsheet page 3 explicitly states: ''Exchange students are NOT eligible to enroll in Computer Science courses.''","source_ref":"data/raw/factsheets/Wellesley College/2026-2027/Factsheet for Exchange Students 2026-2027.pdf#page=3","source_type":"fact_sheet","status":"verified","value":["Computer Science"]},"ext":{},"fact_sheet_status":{"drive_links":["https://drive.google.com/open?id=1hwOwMa-qSffSkZuH6_ZrQ2axWK0Q1XN1","https://drive.google.com/drive/folders/1Dy3msT6bpUpqQufyn3nR8drc5fSEA7yZ"],"extracted_files":["data/raw/extracted/Wellesley College/2025-2026/[Wellesley] Factsheet for Exchange Students 2025-2026.pd