INSERT OR REPLACE INTO universities (slug, excel_rows_json, shard, fact_sheet_match_status, fact_sheet_files_json, cross_references_json, official_name, short_name, country, state_or_province, city, region, agreement_status, agreement_student_levels_json, min_standing_note, agreement_scope_raw, eligible_auc_schools_json, eligible_majors_json, excluded_majors_json, min_gpa_host, instruction_languages_json, english_course_availability, english_proficiency_and_rhet1020, host_language_requirement, available_terms_json, fall_term_dates, spring_term_dates, final_semester_allowed, seat_quota, tuition_model, est_monthly_living_currency, est_monthly_living_min, est_monthly_living_max, living_cost_usd_est, living_cost_usd_est_status, mandatory_host_fees_and_insurance, housing_availability, housing_notes, host_grants_or_stipends, citizenship_restrictions, visa_lead_time_and_financial_proof, official_website_url, exchange_page_url, course_catalog_url, english_course_list_url, credit_system_and_load, course_restrictions_note, required_application_docs_json, academic_style, city_tier, campus_type, daily_life_english_friendliness, international_support_services, nomination_deadlines, ext_json, metadata_json) VALUES ('yildiz-technical-university', '[163]', 3, 'none', '[]', '[]', 'Yildiz Technical University', 'YTU', 'Turkey', NULL, 'Istanbul', 'Europe', 'active', NULL, NULL, 'AENG major', '["SSE"]', '["AENG (Architectural Engineering)"]', NULL, NULL, '["Turkish","English"]', 'substantial', 'B1–B2 English level required/recommended for English-taught courses.', 'B1 Turkish required/recommended for Turkish-taught courses; B1–B2 English for English-taught courses.', NULL, 'Fall semester typically runs late September–mid-January.', 'Spring semester typically starts around February with exams extending through June.', NULL, NULL, 'auc_exchange_waiver', NULL, NULL, NULL, NULL, 'unknown', 'Valid health insurance covering the entire mobility period is required (especially for Turkish residence permit applications); students pay residence permit card fees and tax.', 'off_campus_only', 'No university dormitory spots for incoming exchange students; students rent shared apartments or private Istanbul dormitories (landlords typically require 1–2 months security deposit upfront), with support from ESN Yildiz and buddy program.', NULL, NULL, 'Foreign exchange students staying >90 days must apply online for a Turkish student residence permit via https://e-ikamet.goc.gov.tr/ regardless of nationality, holding full-period health insurance and paying card/tax fees (extensions typically applied ~60 days before expiry).', 'https://www.yildiz.edu.tr/en', 'https://erasmus.yildiz.edu.tr/page/Incoming-Student/232', 'https://www.bologna.yildiz.edu.tr', NULL, 'ECTS credit system; standard full-time exchange load is 30 ECTS per semester.', NULL, '["Online application via www.ytuerasmus.yildiz.edu.tr","Signed and stamped Learning Agreement (PDF)","Headshot ID photo (JPG)","Copy of passport ID page"]', 'Turkish public technical university following Bologna ECTS frameworks across Istanbul campuses (Faculty of Architecture / AENG is located at historic Yıldız Campus in Beşiktaş; other faculties at Davutpaşa Campus).', NULL, 'multi_campus', NULL, 'ESN Yildiz and buddy program support for incoming exchange students (housing assistance, residence permit guidance, welcome activities).', 'Fall/AY: nom Apr 30 / app Jun 1–30; Spring: nom Sep 30 / app Dec 1–31 (Nov 1–30 also noted on prior cycle info; online portal www.ytuerasmus.yildiz.edu.tr).', '{}', '{"academic_style":{"notes":null,"source_ref":"https://www.bologna.yildiz.edu.tr","source_type":"official_web","status":"partial","value":"Turkish public technical university following Bologna ECTS frameworks across Istanbul campuses (Faculty of Architecture / AENG is located at historic Yıldız Campus in Beşiktaş; other faculties at Davutpaşa Campus)."},"agreement_scope_raw":{"notes":null,"source_ref":"data/raw/partner_list_extracte