INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'course_restrictions_note', 3, 'verified', 'official_web', 'https://international.au.dk/education/admissions/exchange/admission-to-aarhus-university/course-information-restrictions', '1-faculty/1-department rule corroborated in Brev.pdf#page=3; Law/Dentistry/Medicine subject rules come from AU official web course-information-restrictions.', '"Students must select courses from 1 faculty only (and most faculties allow 1 department only, per Brev.pdf#page=3). Law offers no Bachelor-level English courses (Master-level Law requires >=100 ECTS); Dentistry is Danish-only via faculty agreements; Medicine international semester has limited clinical capacity and requires Bachelor/3 years Medicine, C1 English, and clinical experience."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'credit_system_and_load', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Aarhus University/2026-2027/Brev.pdf#page=3', NULL, '"ECTS; full-time study workload is 30 ECTS per semester (Danish grading scale: 12, 10, 7, 4, 02 passing; 00, -03 fail; some pass/fail exams)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'daily_life_english_friendliness', 4, 'verified', 'official_web', 'https://international.au.dk/about-au/profile/international-staff-and-researchers/life-in-denmark', 'au.dk explicitly notes Denmark ranks among the highest countries globally in English proficiency and accommodates English speakers in daily life and university services.', '"high"');
