INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'english_proficiency_and_rhet1020', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Aarhus University/2026-2027/Brev.pdf#page=3', NULL, '"Expected English proficiency comparable to TOEFL iBT 83 or IELTS 6.5 (no RHET 1020 exemption stated). Documentation varies by faculty: Aarhus BSS (none required); Health (none required); Arts (required for English degree programme only); Natural Sciences and Technical Sciences (documentation may be required)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'est_monthly_living_local', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Aarhus University/2026-2027/Brev.pdf#page=4', 'AY 2026-2027 Fact Sheet p.4 publishes ''Monthly estimate 1.000'' EUR (itemized breakdown sums to 805-1,055 EUR: Housing 350-600 EUR, Meals 300 EUR, Books 25 EUR, Local transportation 30 EUR, Personal expenses incl. insurance 100 EUR). Official web also notes AU Housing ~3,000-4,000 DKK/mo and SIRI visa financial threshold DKK 7,086/mo.', '{"currency":"EUR","max":1000,"min":1000}');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'exchange_page_url', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Aarhus University/2026-2027/Brev.pdf#page=4', 'Official incoming exchange URL embedded as hyperlink in AY 2026-2027 Fact Sheet p.4.', '"https://international.au.dk/education/admissions/exchange"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'excluded_majors', 1, 'verified', 'official_web', 'https://international.au.dk/education/admissions/exchange/admission-to-aarhus-university/course-information-restrictions', 'Dentistry (Danish-only) and Medicine (limited clinical capacity) exclusions documented on AU Course Information & Restrictions page; AY 2026-2027 Fact Sheet (Brev.pdf#page=3) separately states the 1-faculty/1-department rule.', '["Dentistry (faculty-level agreement required; Danish only)","Medicine (limited clinical capacity; specific bilateral placement required)"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'fall_term_dates', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Aarhus University/2026-2027/Brev.pdf#page=2', NULL, '"Autumn semester (AY 2026-2027): Mandatory AU Intro Days late-August/early-September; Courses late-August to late-January; Exam period mid-December to late-January (exact dates vary by study programme)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'final_semester_allowed', 1, 'unknown', 'unknown', NULL, NULL, NULL);
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'host_grants_or_stipends', 2, 'unknown', 'unknown', NULL, 'Erasmus+ is EU-programme-specific and Danish Government Scholarships apply to full-degree students; no incoming bilateral exchange grant confirmed for AUC students.', NULL);
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'host_language_requirement', 1, 'verified', 'official_web', 'https://international.au.dk/education/admissions/exchange/admission-to-aarhus-university/course-information-restrictions', 'Dentistry Danish-language rule documented on AU Course Information & Restrictions page; optional Danish language courses linked in Brev.pdf#page=4.', '"None required for English-taught exchange courses (Danish required only for Danish-taught courses such as Dentistry; optional Danish language courses offered)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'housing_availability', 2, 'verified', 'official_web', 'https://international.au.dk/life/locations/housing/auhousing/exchange-student/', 'AU Housing assists incoming exchange students via an optional portal integrated with admission, but explicitly states housing is not guaranteed.', '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'housing_notes', 2, 'verified', 'official_web', 'https://international.au.dk/life/locations/housing/auhousing/exchange-student/', 'Timing and 350-600 EUR estimate also corroborated in Brev.pdf#page=2 and #page=4.', '"Optional AU Housing application is integrated into the admission application (deadlines Apr 1 Autumn / Oct 1 Spring). No housing guarantee; offers sent by Jul 1 (Autumn) and Dec 15 (Spring) with a 48-hour acceptance window requiring credit/debit card payment of 600 DKK non-refundable booking fee + first month''s rent (deposit of 1-3 months'' rent billed with 2nd month''s rent). Estimated AU Housing rent 350-600 EUR/mo (~3,000-4,000 DKK/mo); AU advises applying to Student Housing Aarhus (Ungdomsbolig Aarhus) as backup."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'instruction_languages', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Aarhus University/2026-2027/Brev.pdf#page=3', NULL, '["English","Danish"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Aarhus University/2026-2027/Brev.pdf#page=2', 'Further student arrival and mentor/language details on Brev.pdf#page=4.', '"Mandatory AU Intro Days (orientation before semester start with CPR/residence guidance, campus tours, social events), mentor/buddy contact via email where applicable, AU International Student Guide app, and Danish language courses."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'living_cost_usd_est', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Aarhus University/2026-2027/Brev.pdf#page=4', 'Converted from AU AY 2026-2027 official monthly estimate of 1,000 EUR over 5 months: 1000 EUR * 5 * FX rate 1.1052 USD/EUR = 5,526.00 USD. FX rate 1 EUR = 1.1052 USD (and 1 EUR = 7.4756 DKK; 1 DKK = 0.147841 USD) from ECB Euro reference exchange rates for 2026-11-13 (latest prior to 2026-11-15), retrieved 2026-11-15 at https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html.', '5526.0');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Aarhus University/2026-2027/Brev.pdf#page=3', NULL, '"No mandatory host tuition or student union fee stated for exchange students. Stays >3 months are covered by Danish Health Insurance once issued a CPR number; stays <3 months require private health insurance. Students must arrange private travel, personal belongings, accident, and third-party liability insurance."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'min_gpa_host', 1, 'unknown', 'unknown', NULL, 'No centralized university-wide minimum GPA published in AY 2026-2027 fact sheet or AU incoming exchange pages.', NULL);
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'min_standing_note', 1, 'verified', 'official_web', 'https://international.au.dk/education/admissions/exchange/admission-to-aarhus-university/course-information-restrictions', NULL, '"Bachelor-level courses are open to 2nd- and 3rd-year students (typically >=30 ECTS in field); Master-level courses are reserved for Master''s students (>=60 ECTS in field; Law Master''s >=100 ECTS)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'nomination_deadlines', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Aarhus University/2026-2027/Brev.pdf#page=2', 'Also listed in nomination summary table on Brev.pdf#page=1.', '"Autumn semester (AY 2026-2027): Nomination 15 Feb - 25 Mar, Application 1 Mar - 1 Apr. Spring semester (AY 2026-2027): Nomination 15 Aug - 25 Sep, Application 1 Sep - 1 Oct (housing application deadline is the same)."');
