INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('aarhus-university', 'required_application_docs', 3, 'verified', 'official_web', 'https://international.au.dk/education/admissions/exchange/admission-to-aarhus-university/how-to-apply', 'Required document checklist verified at international.au.dk (and .../education/exchange/how-to-apply); faculty-specific English documentation rules detailed in Brev.pdf#page=3.', '["Online application via AU portal (post-nomination)","Official university transcript of records (PDF in English)","Bachelor''s degree diploma & transcript (if already earned and applying for Master-level courses)","Documentation of English language skills (faculty/department-dependent; not required for Aarhus BSS or Health)","Passport number (entered in the online application form)"]');
