INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('akita-international-university', 'est_monthly_living_local', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Akita/Akita International University.pdf#page=3', 'Derived monthly cost from AY 2020-2021 Fact Sheet p.3 exact printed semester items divided by 5 months: Min = Komachi Residence 90,000 + Bedding & Cleaning 20,000 + Initial 2-wk meal plan 14,670 + 10-meal plan 60,000 + Textbooks 15,000 = 199,670 JPY / 5 = 39,934 JPY/mo; Max = Sakura Village (Fall) 184,000 + Bedding & Cleaning 20,000 + Initial 2-wk meal plan 14,670 + 21-meal plan 102,690 + Textbooks 50,000 = 371,360 JPY / 5 = 74,272 JPY/mo (excludes refundable 20,000 JPY deposit and 20,000 JPY activity fee; newer aiu.ac.jp pages cite textbooks ~50,000-70,000 JPY and housing ~130,000-215,000+ JPY/semester).', '{"currency":"JPY","max":74272,"min":39934}');
