INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('akita-international-university', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Akita/Akita International University.pdf#page=1', NULL, '"Center for International Affairs inbound exchange team, free arrival shuttle pickup from Akita Airport/JR station, orientation week, and residential life support."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('akita-international-university', 'living_cost_usd_est', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Akita/Akita International University.pdf#page=3', '5-month estimate derived from monthly JPY range 39,934-74,272 (midpoint 57,103.0)/month. ECB cross-rate 1 EUR = 1.1052 USD and 1 EUR = 176.83 JPY -> 1 JPY = 0.006250 USD (2026-11-13, retrieved 2026-11-15 at https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html); 5-month USD est = 57,103.0 JPY * 5 * 0.006250 = 1,784.49 USD.', '1784.49');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('akita-international-university', 'mandatory_host_fees_and_insurance', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Akita/Akita International University.pdf#page=3', NULL, '"General deposit 20,000 JPY (partly refundable), International student activity fee 20,000 JPY/semester (non-refundable), initial 2-week meal plan 14,670 JPY (2020-21 PDF p.3); mandatory Japanese National Health Insurance plus Gakkensai/Inbound Futai-Gakuso insurance per aiu.ac.jp/en/st/financial/."');
