INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'course_restrictions_note', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=14', 'Priority consideration recommendation continued on data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=15.', '"Course availability depends on seats and AU faculty advisor approval (Business majors and students without an AU advisor coordinate with the Auburn Abroad Exchange Coordinator); specific courses cannot be guaranteed."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'credit_system_and_load', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=15', NULL, '"US semester credit hours; J-1 full-time minimum is 12 credit hours/semester for undergraduates (typically 4-5 classes) and 9 credit hours/semester for graduate students (typically 3 classes)."');
