INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'english_proficiency_and_rhet1020', 1, 'partial', 'fact_sheet', 'data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=7', NULL, '"Proof of English proficiency is required in the incoming exchange application checklist; specific numeric minimum test scores and RHET 1020 equivalency are not stated in the AY23-24 incoming exchange guide."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'est_monthly_living_local', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=9', 'Derived from AY2024-25 semester estimate in Guide p.9 divided across a 5-month semester: Housing $4,000-$6,500 + Meal Plan $500-$1,500 + Additional Meals $1,000 + Spending Money $2,000 = $7,500-$11,000/semester ($1,500-$2,200/month). Excludes $1,000/sem mandatory insurance; Auburn ISSS 2027-2028 COA (https://www.auburn.edu/academic/international/isss/cost-of-attendance.html) lists $15,000/yr living expenses.', '{"currency":"USD","max":2200.0,"min":1500.0}');
