INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'fall_term_dates', 1, 'verified', 'official_web', 'https://www.auburn.edu/academic/registrar/pdf/calendar/2026-2027-calendar.pdf', 'Pre-class arrival/orientation timing from data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=6.', '"Fall 2026: Classes Aug 17 - Dec 4, 2026; Final Exams Dec 7 - Dec 11, 2026 (2-day orientation before classes; arrival 3-4 days prior)."');
