INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'host_language_requirement', 1, 'partial', 'fact_sheet', 'data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=14', 'Application checklist item ''Proof of English'' listed in Guide p.7.', '"English (primary language of instruction; proof of English required in application)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'housing_availability', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=12', 'Guide p.12 notes limited on-campus availability via University Housing portal (recommended) alongside independent off-campus search options.', '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=12', 'Holiday-break recommendation (160 Ross) and arrival hotel guidance on data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=11; meal plan cost on data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=9.', '"On-campus housing is recommended (limited availability; opens ~Feb 15 for Fall / Sept for Spring via https://universityhousing.auburn.edu/; Quad, Village, South Donahue suites, and 160 Ross apartment-style recommended as open during holiday breaks; AY2024-25 rates $4,000-$6,500/semester incl. utilities/internet/laundry). Required meal plan ($500-$1,500/sem). Off-campus resources at https://offcampushousing.auburn.edu/housing."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'instruction_languages', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=14', NULL, '["English"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=5', 'ISSS details on data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=10 & #page=23; shuttle on #page=11; clubs & GTA on #page=19.', '"Auburn Abroad advising, 2-day pre-term orientation, ISSS immigration & DS-2019 advising (intledu@auburn.edu), AU Medical Clinic & ClearWave support, Global Tigers Association (2 events/mo), 300+ clubs via AU Involve, Tiger Transit, Night Security Shuttle, and Atlanta Airport Groome Shuttle."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'living_cost_usd_est', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=9', '1 USD = 1.0 USD on 2026-11-15 (native USD); 5-month semester midpoint of $7,500-$11,000/semester living expenses (Housing $4,000-$6,500 + Meal Plan $500-$1,500 + Additional Meals $1,000 + Spending Money $2,000 = $9,250 midpoint) from Guide p.9. Excludes $1,000/sem mandatory health insurance and waived tuition/fees.', '9250.0');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=9', 'Non-waivable SHIP policy detailed at data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=13; 2027-2028 annual SHIP rate ($2,317) from https://www.auburn.edu/academic/international/isss/cost-of-attendance.html.', '"Tuition, Student Fees, and International Student Fee are waived during orientation check-in. Mandatory Auburn University Student Health Insurance Plan (SHIP, Blue Cross Blue Shield of Alabama; cannot be waived by exchange students) estimated at $1,000/semester in AY2024-25 guide ($2,317/year in 2027-2028 ISSS COA). Mandatory meal plan ($500-$1,500/semester) also applies."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'min_gpa_host', 1, 'unknown', 'unknown', NULL, NULL, NULL);
