INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'nomination_deadlines', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=6', 'Spring dates confirmed in data/raw/factsheets/Auburn/Spring 2025 Exchange Quick Facts.pdf#page=1.', '"Fall Nomination: Feb 1 - Mar 15, Application: Feb 1 - Apr 1; Spring Nomination: Sep 1 - Oct 15, Application: Sep 1 - Nov 15 (rolling weekly review; commitment paperwork due 2 weeks pre-arrival)."');
