INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'spring_term_dates', 1, 'verified', 'official_web', 'https://www.auburn.edu/academic/registrar/pdf/calendar/2026-2027-calendar.pdf', 'Spring arrival/orientation timing pattern from data/raw/factsheets/Auburn/Spring 2025 Exchange Quick Facts.pdf#page=1.', '"Spring 2027: Classes Jan 6 - Apr 23, 2027; Final Exams Apr 26 - Apr 30, 2027 (Spring 2025 orientation Jan 9-10, arrival Jan 1-7)."');
