INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('auburn-university', 'visa_lead_time_and_financial_proof', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=10', 'Financial Statement threshold ($5,000/term) and 6-month passport validity from data/raw/factsheets/Auburn/Auburn University Incoming Exchange Student Guide AY23-24 (1).pdf#page=7.', '"J-1 Exchange Visitor Visa required (Form DS-2019 processed by ISSS ~1 week after undergraduate admission / ~2 weeks after graduate admission and mailed physically for U.S. Embassy/Consulate interview; exact visa wait times vary by country). Financial Statement in application checklist must show at least $5,000 USD per semester; passport valid 6+ months post-program."');
