INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bocconi-university', 'est_monthly_living_local', 2, 'partial', 'official_web', 'https://www.unibocconi.it/en/admissions/cost-aid/cost-attendance-ay-2026-2027', 'AY 2026-2027 Cost of Attendance monthly living budget estimate (EUR 1,700–1,800/month, contextually used e.g. for US Direct Loans planning). Incoming-exchange specific page (https://www.unibocconi.it/en/foe/incoming-exchange-students/estimated-costs) and AY25-26 factsheet (data/raw/factsheets/Bocconi/2025-2026/AY2526_Factsheet International Student Desk Exchange_Pieghevole.pdf#page=2) itemize private double room EUR 500–750/mo, single room EUR 600–1,100/mo, flat EUR 800–1,800/mo, dorm EUR 4,000–4,800/sem, canteen ~EUR 5/meal, metro pass EUR 22/mo (<27 yrs).', '{"currency":"EUR","max":1800,"min":1700}');
