INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bocconi-university', 'fall_term_dates', 1, 'verified', 'official_web', 'https://www.unibocconi.it/en/for-international-students/incoming-exchange-students', 'AY 2026-2027 Fall schedule: mandatory check-in Aug 25–28; Italian crash course Aug 25–Sep 5; classes Sep 2–Dec 5; mid-terms Oct 19–28; early exchange exam session Dec 9–22 (earliest departure Dec 23); regular exam sessions Jan 7–19 and Jan 20–Feb 2, 2027.', '"2026-09-02 to 2026-12-22 (early exchange exams) / 2027-02-02 (regular exam sessions)"');
