INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bocconi-university', 'housing_notes', 2, 'verified', 'official_web', 'https://www.unibocconi.it/en/housing-information-incoming-exchange-students', 'Rent itemization from https://www.unibocconi.it/en/foe/incoming-exchange-students/estimated-costs and AY25-26 factsheet #page=2.', '"Limited on-campus residence rooms (EUR 4,000–4,800/semester single) allocated on a first-come, first-served basis; Bocconi provides guidance for private rentals (double EUR 500–750/mo, single EUR 600–1,100/mo, entire flat EUR 800–1,800/mo)."');
