INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bocconi-university', 'international_support_services', 4, 'verified', 'official_web', 'https://www.unibocconi.it/en/for-international-students/incoming-exchange-students', NULL, '"International Student Desk (ISD) online application portal, mandatory Welcome Check-in days, optional pre-term Italian crash course, visa/Permesso guidance, and housing info."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bocconi-university', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://www.unibocconi.it/en/admissions/cost-aid/cost-attendance-ay-2026-2027', '5-month midpoint estimate: 1,750 EUR/month * 5 months = 8,750 EUR * 1.1052 USD/EUR = 9,670.50 USD (ECB 2026-11-13 reference rate, collected 2026-11-15: https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html).', '9670.5');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bocconi-university', 'mandatory_host_fees_and_insurance', 2, 'verified', 'official_web', 'https://www.unibocconi.it/en/foe/incoming-exchange-students/estimated-costs', 'Confirmed also in data/raw/factsheets/Bocconi/2025-2026/AY2526_Factsheet International Student Desk Exchange_Pieghevole.pdf#page=2.', '"No mandatory Bocconi enrollment health insurance fee; non-EU students require valid international health insurance for visa/Permesso di Soggiorno (e.g., WAI Italy ~EUR 91/6 months) and pay ~EUR 100.46 + EUR 16 stamp for Permesso di Soggiorno."');
