INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bocconi-university', 'nomination_deadlines', 4, 'partial', 'official_web', 'https://www.unibocconi.it/en/for-international-students/incoming-exchange-students/online-application', NULL, '"Home partner coordinator submits online nomination first; Spring 2027 student online application window ran Sep 30 – Oct 22, 2026 (15:00 CET). Fall deadlines communicated per partner nomination cycle."');
