INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bogazici-university', 'credit_system_and_load', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Bogazici/2026-2027/Fact sheet 2026-2027.pdf#page=4', NULL, '"Boğaziçi credit-hour system (typical course is 3-4 credits / 5-7 ECTS); incoming exchange students take 4-6 courses totaling 17-21 Boğaziçi credits (~20-30 ECTS) per semester. Grading scale: AA (4.0) to DD (1.0) pass, F (0.0) fail."');
