INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bogazici-university', 'english_proficiency_and_rhet1020', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Bogazici/2026-2027/Fact sheet 2026-2027.pdf#page=9', NULL, '"Non-native English speakers must provide proof of CEFR B2 or higher: TOEFL iBT 79+ (Writing 22+), IELTS 6.5+, Cambridge Assessment English C1, OR a formal signed B2/C1 certification letter from the home university (no explicit RHET 1020 exemption stated)."');
