INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bogazici-university', 'fall_term_dates', 1, 'verified', 'official_web', 'https://akademiktakvim.bogazici.edu.tr/en', 'Fact sheet 2026-2027.pdf#page=3 states mid-September to January overview and points to https://akademiktakvim.bogazici.edu.tr/en.', '"Fall Semester (AY 2026-2027): Online pre-registration deadline Aug 20, 2026; Orientation Sep 14, 2026; Online course registration Sep 15-17, 2026; Classes Sep 21 – Dec 11, 2026; Final exams through Dec 22, 2026 (Make-up exams Dec 23-25, 2026)."');
