INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bogazici-university', 'housing_availability', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Bogazici/2026-2027/Fact sheet 2026-2027.pdf#page=10', 'AY 2026-2027 Fact Sheet p.10 explicitly states: ''Boğaziçi University does not offer on-campus housing for incoming students.''', '"off_campus_only"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bogazici-university', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Bogazici/2026-2027/Fact sheet 2026-2027.pdf#page=10', NULL, '"AY 2026-2027 Fact Sheet p.10 states Boğaziçi University does not offer on-campus housing for incoming students; students must arrange their own off-campus accommodation (contact residencepermit@bogazici.edu.tr for recommendations)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bogazici-university', 'instruction_languages', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Bogazici/2026-2027/Fact sheet 2026-2027.pdf#page=4', '100% English-medium institution; some courses in the Department of Law and Department of Turkish Language and Literature are offered in Turkish.', '["English","Turkish"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bogazici-university', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Bogazici/2026-2027/Fact sheet 2026-2027.pdf#page=8', 'Turkish courses on p.3; campus life & clubs on p.10; Residence Permit Operations on p.14.', '"Mandatory orientation covering course registration, campus life, and procedures; Office of International Relations incoming advising and Residence Permit Operations team; 40+ student clubs, sports centers, cultural series, and credited Turkish language courses."');
