INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bogazici-university', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Bogazici/2026-2027/Fact sheet 2026-2027.pdf#page=11', NULL, '"Boğaziçi University has no separate institutional health insurance requirement, but Turkish law requires valid health insurance covering the full stay for the mandatory Student Residence Permit (EU reciprocity public insurance or private health insurance purchased in Turkey)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bogazici-university', 'min_gpa_host', 1, 'unknown', 'unknown', NULL, 'No fixed numeric minimum GPA published for incoming exchange students in AY 2026-2027 Fact Sheet or intl.bogazici.edu.tr (2.50 UG / 3.00 GR applies to outgoing Boğaziçi students).', NULL);
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bogazici-university', 'min_standing_note', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Bogazici/2026-2027/Fact sheet 2026-2027.pdf#page=9', NULL, '"Must be nominated by home university; Boğaziçi reviews applications and individual academic units decide on admission (exchange students must take at least one course from their registered host department)."');
