INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('bogazici-university', 'visa_lead_time_and_financial_proof', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Bogazici/2026-2027/Fact sheet 2026-2027.pdf#page=11', 'Pre-arrival country visa rules checked via http://www.mfa.gov.tr/visa-information-for-foreigners.en.mfa (per 2023-2024 guide p.4); exact lead time and financial threshold not stated in AY 2026-2027 Fact Sheet.', '"Nationalities eligible for touristic entry may enter Türkiye with an e-Visa or passport entry stamp and complete university registration; other nationalities must obtain a Student Visa (not an internship visa) from a Turkish embassy/consulate beforehand. All students must enter with a valid passport (not national ID) and apply for a Turkish Student Residence Permit after arrival with valid health insurance and proof of accommodation."');
