INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('brandeis-university', 'est_monthly_living_local', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Brandeis/2026-2027/FactSheet_26-27.pdf#page=6', 'Derived monthly cost from AY 2026-2027 Fact Sheet p.6 estimated per-semester living expenses divided by 5 months: Room & Board $10,422 (Ziv suite + required All Access + 5 Meal Plan) + Books & supplies $500 + Personal expenses $600 = $11,522/semester -> $2,304.40/mo (~$2,304/mo). Excludes Health insurance ($3,917/sem), Visa fees ($400), and Airfare ($1,850).', '{"currency":"USD","max":2304,"min":2304}');
