INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('chung-ang-university', 'living_cost_usd_est', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Chung-Ang University/2026-2027/CAU - Fact Sheet_Spring 2026.pdf#page=6', '5 months * 1075 USD/month midpoint = 5375.00 USD (rate 1 USD = 1 USD; verified 2026-11-15). Prorated from CAU Spring 2026 Fact Sheet official 16-week (~4-month) semester budget of $4,300 USD ($1,300 dorm + $700 meals + $600 transport + $200 books + $1,500 personal) = $1,075 USD/month.', '5375.0');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('chung-ang-university', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Chung-Ang University/2026-2027/CAU - Fact Sheet_Spring 2026.pdf#page=5', 'Optional intensive Korean language courses carry a 25% discount for exchange students.', '"Mandatory South Korean National Health Insurance (NHIS) enrollment upon Residence Card issuance at ~USD 70/month; private home insurance does not exempt from NHIS."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('chung-ang-university', 'min_gpa_host', 1, 'unknown', 'unknown', NULL, 'Fall 2025 Fact Sheet (#page=6, confirmed via cau.ac.kr) explicitly states ''CAU does not have strict GPA requirements. Students nominated by their home universities will be deemed qualified'', and Spring 2026 Fact Sheet (#page=6) drops the 4.0 conversion table and specifies only Minimum 2.0/4.5 (75/100) for the whole semester.', NULL);
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('chung-ang-university', 'min_standing_note', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Chung-Ang University/2026-2027/CAU - Fact Sheet_Spring 2026.pdf#page=6', NULL, '"CAU does not enforce a strict incoming minimum GPA (Fall 2025 Fact Sheet #page=6: ''CAU does not have strict GPA requirements. Students nominated by their home universities will be deemed qualified''); Spring 2026 Fact Sheet specifies maintaining Minimum 2.0/4.5 (75/100) for the whole semester."');
