INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('concordia-university', 'english_proficiency_and_rhet1020', 1, 'verified', 'official_web', 'https://www.concordia.ca/admissions/undergraduate/requirements/english-language-proficiency.html', 'Inbound exchange rule confirmed at https://www.concordia.ca/international/students-from-abroad/inbound-exchange/how-to-apply.html; graduate standards via https://www.concordia.ca/graduatestudies/admissions/international/english-language-proficiency.html.', '"Non-English-medium applicants must meet direct-admission English proficiency (no ESL/conditional admission): UG baseline TOEFL iBT 70 (4.0 on revised scale) or IELTS Academic 6.0 (min 5.5 component); GR/MBA often higher (e.g., TOEFL 95 with min 20 section / IELTS 7.0 with min 6.5). No RHET 1020 exemption stated."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('concordia-university', 'est_monthly_living_local', 2, 'partial', 'official_web', 'https://www.concordia.ca/students/financial-aid/tuition-fees/cost-of-living.html', 'Sum of published monthly off-campus budget components ($1,100 housing/rent + $450 food + $63 student transit + $408 personal/phone from cost-of-living.html & https://www.concordia.ca/admissions/undergraduate/costs-aid.html), excluding books (~$2,800+/yr). Comparable to Quebec immigration 12-month living estimate of CAD $24,617/yr (~CAD $2,051/mo) on https://www.concordia.ca/students/international/immigration/study-permits/estimate-costs.html.', '{"currency":"CAD","max":2021,"min":2021}');
