INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('concordia-university', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://www.concordia.ca/students/financial-aid/tuition-fees/cost-of-living.html', '5-month estimate: 2,021 CAD/month * 5 months = 10,105 CAD * 0.701358 USD/CAD = 7,087.22 USD (ECB 2026-11-13 cross rate 1 EUR = 1.5758 CAD and 1 EUR = 1.1052 USD -> 1 CAD = 0.701358 USD, collected 2026-11-15: https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html).', '7087.2');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('concordia-university', 'mandatory_host_fees_and_insurance', 2, 'verified', 'official_web', 'https://www.concordia.ca/students/international/health-insurance.html', 'Inbound exchange health insurance FAQ at https://www.concordia.ca/international/students-from-abroad/inbound-exchange/faq/health-insurance.html.', '"Compulsory Blue Cross international health insurance (2026-2027 rates): CAD $388 (4-month term), CAD $873 (9-month Fall & Winter), or CAD $1,164 (12-month)."');
