INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('concordia-university', 'min_standing_note', 1, 'verified', 'official_web', 'https://www.concordia.ca/international/students-from-abroad/inbound-exchange/how-to-apply.html', NULL, '"Minimum cumulative GPA equivalent to 3.00 on a 4.3 grading scale; undergraduate applicants must have completed at least one semester and graduate applicants at least one semester of graduate studies prior to arrival."');
