INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('east-carolina-university', 'housing_notes', 2, 'verified', 'official_web', 'https://global-affairs.ecu.edu/incoming-exchange-students/', NULL, '"Incoming exchange students are required to live on campus in designated reserved spots and may move in one day prior to orientation. ECU residence hall rates range ~$3,046.50 (standard) to $3,576.00/semester (College Hill Suites), plus required residential meal plans (~$2,517+tax/semester)."');
