INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('east-carolina-university', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://financialaid.ecu.edu/cost/', '1 USD = 1.0 USD on 2026-11-15 (native USD); 5-month semester midpoint of ECU 2026-27 on-campus undergraduate Housing + Food COA ($11,401/yr continuing = $5,700.50/sem to $12,220/yr entering = $6,110.00/sem; midpoint $5,905.25/semester), excluding books/personal expenses and health insurance.', '5905.25');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('east-carolina-university', 'mandatory_host_fees_and_insurance', 2, 'partial', 'official_web', 'https://global-affairs.ecu.edu/required-medical-insurance/', 'Student Blue semester estimate and Purple meal plan rate sourced from ECU Student Financial Services / Campus Living.', '"J-1 exchange visitors are federally required to carry J-1 compliant medical insurance for the full DS-2019 period (home country policies are generally not accepted; enrollment in an ECU/UNC-approved plan is mandatory; degree-seeking Student Blue SHIP is estimated at $1,312/sem UG or $2,366.50/sem GR). On-campus residents are typically required to carry a residential meal plan (Purple plans $2,517+tax/semester)."');
