INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('ecole-de-management-de-normandie-em-normandie', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/EM Normandie/FACTSHEET 24-25 EM Normandie.pdf#page=2', 'Concierge Club and Studapart details on p.3.', '"International Affairs team (incoming@em-normandie.fr), Studapart housing support (accommodation@em-normandie.fr), complimentary French classes for English-taught programmes, and optional Student Concierge Club."');
