INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('edhec-business-school', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/EDHEC Business School/Factsheet_EDHEC_BBA_25-26.pdf#page=5', 'Also in Factsheet_Master_2025-26.pdf#page=7. EDHEC ISO portal (https://www.edhec.edu/en/iso/international-student-office) provides housing platform access, guarantor (VISALE/Garantme/Smartgarant), and Assurance Habitation guidance.', '"Lille Campus: on-campus accommodation in the EDHEC residence (kots and private studios) plus off-campus offers via ISO when available; Nice Campus: off-campus accommodation only; first-come, first-served allocation (#page=5)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('edhec-business-school', 'instruction_languages', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/EDHEC Business School/Factsheet_EDHEC_BBA_25-26.pdf#page=3', 'All BBA Year 2/IBT/Year 3 exchange tracks and Master/MSc tracks are taught in English; BBA Year 2 French track in Nice and Master Classic Track are French/mixed (#page=5-6 in Master fact sheet).', '["English","French"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('edhec-business-school', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/EDHEC Business School/Factsheet_EDHEC_BBA_25-26.pdf#page=5', NULL, '"EDHEC International Students Office (ISO, https://www.edhec.edu/en/iso/international-student-office) provides pre-arrival, visa documentation, housing guidance, and campus sports access."');
