INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('emlyon-business-school', 'living_cost_usd_est', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Emlyon Business School/Factsheet_MiM_2025_-_2026_V.1_3_.pdf#page=1', '5-month estimate: 1,000 EUR/month * 5 months = 5,000 EUR * 1.1052 USD/EUR = 5,526.00 USD (ECB 2026-11-13 rate, collected 2026-11-15: https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html).', '5526.0');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('emlyon-business-school', 'mandatory_host_fees_and_insurance', 2, 'verified', 'official_web', 'https://em-lyon.com/en/international/incoming-students/first-steps-france', 'CVEC exemption rules verified via official French student portal (etudiant.gouv.fr / campusfrance.org); ameli portal via https://etudiant-etranger.ameli.fr/#/.', '"Bilateral exchange students are EXEMPT from the French CVEC student life fee (obtain free exemption certificate at cvec.etudiant.gouv.fr per Campus France/etudiant.gouv.fr). Registration for French Sécurité Sociale (etudiant-etranger.ameli.fr) is mandatory for stays >3 months, plus third-party civil liability insurance (~EUR 10)."');
