INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('emlyon-business-school', 'visa_lead_time_and_financial_proof', 2, 'verified', 'official_web', 'https://www.legifrance.gouv.fr/eli/decret/2026/6/22/INTV2605727D/jo/texte', 'Visa portals also listed at https://france-visas.gouv.fr/en/web/france-visas/visa-wizard and https://pastel.diplomatie.gouv.fr/etudesenfrance.', '"Non-EU students staying >90 days must obtain a French VLS-TS long-stay student visa via Etudes en France (pastel.diplomatie.gouv.fr/etudesenfrance) / France-Visas before departure. Effective August 1, 2026, Décret n° 2026-526 increased minimum student financial proof from EUR 615/mo to EUR 877.50/month (EUR 10,530/year; 47% of gross SMIC)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'academic_style', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Frankfurt School of Finance & Management/2026-2027/Fact_Sheet_Exchange_Students_2026_27.pdf#page=1', NULL, '"Research-led, triple-accredited (AACSB, AMBA, EQUIS) business school focusing on finance, management, economics, accounting, and philosophy & law; lectures and exams run Monday–Saturday, with mandatory orientation and online course selection."');
