INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'course_restrictions_note', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Frankfurt School of Finance & Management/2026-2027/Fact_Sheet_Exchange_Students_2026_27.pdf#page=2', 'Mon–Sat schedule and exam-release note on #page=1.', '"Bachelor exchange limited to 6th and 7th semester BA modules; most Master modules open subject to availability. Add/drop available before semester start; enrollment in specific courses not guaranteed. Lectures and exams run Monday–Saturday (#page=1); exam dates released ~1–2 weeks before exam week."');
