INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'english_proficiency_and_rhet1020', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Frankfurt School of Finance & Management/2026-2027/Fact_Sheet_Exchange_Students_2026_27.pdf#page=2', NULL, '"TOEFL iBT 90, IELTS 7.0, or Cambridge C1 (within 2 years of test date), OR confirmation from home university study advisory office if degree programme at home university is fully taught in English (native speakers provide native-English passport proof). RHET 1020 is not specifically mentioned; AUC English-medium degree confirmation letter satisfies the home-programme English exemption."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'est_monthly_living_local', 2, 'verified', 'official_web', 'https://www.frankfurt-school.de/en/live/international-student-guide/before-you-apply', 'Official FS International Student Guide (''Before you Apply'') cites DAAD guidance of EUR 900–1,200/month covering accommodation, groceries, health insurance, transport, communication, study materials, and personal expenses (note AY 2026-27 Fact Sheet #page=2 also lists optional i-Live dorm rent at EUR 770/month).', '{"currency":"EUR","max":1200,"min":900}');
