INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'fall_term_dates', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Frankfurt School of Finance & Management/2026-2027/Fact_Sheet_Exchange_Students_2026_27.pdf#page=1', 'Excel agreement_terms_raw is ''AY/Spring''; Winter semester dates apply to Academic Year students.', '"AY 2026-2027 Winter semester (available under Academic Year option): Mandatory orientation 19–20 Aug 2026; Bachelor lectures 17 Aug–11 Dec 2026 (Exam I 17–24 Oct, Exam II 12–19 Dec 2026); Master term 1 Sep 2026–31 Jan 2027 (lectures begin 31 Aug, end 12 Dec; Exam I 19–24 Oct, Exam II 14–19 Dec 2026)."');
