INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'host_language_requirement', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Frankfurt School of Finance & Management/2026-2027/Fact_Sheet_Exchange_Students_2026_27.pdf#page=2', NULL, '"C1 German proficiency required only if enrolling in German-taught modules; no German required for English-taught modules. Optional German courses offered (6 ECTS during semester; optional 1-month intensive August course before Winter semester for a fee)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'housing_availability', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Frankfurt School of Finance & Management/2026-2027/Fact_Sheet_Exchange_Students_2026_27.pdf#page=2', NULL, '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Frankfurt School of Finance & Management/2026-2027/Fact_Sheet_Exchange_Students_2026_27.pdf#page=2', NULL, '"Limited furnished on-campus apartments (private bath and kitchenette) reserved with dorm partner i-Live on a first-come, first-served basis (not guaranteed; apply within online exchange application). Fixed 6-month solidarity contracts (15 Jan–14 Jul or 15 Jul–14 Jan) at EUR 770/month (14-day withdrawal period, after which full 6-month rent applies; contracted directly with i-Live). Other Frankfurt options: http://www.frankfurt-school.de/en/home/about/campus/dorms"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'instruction_languages', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Frankfurt School of Finance & Management/2026-2027/Fact_Sheet_Exchange_Students_2026_27.pdf#page=2', NULL, '["English","German"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Frankfurt School of Finance & Management/2026-2027/Fact_Sheet_Exchange_Students_2026_27.pdf#page=1', 'Also cites #page=2 for German courses/contact and #page=3 for office/reception hours.', '"Mandatory International Student Orientation (campus tour, FS Online Campus onboarding, compulsory health insurance check), optional semester German course (6 ECTS) and August intensive German course, dedicated Incoming Student Mobility Manager (Patricia Escalera, p.escalera@fs.de; #page=2), International Office walk-in hours Mon–Fri 9:00–16:00 and 24/7 campus reception (#page=3)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://www.frankfurt-school.de/en/live/international-student-guide/before-you-apply', '5-month USD midpoint estimate derived from EUR 900–1,200/month range (midpoint EUR 1,050/mo x 5 = EUR 5,250) converted at ECB 2026-11-13 reference rate 1 EUR = 1.1052 USD (collected 2026-11-15 via https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html): 5,250 x 1.1052 = 5,802.30 USD.', '5802.3');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Frankfurt School of Finance & Management/2026-2027/Fact_Sheet_Exchange_Students_2026_27.pdf#page=2', NULL, '"Mandatory reduced Deutschlandticket (~EUR 189/semester) and Student Council fee (EUR 15/semester) apply to all enrolled students regardless of length of stay. Compulsory German-equivalent unlimited health insurance covering the full semester (travel insurance rejected; checked at mandatory orientation, or students must enroll in German insurance at ~EUR 105/month)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'min_gpa_host', 1, 'unknown', 'unknown', NULL, 'No institutional minimum GPA stated in AY 2026-27 Fact Sheet; partner institutions handle nomination screening.', NULL);
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'min_standing_note', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Frankfurt School of Finance & Management/2026-2027/Fact_Sheet_Exchange_Students_2026_27.pdf#page=2', NULL, '"Bachelor exchange: at least 2 years completed in a business or economics-related programme (eligible for 6th/7th semester modules). Master exchange: completed undergraduate degree and at least 1 semester at graduate level."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'nomination_deadlines', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Frankfurt School of Finance & Management/2026-2027/Fact_Sheet_Exchange_Students_2026_27.pdf#page=2', NULL, '"Summer Semester (Spring): Nomination 1 October / Application 1 November; Winter Semester (Fall / Academic Year): Nomination 15 April / Application 15 May."');
