INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'spring_term_dates', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Frankfurt School of Finance & Management/2026-2027/Fact_Sheet_Exchange_Students_2026_27.pdf#page=1', NULL, '"AY 2026-2027 Summer semester 2027: Mandatory orientation 21–22 Jan 2027; Bachelor lectures 25 Jan–21 May 2027 (Exam I 13–20 Mar, Exam II 22–29 May 2027); Master term 1 Feb–31 Aug 2027 (lectures begin 11 Jan, end 22 May; Exam I 15–20 Mar, Exam II 24–29 May 2027)."');
