INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'tuition_model', 2, 'verified', 'official_web', 'https://www.frankfurt-school.de/en/students/international-office/incoming', 'Standard FS tuition fees are waived for incoming exchange students nominated under partner exchange agreements; mandatory Deutschlandticket and Student Council fees still apply.', '"auc_exchange_waiver"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('frankfurt-school-of-finance-and-management', 'visa_lead_time_and_financial_proof', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Frankfurt School of Finance & Management/2026-2027/Fact_Sheet_Exchange_Students_2026_27.pdf#page=2', NULL, '"Compulsory pre-arrival German student visa for non-EU students (arranged individually via local German embassy; must be valid for mandatory pre-semester orientation days per AY 2026-27 Fact Sheet #page=2). German Federal Foreign Office blocked-account financial standard is EUR 992/month (EUR 11,904/year) per https://www.auswaertiges-amt.de/en/sperrkonto/388600."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'academic_style', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=3', NULL, '"Modular structure (lecture + seminar pairings per module) at a German research university (University of Excellence / Berlin University Alliance) with cross-registration across HU Berlin, TU Berlin, and University of Potsdam."');
