INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'course_catalog_url', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=3', 'Official FU Berlin course catalog URL embedded in AY 2026-2027 Fact Sheet p.3.', '"https://www.fu-berlin.de/vv/en/fb"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'course_restrictions_note', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=3', NULL, '"Human Medicine, Veterinary Medicine, and fee-based continuing education Master''s programs are closed. Biochemistry, bioinformatics, and biology depend on lab availability and prior departmental approval; restrictions apply in Pharmacy, Law (prefers reciprocal Law exchange partners), and Business & Economics (requires B2+ German; very limited irregular English offerings). Master''s courses other than Modern German Literature, Philosophy, and Political Science require prior departmental approval; BA students generally cannot take Master''s courses. Cross-registration at HU Berlin, TU Berlin, and University of Potsdam possible with prior lecturer approval."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'credit_system_and_load', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=3', 'Grading scale table detailed on Fact Sheet p.4.', '"ECTS (Leistungspunkte/LP); regular full-time workload is 30 ECTS per semester (FU recommends 10-30 ECTS for exchange students; no strict host minimum). Grading scale (except Law): 1.0-1.5 very good, 1.6-2.5 good, 2.6-3.5 satisfactory, 3.5-4.0 sufficient, 5.0 fail."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'daily_life_english_friendliness', 4, 'unknown', 'unknown', NULL, 'Not explicitly stated in FU Berlin fact sheets or official fu-berlin.de pages reviewed; left unknown per zero-fabrication rules.', NULL);
