INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'english_course_list_url', 3, 'unknown', 'unknown', NULL, 'No standalone static live English-only course list URL; use language filter in https://www.fu-berlin.de/vv/en/fb. Past-term Drive snapshots exist in data/raw/factsheets/FUBerlin/26-27/FUB English Courses Winter 2024-25.xlsx & Summer 2025.xlsx.', NULL);
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'english_proficiency_and_rhet1020', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=1', NULL, '"No general English test certificate stated for most departments; CEFR C1 English level required for courses at the John F. Kennedy Institute for North American Studies."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'est_monthly_living_local', 2, 'verified', 'official_web', 'https://www.fu-berlin.de/en/sites/cairo/faq/faq-study/living-costs/index.html', 'Official FU Berlin Cairo FAQ lists minimum 934 EUR/month (rental fees, groceries, leisure). AY 2026-2027 Fact Sheet (#page=2,#page=3) separately cites ERG housing 500-1,200 EUR/month, student health insurance ~150 EUR/month (under age 30), and mandatory semester/social fees ~310 EUR/semester; German federal student visa blocked-account threshold is 992 EUR/month.', '{"currency":"EUR","max":934,"min":934}');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'exchange_page_url', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=1', 'Embedded official incoming Direct Exchange URL in AY 2026-2027 Fact Sheet p.1 and verified via fu-berlin.de search.', '"https://www.fu-berlin.de/en/studium/international/studium_fu/auslandssemester/direktaustausch_in/index.html"');
