INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'fall_term_dates', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=1', NULL, '"Winter Term 2026/2027: Semester Oct 1, 2026 – Mar 31, 2027; Orientation first week of October; Lecture period Oct 12, 2026 – Feb 19, 2027; Exams typically during last two weeks of lecture period (varies by department)."');
