INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'host_grants_or_stipends', 2, 'unknown', 'unknown', NULL, 'PROMOS/DAAD links found via web search apply to outgoing FU Berlin students; no incoming host stipend confirmed for AUC Direct Exchange.', NULL);
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'host_language_requirement', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=1', 'Optional pre-semester and free in-semester German course details on Fact Sheet p.2.', '"Exempt from DSH/TestDaF exam and no certificate required (home university verifies); expected German CEFR B2 for Humanities & Social Sciences and B1 for Natural Sciences. Optional pre-semester 6-week intensive German course (~900 EUR, all levels incl. beginners) and free in-semester German courses (placement test required)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'housing_availability', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=3', NULL, '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=3', 'ERG Accommodation Service options, ~500-1,200 EUR/month range, and June 10 / Dec 10 registration deadlines from AY 2026-2027 Fact Sheet #page=3; ''no on-campus accommodation available'' corroborated in data/raw/factsheets/FUBerlin/2024-2025/Fact Sheet Direct Exchange Program FU Berlin academic year 2025-2026.pdf#page=3.', '"No on-campus accommodation available (per AY 2025-2026 Fact Sheet #page=3). Students may arrange private housing (e.g., WG shared flats) or apply via FU Berlin''s ERG Accommodation Service (dorms, shared apartments, furnished single apartments; ~500-1,200 EUR/month). First-come, first-served; mandatory online registration deadlines June 10 (Winter term) and December 10 (Summer term)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'instruction_languages', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=1', NULL, '["German","English"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=2', 'Distributed Campus, Pass Service, German language courses, and Exchange courses detailed across Fact Sheet p.1-p.3.', '"Mandatory orientation program (5-10 days before lectures: course selection, FU-Net/campus tours), Distributed Campus onboarding portal, Pass Service (arrival residence permit assistance), pre-semester and free in-semester German language courses via ZE Sprachenzentrum, plus dedicated Exchange courses in German culture/history/society."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://www.fu-berlin.de/en/sites/cairo/faq/faq-study/living-costs/index.html', 'Converted from FU Berlin official minimum monthly estimate of 934 EUR over 5 months: 934 EUR * 5 * FX rate 1.1052 USD/EUR = 5,161.28 USD. FX rate 1 EUR = 1.1052 USD from ECB Euro reference exchange rates for 2026-11-13 (latest prior to 2026-11-15), retrieved 2026-11-15 at https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html.', '5161.28');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=2', NULL, '"Exempt from university tuition; mandatory semester ticket and social fees ~310 EUR/semester (paid prior to arrival). Mandatory comprehensive German health insurance required for enrollment and residence permit (~150 EUR/month for students under age 30 via German public student insurance; external waivers rarely accepted unless EHIC/GHIC or unlimited coverage)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'min_gpa_host', 1, 'unknown', 'unknown', NULL, 'AY 2026-2027 incoming Direct Exchange fact sheet specifies no numeric minimum GPA (2.5 GPA in FU web search results refers to FU outgoing students, not incoming exchange).', NULL);
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'min_standing_note', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=3', 'Application eligibility also summarized on Fact Sheet p.1.', '"Must be nominated by home university; in general BA students cannot enroll in Master''s programs or individual Master''s-level courses (case-by-case departmental exceptions possible); visiting PhD enrollment possible with prerequisites."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'nomination_deadlines', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=1', NULL, '"Winter term: Nomination & student application deadline April 30; Summer term: Nomination & student application deadline October 30."');
