INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'required_application_docs', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=2', 'Nomination and online MoveON application checklist also referenced on Fact Sheet p.1.', '["Official home university nomination (email or letter)","Online MoveON application form","Passport photocopy (photo page)","University transcript of records (German or English)","Copies of completed B.A./M.A./other degrees (if available)","Proof of comprehensive German/valid health insurance & semester fee payment (for enrollment)"]');
