INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'spring_term_dates', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=1', NULL, '"Summer Term 2027: Semester Apr 1, 2027 – Sep 30, 2027; Orientation first week of April; Lecture period Apr 12, 2027 – Jul 23, 2027; Exams typically during last two weeks of lecture period (varies by department)."');
