INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'tuition_model', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=2', 'Fact Sheet p.2 states exchange students are exempt from university tuition fees, though mandatory semester ticket and social fees still apply.', '"auc_exchange_waiver"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('freie-universitat-berlin', 'visa_lead_time_and_financial_proof', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/FUBerlin/26-27/Fact Sheet Direct Exchange Program FU Berlin academic year 2026-2027.pdf#page=2', 'Pre-arrival entry visa requirement & >=8 weeks visa processing from AY 2026-2027 Fact Sheet #page=2; Berlin residence permit 8-14 week timeline from https://www.fu-berlin.de/en/studium/international/studium_fu/einreise_aufenthalt/aufenthaltserlaubnis/index.html; blocked account 992 EUR/mo (11,904 EUR/yr) from https://www.auswaertiges-amt.de/en/sperrkonto/388600; FU >=934 EUR/mo baseline from https://www.fu-berlin.de/en/sites/cairo/faq/faq-study/living-costs/index.html.', '"Non-EU/EEA/non-exempt nationals (incl. Egypt) must obtain a German student visa prior to arrival (processing takes at least 8 weeks, up to several months, per Fact Sheet #page=2). After arrival, non-EU students apply for a Berlin residence permit (Aufenthaltserlaubnis) via LEA/FU Pass-Service (typically 8 to 14 weeks processing). Financial proof (e.g., blocked account / Sperrkonto) required per German Federal Foreign Office standard (992 EUR/month / 11,904 EUR/year; FU Berlin general FAQ lists >=934 EUR/month)."');
