INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('institut-polytechnique-de-sciences-avancees-ipsa', 'host_grants_or_stipends', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/IPSA France/20260902_Factsheet_IPSA.pdf#page=2', NULL, '"CAF personal housing allowance (APL, up to 210 EUR/month) for EU students renting accommodation in France; Campus France scholarships vary by home country (no AUC-specific incoming IPSA stipend confirmed)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('institut-polytechnique-de-sciences-avancees-ipsa', 'host_language_requirement', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/IPSA France/20260902_Factsheet_IPSA.pdf#page=2', NULL, '"None required for English-track Aero 3/4/5 courses; CEFR B2 French recommended for French-track Aero 3 and for the Aero 5 Management option. Free French lessons (FLE) and intercultural courses offered."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('institut-polytechnique-de-sciences-avancees-ipsa', 'housing_availability', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/IPSA France/20260902_Factsheet_IPSA.pdf#page=2', 'IPSA provides access to its partner''s dedicated student housing platform (student residencies and offers with personalized rental support).', '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('institut-polytechnique-de-sciences-avancees-ipsa', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/IPSA France/20260902_Factsheet_IPSA.pdf#page=2', NULL, '"Access to IPSA''s partner student housing platform offering student residencies and rental support; estimated accommodation 600-900 EUR/month. EU students renting in France may receive CAF APL housing allowance (up to 210 EUR/month per 2026-2027 Fact Sheet p.2)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('institut-polytechnique-de-sciences-avancees-ipsa', 'instruction_languages', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/IPSA France/20260902_Factsheet_IPSA.pdf#page=2', NULL, '["English","French"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('institut-polytechnique-de-sciences-avancees-ipsa', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/IPSA France/20260902_Factsheet_IPSA.pdf#page=2', 'Orientation days timing on p.1.', '"Orientation days 1 week before program start; buddy system, free French language (FLE) and intercultural courses, cultural activities with the international student association, 90+ clubs, and partner housing platform support."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('institut-polytechnique-de-sciences-avancees-ipsa', 'living_cost_usd_est', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/IPSA France/20260902_Factsheet_IPSA.pdf#page=2', 'Converted from midpoint 1,082 EUR/month (range 932-1,232 EUR/month) over 5 months: 1082 EUR * 5 * FX rate 1.1052 USD/EUR = 5,979.13 USD. FX rate 1 EUR = 1.1052 USD from ECB Euro reference exchange rates for 2026-11-13 (latest prior to 2026-11-15), retrieved 2026-11-15 at https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html.', '5979.13');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('institut-polytechnique-de-sciences-avancees-ipsa', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/IPSA France/20260902_Factsheet_IPSA.pdf#page=2', NULL, '"Tuition fee waived; VLS-TS visa fee 50 EUR. EU students must present a valid EHIC upon arrival; non-EU students must enroll in the free French student social security scheme once in France (complementary health insurance recommended). Civil (third-party) liability insurance is mandatory for all students."');
