INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('james-madison-university', 'english_proficiency_and_rhet1020', 1, 'verified', 'official_web', 'https://www.jmu.edu/global/abroad/exchange-students-inbound.shtml', 'Historical 2021-22 Fact Sheet figures at data/raw/factsheets/James Madison University/James Madison University Incoming Exchange Info Sheet 2021-2022 - Global Dukes.pdf#page=2.', '"TOEFL iBT >= 81 (or >= 4.5 on updated TOEFL iBT scale for exams taken on/after Jan 21, 2026) or IELTS overall >= 6.5 (2021-22 sheet listed TOEFL PBT 550 / iBT 80-81 / IELTS 6-7). RHET 1020 exemption not stated."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('james-madison-university', 'est_monthly_living_local', 2, 'partial', 'official_web', 'https://www.jmu.edu/admissions/apply/international.shtml', 'Derived from JMU official international cost breakdown ($15,088 living expenses + $4,300 books/personal = $19,388 academic year / 2 semesters = $9,694 per 5-month semester, i.e., $1,939/month). 2026-27 on-campus housing ($3,428-$4,228/sem) + resident meal plans ($3,438-$3,819/sem) + internet ($138/sem) listed at https://www.jmu.edu/ubo/undergraduate-tuition-rates.shtml.', '{"currency":"USD","max":1939.0,"min":1939.0}');
