INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('james-madison-university', 'fall_term_dates', 1, 'verified', 'official_web', 'https://www.jmu.edu/registrar/dates/fall_2026.shtml', 'Pre-term Fall orientation timing from data/raw/factsheets/James Madison University/James Madison University Incoming Exchange Info Sheet 2021-2022 - Global Dukes.pdf#page=2.', '"Fall 2026: Classes Aug 26 - Dec 11, 2026; Final Exams Dec 12 - Dec 18, 2026 (Fall Break Oct 7-11; Thanksgiving Nov 23-27; orientation held the week prior per Fact Sheet p.2)."');
