INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('james-madison-university', 'housing_availability', 2, 'verified', 'official_web', 'https://www.jmu.edu/global/abroad/exchange-students-inbound.shtml', 'Housing preferences/contract coordinated during exchange onboarding and Office of Residential Life portal (rms.jmu.edu); no unconditional guarantee stated.', '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('james-madison-university', 'housing_notes', 2, 'verified', 'official_web', 'https://www.jmu.edu/ubo/undergraduate-tuition-rates.shtml', 'Housing onboarding via https://www.jmu.edu/global/abroad/exchange-students-inbound.shtml.', '"On-campus housing contract and preferences processed after acceptance via Residential Life (rms.jmu.edu). AY 2026-27 per-semester housing rates: $3,428-$4,228 (+$500 single occupancy) + $138 internet + mandatory resident meal plan ($3,438-$3,819/sem)."');
