INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('james-madison-university', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/James Madison University/James Madison University Incoming Exchange Info Sheet 2021-2022 - Global Dukes.pdf#page=1', 'Orientation timing and IAD airport pickup details in data/raw/factsheets/James Madison University/James Madison University Incoming Exchange Info Sheet 2021-2022 - Global Dukes.pdf#page=2.', '"JMU Center for Global Engagement advising, pre-semester orientation (1 week in Fall / 1 day in Spring), airport pickup from Washington Dulles International Airport (IAD), free English Language Learning Center tutoring, LIFE local-family connection program, Culture Nights, International Week, and career workshops."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('james-madison-university', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://www.jmu.edu/admissions/apply/international.shtml', '1 USD = 1.0 USD on 2026-11-15 (native USD); 5-month semester estimate ($15,088 living + $4,300 books/personal = $19,388 annual / 2 semesters = $9,694 USD; 5 * $1,938.80/mo). Excludes tuition and health insurance.', '9694.0');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('james-madison-university', 'mandatory_host_fees_and_insurance', 2, 'verified', 'official_web', 'https://www.jmu.edu/global/isss/resources/health-insurance.shtml', 'Internet fee ($138/sem) from https://www.jmu.edu/ubo/undergraduate-tuition-rates.shtml; legacy fee schedule in data/raw/factsheets/James Madison University/James Madison University Incoming Exchange Info Sheet 2021-2022 - Global Dukes.pdf#page=2.', '"Mandatory CISI health insurance: $1,656/year (split between fall and spring semesters; waivable only upon arrival with proven equivalent abroad coverage meeting U.S. Dept. of State rules). On-campus internet fee $138/semester (2026-27); 2021-22 sheet also noted $100/semester International Student Fee and $40 Housing Contract Fee."');
