INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('kent-state-university', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Kent State University/2026-2027/KSU Fact Sheet 2026-2027.pdf#page=2', 'Career services ($93.84), student health ($90), and transcript ($10) fees detailed on #page=3; SHIP portal at https://www.kent.edu/deweese/student-health-insurance-plan-ship.', '"KSU Student Health Insurance Plan (UHCSR SHIP) is mandatory for all international exchange students and cannot be waived. Mandatory fees: $20/sem international activity fee, $100 first-semester orientation fee, plus UG fees ($15/sem arts, $93.84/sem career services, $90/sem student health); $10/transcript fee."');
