INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('maastricht-university-school-of-business-and-economics', 'est_monthly_living_local', 2, 'partial', 'official_web', 'https://www.maastrichtuniversity.nl/support/your-studies-begin/cost-studying-financial-assistance', 'Derived from UM official Nibud monthly student expense breakdown: Rent EUR 561 + Groceries EUR 272 + Books/materials EUR 53 + Transport EUR 67 + Leisure/sports EUR 238 + Clothing EUR 60 + Phone/internet EUR 55 = EUR 1,306/month excluding health insurance, or EUR 1,462/month including EUR 156/month health insurance. Separately, Dutch IND visa proof of means is EUR 1,250/month.', '{"currency":"EUR","max":1462.0,"min":1306.0}');
