INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('maastricht-university-school-of-business-and-economics', 'housing_notes', 2, 'verified', 'official_web', 'https://www.maastrichtuniversity.nl/support/um-guesthouse', NULL, '"UM Guesthouse offers furnished single/double rooms and studios (minimum 3-month stay for exchange students; semester housing estimates ~EUR 3,600-6,200) via https://www.maastrichtuniversity.nl/about-um/um-guesthouse-and-maastrichthousingcom. Reservations require a 30-day rent down payment and one-time cleaning fee of EUR 60, EUR 75, or EUR 100."');
