INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('maastricht-university-school-of-business-and-economics', 'international_support_services', 4, 'partial', 'official_web', 'https://www.maastrichtuniversity.nl/support/your-studies-begin/coming-maastricht-university-abroad/visa-and-residence-permit', NULL, '"UM Visa Office (visa@maastrichtuniversity.nl), SBE International Relations Office, and UM Guesthouse / Maastricht Housing services."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('maastricht-university-school-of-business-and-economics', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://www.maastrichtuniversity.nl/support/your-studies-begin/cost-studying-financial-assistance', 'Midpoint EUR 1,384.00/month (EUR 1,306 excl. insurance to EUR 1,462 incl. EUR 156/mo health insurance from UM Nibud breakdown) * 5 months = EUR 6,920.00; converted at ECB 2026-11-13 rate (collected 2026-11-15) 1 EUR = 1.1052 USD (https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html) = 7,647.98 USD.', '7647.98');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('maastricht-university-school-of-business-and-economics', 'mandatory_host_fees_and_insurance', 2, 'partial', 'official_web', 'https://www.maastrichtuniversity.nl/education/exchange/sbe', 'Nibud health insurance reference from https://www.maastrichtuniversity.nl/support/your-studies-begin/cost-studying-financial-assistance.', '"Tuition fees are waived for nominated partner exchange students (non-partner fee-paying freemover exchange is not permitted at SBE). Non-EEA visa/residence permit applicants incur Dutch IND administrative fees (est. ~EUR 250+). Health insurance coverage is mandatory (UM Nibud table cites EUR 156/month; semester optional insurance/books/misc noted at ~EUR 300-500)."');
