INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'course_restrictions_note', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx', NULL, '"Enrolled by respective college from application Course Approval Form (not guaranteed); add/drop needs prerequisite verification or permission via OIE (Tammy.Meyers@marquette.edu). Excluded: AFAS, DECS, DEDS, DEGD, DEIN, DENT, DESS, EXBU, FIAR, LEAD, MISL, MLSC, NASC, PHAS, PHTH; LAW restricted to law exchange; Business students restricted to 3-credit courses."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'credit_system_and_load', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx', NULL, '"US semester hours on 4.0 GPA scale (A=4.0, A-=3.67, B+=3.33, B=3.00, etc.). Full-time load: UG & Law 12–18 credits/semester (Business exchange students should only take 3-credit courses); Graduate 7–9 credits/semester."');
