INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'english_proficiency_and_rhet1020', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx', NULL, '"Undergraduate exchange: TOEFL iBT >=80 (min 18/section), IELTS >=6.5 (min 6.5/section), TOEFL ITP >=550 (min 50/section), Cambridge B2/C1/C2 (R/L/S 180, W 175), Duolingo >=115 (min 110 subscore), OR home-university documentation that >=50% of university-level coursework was instructed in English (or objective home-university proficiency letter on case-by-case basis). Graduate requirements vary by program. RHET 1020 not mentioned; AUC''s >=50% English instruction documentation satisfies the UG waiver rule."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'est_monthly_living_local', 2, 'partial', 'official_web', 'https://www.marquette.edu/international-education/tuition-and-costs.php', 'Derived from Marquette OIE 2026-27 Fall & Spring (2 terms, 9 months) Living Expenses estimate of USD 24,950 (shared residence hall, meals, 12-mo mandatory health insurance, books, 9-mo personal, 2-term fees incl. bus pass) divided by 9 months = USD 2,772.22/month.', '{"currency":"USD","max":2772,"min":2772}');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'exchange_page_url', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx', NULL, '"https://studyabroad.marquette.edu/?go=incoming"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'excluded_majors', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx', 'AY 2026-27 Fact Sheet lists exact prohibited course prefixes and Law restriction; older 2020-21 Fact Sheet also noted Dentistry and Nursing unavailable and Health Science/Grad School limited.', '["Law (restricted to law school exchange programs)","AFAS / Air Force Aerospace Studies","Dentistry / Dental specialties (DECS, DEDS, DEGD, DEIN, DENT, DESS)","Military & Naval Science (MISL, MLSC, NASC)","Physician Assistant Studies & Physical Therapy (PHAS, PHTH)","EXBU, FIAR, LEAD courses"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'fall_term_dates', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx', NULL, '"Fall 2026: Arrival 20–23 Aug 2026; Mandatory International Orientation 24–26 Aug 2026; UG/Grad classes start 31 Aug 2026; Fall Break 22–23 Oct; Thanksgiving Break 25–27 Nov; Final Exams 14–19 Dec 2026 (Law: orientation 20–21 Aug, classes 24 Aug, exams 7–18 Dec 2026)."');
