INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'housing_availability', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx', NULL, '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx', NULL, '"Rank preferences inside online application by application deadline (Mar 15 Fall / Oct 15 Spring); first-choice not guaranteed. Options: (1) Global Village / Campus Town Apartments (https://www.marquette.edu/residence-life/apartments-global-village.php) — furnished 2BR/4-student shared apartments, heat/water included, UG priority, more available in Spring; (2) Residence Halls (https://www.marquette.edu/residence-life/residence-halls.php) — mandatory meal plan, preferred <=20 yrs & first 2 yrs; (3) Off-campus assistance near campus (https://www.marquette.edu/offcampus/)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'instruction_languages', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx', NULL, '["English"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx', NULL, '"Mandatory International Orientation (https://www.marquette.edu/oie/admitted-students/orientation.php), OIE (https://www.marquette.edu/oie/index.php) advising & J-1 Responsible Officer (Michael Groen), Medical Clinic (https://www.marquette.edu/medical-clinic/), Counseling Center (https://www.marquette.edu/counseling-center/), Disability Services (https://www.marquette.edu/disability-services/), Campus Police (https://www.marquette.edu/mupd/), Student Organizations (https://marquette.presence.io/organizations), Service Learning (https://www.marquette.edu/service-learning/)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://www.marquette.edu/international-education/tuition-and-costs.php', '5-month USD estimate derived from Marquette OIE 2026-27 9-month Fall & Spring Living Expenses USD 24,950 (USD 2,772.22/month x 5 = USD 13,861.11; 1-semester half share = USD 12,475), verified 2026-11-15 (USD local currency; no FX conversion).', '13861.11');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx', 'Additional details from https://www.marquette.edu/oie/health-insurance.php and https://www.marquette.edu/international-education/tuition-and-costs.php.', '"Mandatory Marquette University health insurance: all exchange students are automatically enrolled and billed for their entire period of study (AY 2026-27 Fact Sheet; waivers strictly restricted per https://www.marquette.edu/oie/health-insurance.php; OIE notes ~USD 250/month baseline plan cost, included in OIE living budget alongside 2-term student fees with city bus pass)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'min_gpa_host', 1, 'unknown', 'unknown', NULL, 'AY 2026-27 Fact Sheet explicitly states ''GPA Requirement: This is dependent upon field of study and home country grading system'' (no universal numerical cutoff stated).', NULL);
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'min_standing_note', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx', NULL, '"Official partner nomination required; GPA requirement depends upon field of study and home country grading system. Students living in traditional residence halls are preferred to be <=20 years old and within their first two years of university study."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'nomination_deadlines', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx', NULL, '"Application deadlines: Fall semester 15 March; Spring semester 15 October (exceptions case-by-case)."');
