INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'spring_term_dates', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx', NULL, '"Spring 2027: Arrival 7–12 Jan 2027; Mandatory Orientation 13–15 Jan 2027; UG/Grad/Law classes start 19 Jan 2027; Spring & Easter Break 22–29 Mar 2027 (Law: 8–14 Mar); Final Exams 10–15 May 2027 (Law: 3–14 May 2027)."');
