INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('marquette-university', 'visa_lead_time_and_financial_proof', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Marquette University/2026-2027/Marquette University 2026-2027 Exchange Student Factsheet.docx', NULL, '"J-1 student visa documents are emailed after acceptance, typically after April 1 (Fall) or November 1 (Spring) (AY 2026-27 Fact Sheet; http://www.marquette.edu/oie/admitted-students/visa.shtml). Financial sponsorship form and support proof uploaded in https://studyabroad.marquette.edu/?go=incoming; OIE 2026-27 annual living expense basis for F-1/J-1 certification is USD 24,950 (+ USD 12,000 spouse / USD 6,000 per child) per https://www.marquette.edu/international-education/tuition-and-costs.php."');
