INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nagoya-university-of-commerce-and-business-nucb', 'housing_availability', 2, 'verified', 'official_web', 'https://www.nucba.ac.jp/en/campuslife/dormitory/', 'Multiple NUCB residence halls allocated upon application (Meito, Chiyoda, Higashiyama Annex, Sanbongi, Sanbongi Campus / Hiroshi Hall / Koryo Hall); strict rules prohibit partying, gathering, and smoking.', '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nagoya-university-of-commerce-and-business-nucb', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Nagoya University of Commerce and Business (NUCB)/Nagoya University of Commerce and Business (NUCB).docx', 'Live dormitory portal at https://www.nucba.ac.jp/en/campuslife/dormitory/.', '"Multiple NUCB halls in Nagoya & Nisshin (2020/21 rates incl. utilities: Sanbongi JPY 42,750/mo, Sanbongi Campus JPY 45,750/mo, Higashiyama Annex JPY 63,750/mo, Meito/Chiyoda JPY 74,000/mo; plus JPY 30,000 refundable deposit & JPY 22,500 non-refundable check-in fee per semester; newer halls include Hiroshi Hall & Koryo Hall)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nagoya-university-of-commerce-and-business-nucb', 'instruction_languages', 1, 'verified', 'official_web', 'https://www.nucba.ac.jp/en/program/exchange/', 'UG Global BBA and GR MBA/MSc international modules taught in English.', '["English","Japanese"]');
