INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nagoya-university-of-commerce-and-business-nucb', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://www.nucba.ac.jp/en/faq/exchange/living-expense.html', 'Midpoint JPY 75,000/month (60,000-90,000 JPY/month excluding accommodation) * 5 months = JPY 375,000; converted at ECB 2026-11-13 rate (collected 2026-11-15) 1 EUR = 176.83 JPY & 1 EUR = 1.1052 USD -> 1 JPY = 0.00625007 USD (https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html) = 2,343.78 USD (excludes dorm rent JPY 42,750-74,000/mo).', '2343.78');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nagoya-university-of-commerce-and-business-nucb', 'mandatory_host_fees_and_insurance', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Nagoya University of Commerce and Business (NUCB)/Nagoya University of Commerce and Business (NUCB).docx', NULL, '"Tuition waived under bilateral exchange. All students in Japan are legally required to join Japan National Health Insurance (NHI, avg ~JPY 2,000/month, covering 70% of medical care). Casebooks/materials (~JPY 2,000/course) and residence check-in/deposit fees apply (2020/21 sheet: JPY 30,000 refundable deposit + JPY 22,500 check-in fee/sem)."');
