INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northern-arizona-university', 'housing_notes', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Northern Arizona University/Fact Sheet 2024-25.pdf#page=2', NULL, '"Residence halls & NAU International House (~$4,380/sem housing + $2,885/sem meals in 2024-25 Fact Sheet; 2025-26/2026-27 housing portal at http://nau.edu/residence-life). Single-semester exchange students typically pay ~60% of academic-year housing rate."');
