INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northern-arizona-university', 'living_cost_usd_est', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Northern Arizona University/Fact Sheet 2024-25.pdf#page=2', '1-semester USD living estimate summing Housing ($4,380) + Meals ($2,885) + Personal ($1,500 minimum) = $8,765.00 USD from 2024-2025 Fact Sheet (excluding Books $450 and SHIP insurance; already in USD, recorded 2026-11-15).', '8765.0');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northern-arizona-university', 'mandatory_host_fees_and_insurance', 2, 'verified', 'official_web', 'https://in.nau.edu/campus-health-services/student-health-insurance-plan-ship/', 'Immunization requirement confirmed on NAU Fact Sheet 2024-25.pdf#page=2.', '"NAU Student Health Insurance Plan (SHIP) is strictly mandatory for all international exchange students per Arizona Board of Regents policy and cannot be waived ($1,838 Spring 2027 / ~$2,956 full year on campus health site; 2024-25 factsheet listed $1,088 Fall / $1,788 Spring). Mandatory immunizations (MMR) required prior to class registration."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northern-arizona-university', 'min_gpa_host', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Northern Arizona University/Fact Sheet 2024-25.pdf#page=2', 'Minimum 2.5 cumulative GPA on a 4.0 scale confirmed on https://nau.edu/isss/exchange-students/.', '2.5');
