INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northwestern-university', 'course_restrictions_note', 3, 'verified', 'official_web', 'https://www.northwestern.edu/abroad/visiting-students/preparing-for-northwestern/course-planning.html', NULL, '"Visiting exchange students have full access (prerequisites and open seats permitting) to undergraduate courses in Weinberg College of Arts & Sciences and McCormick School of Engineering & Applied Science; limited access to Medill (School of Journalism, Media, Integrated Marketing Communications), School of Education and Social Policy (SESP), School of Communication, and School of Professional Studies (SPS); Integrated Marketing Communications (IMC), Bienen School of Music, Kellogg School of Management, Pritzker School of Law, Feinberg School of Medicine, and 400-level+ graduate courses are closed/not open."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northwestern-university', 'credit_system_and_load', 3, 'verified', 'official_web', 'https://www.northwestern.edu/abroad/visiting-students/preparing-for-northwestern/course-planning.html', NULL, '"Quarter unit system (10-week Fall/Winter/Spring quarters; 1 course = 1 credit unit). Full-time visiting exchange load is 3 to 4 course units per quarter."');
