INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northwestern-university', 'english_proficiency_and_rhet1020', 1, 'verified', 'official_web', 'https://www.northwestern.edu/abroad/visiting-students/getting-started/applying-to-study-at-northwestern.html', NULL, '"Non-native English speakers must provide proof of English proficiency via TOEFL/IELTS scores or an official supporting letter from their home university confirming English proficiency (no fixed numeric exchange minimum or RHET 1020 exemption stated on GLO visiting-student page)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northwestern-university', 'est_monthly_living_local', 2, 'partial', 'official_web', 'https://www.northwestern.edu/abroad/visiting-students/preparing-for-northwestern/costs-money-management.html', 'Derived monthly figure from GLO AY 2026-2027 per-quarter visiting exchange recurring living budget: Housing $4,200 + Meals $2,950 + Books & Supplies $300 + Transportation $200 + Personal Expenses $850 = $8,500/quarter / 3 months = $2,833/month (excludes $2,000/quarter NU-SHIP health insurance documented in mandatory_host_fees_and_insurance and $2,000 one-time pre-arrival travel/misc).', '{"currency":"USD","max":2833,"min":2833}');
