INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northwestern-university', 'housing_availability', 2, 'verified', 'official_web', 'https://www.northwestern.edu/abroad/visiting-students/preparing-for-northwestern/housing.html', 'On-campus housing is not guaranteed, but Northwestern assists admitted visiting exchange students via an online housing contract placed based on availability.', '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northwestern-university', 'housing_notes', 2, 'verified', 'official_web', 'https://www.northwestern.edu/abroad/visiting-students/preparing-for-northwestern/housing.html', 'Quarterly housing/meal budget figures from https://www.northwestern.edu/abroad/visiting-students/preparing-for-northwestern/costs-money-management.html.', '"On-campus housing is not guaranteed; admitted visiting students submit a binding online housing contract through Residential Services and are placed based on availability (billed directly by NU for room and board; GLO estimates $4,200/quarter housing + $2,950/quarter meals). Early check-in before hall opening is restricted."');
