INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northwestern-university', 'international_support_services', 4, 'verified', 'official_web', 'https://www.northwestern.edu/abroad/visiting-students/studying-at-northwestern/arrival-and-check-in.html', NULL, '"Mandatory pre-term orientation & GLO advising, OISS immigration & J-1 compliance check-in, and International Wildcat Welcome / peer transition programming."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northwestern-university', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://www.northwestern.edu/abroad/visiting-students/preparing-for-northwestern/costs-money-management.html', 'USD official GLO per-quarter budget scaled to 5-month equivalent (1 USD = 1.0 USD, no FX conversion; 5 * $2,833/mo = $14,165 USD; calculated 2026-11-15). Note: Northwestern operates a 10-week quarter system (1 quarter recurring living budget is $8,500, or $10,500 incl. $2,000 NU-SHIP, or $12,500 incl. $2,000 one-time pre-arrival); a two-quarter stay scales proportionally.', '14165');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northwestern-university', 'mandatory_host_fees_and_insurance', 2, 'verified', 'official_web', 'https://www.northwestern.edu/student-insurance/plan-info-reqs/nu-ship-information/index.html', 'Quarterly $2,000 NU-SHIP line item also listed at https://www.northwestern.edu/abroad/visiting-students/preparing-for-northwestern/costs-money-management.html.', '"Mandatory Northwestern University Student Health Insurance Plan (NU-SHIP): estimated $2,000/quarter on GLO visiting student budget (annual 2026-2027 NU-SHIP rate is $5,996 for Sep 1, 2026 - Aug 31, 2027; automatically billed unless an approved comparable waiver is granted)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northwestern-university', 'min_gpa_host', 1, 'unknown', 'unknown', NULL, 'Incoming visiting exchange eligibility (applying-to-study-at-northwestern.html) requires partner nomination, >=1 year completed study, and English proficiency; no numeric minimum GPA is published (3.0 GPA on GLO Study Abroad applies to outgoing NU students, not incoming exchange).', NULL);
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northwestern-university', 'min_standing_note', 1, 'verified', 'official_web', 'https://www.northwestern.edu/abroad/visiting-students/getting-started/applying-to-study-at-northwestern.html', NULL, '"Must be nominated by a partner university and have completed at least one full year of university study prior to attending (no numeric minimum GPA published for incoming visiting exchange)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northwestern-university', 'nomination_deadlines', 4, 'verified', 'official_web', 'https://www.northwestern.edu/abroad/visiting-students/getting-started/applying-to-study-at-northwestern.html', NULL, '"Fall Quarter: Opens Mar 1, Deadline Apr 1; Winter Quarter: Opens Jun 1, Deadline Jul 1; Spring Quarter: Opens Sep 1, Deadline Oct 1 (must be nominated by home university first)."');
