INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northwestern-university', 'tuition_model', 2, 'verified', 'official_web', 'https://www.northwestern.edu/abroad/visiting-students/preparing-for-northwestern/costs-money-management.html', 'GLO visiting exchange page specifies $0 Northwestern tuition; exchange students continue paying home university tuition.', '"auc_exchange_waiver"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('northwestern-university', 'visa_lead_time_and_financial_proof', 2, 'verified', 'official_web', 'https://www.northwestern.edu/international/students/steps-for-newly-admitted-students/financial-documentation-requirements.html', 'Up to 4-week OISS DS-2019 processing timeline from https://www.northwestern.edu/international/students/steps-for-newly-admitted-students/index.html; visiting student J-1/DS-2019 requirement and $12,500/quarter budget from https://www.northwestern.edu/abroad/visiting-students/preparing-for-northwestern/costs-money-management.html.', '"Non-U.S. visiting exchange students require a J-1 Student Visa (Form DS-2019) via OISS. After admission and OISS Portal access (https://oissportal.northwestern.edu), OISS processing takes up to 4 weeks once a complete DS-2019 request and financial packet are submitted. Financial proof: liquid funds (bank statement dated within 6 months, plus Sponsor Statement of Support if family/friend-funded) guaranteed for the full program length (GLO 1-quarter visiting student budget totals $12,500 incl. NU-SHIP and pre-arrival; plus additional funds if bringing J-2 dependents)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'academic_style', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=4', NULL, '"Semester courses split into 2x 6-week trimesters (T1/T2 Fall, T3/T4 Spring) alongside full 12-week courses; mandatory >=50% in-class assessment weight and 30–70% exam weight; all classes/exams on Carcavelos coastal campus; Saturday exams possible."');
