INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'course_catalog_url', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=4', 'Nova SBE notes Guia UNL descriptions may be outdated pre-acceptance (full syllabi posted on Moodle after acceptance). 2023-24 Fact Sheet also links https://www.novasbe.unl.pt/en/programs/exchange-programs/courses-for-exchange-students.', '"https://guia.unl.pt/en/2025/novasbe"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'course_restrictions_note', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=5', NULL, '"All classes/exams strictly on campus at Carcavelos (Rua da Holanda, 1); midterms/exams/presentations may occur on Saturdays (#page=6). Enrollment is via points Bidding platform + Add/Drop; specific/first-choice courses not guaranteed (#page=5). Overlapping-exam courses cannot be taken simultaneously; BSc allows max 2 resits per semester (#page=4), MSc has 1 exam period per course (MSc #page=4)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'credit_system_and_load', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=4', 'Max 31.5 ECTS and no minimum stated on #page=5.', '"ECTS (1 ECTS = 28 total workload hours). Semester courses (S1/S2, 12 weeks) = 7 ECTS; trimester short courses (T1–T4, 6 weeks) = 3.5 ECTS. Incoming load: no minimum ECTS required, maximum 31.5 ECTS/semester. Grading scale 0–20 (10 minimum pass)."');
