INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'english_course_list_url', 3, 'partial', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=4', 'Full BSc (except some 1st-yr PT options) and MSc curriculum taught in English; pre-acceptance catalogue on UNL Guia.', '"https://guia.unl.pt/en/2025/novasbe"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'english_proficiency_and_rhet1020', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=3', 'Identical requirement in MSc Fact Sheet #page=3.', '"One required: IELTS 6, TOEFL iBT 80 (online acceptable), Cambridge CFE >=170, CAE/CPE (any passing grade), proof that high school or current Bachelor''s/Master''s degree is fully taught in English, OR home-institution statement confirming CEFR B2 fluency. RHET 1020 not mentioned; AUC''s English-medium current degree satisfies exemption."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'est_monthly_living_local', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=5', 'Identical monthly estimate on BSc & MSc Fact Sheets #page=5: Accommodation EUR 450–850 + Meals EUR 180–200 + Books/Supplies EUR 50 + Public Transport EUR 30–40 + Leisure EUR 80–150 = EUR 790–1,290/month.', '{"currency":"EUR","max":1290,"min":790}');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'exchange_page_url', 3, 'verified', 'official_web', 'https://www.novasbe.unl.pt/en/programs/exchange-programs/incoming-exchange-students', 'Also linked in AY 2026/27 Fact Sheet #page=2 /Annots.', '"https://www.novasbe.unl.pt/en/programs/exchange-programs/incoming-exchange-students"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'excluded_majors', 1, 'unknown', 'unknown', NULL, 'No excluded majors listed in AY 2026/27 BSc or MSc Fact Sheets; enrollment in specific courses is via Bidding and not guaranteed.', NULL);
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'fall_term_dates', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=6', 'MSc Fall dates also on MSc Fact Sheet #page=6.', '"AY 2026/27 Fall (S1): Course enrollments 14–16 Jul 2026 (BSc) / 21–23 Jul (MSc); Welcome Week 25–27 Aug (BSc) / 26–28 Aug (MSc); S1 Classes 31 Aug–4 Dec 2026 (1st-yr BSc starts 8 Sep; T1 31 Aug–12 Oct, T2 22 Oct–4 Dec); Exams: T1 14–20 Oct, S1/T2 7–21 Dec 2026; BSc resits 5–16 Jan 2027."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'final_semester_allowed', 1, 'partial', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=5', 'Allowed with explicit warning: BSc & MSc Fact Sheets #page=5 state ''We do not guarantee enrollments in specific or first choice courses... Students who need to take specific courses and/or are in the last semester of their degree must be made aware of this rule before applying.''', 'true');
