INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'host_language_requirement', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=3', NULL, '"No Portuguese required for English-taught BSc/MSc exchange courses (optional Portuguese semester courses offered via NOVA FCSH per 2023-24/2021-22 Fact Sheets)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'housing_availability', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=5', NULL, '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=5', NULL, '"Nova SBE has partnerships with external housing companies helping foreign students find accommodation in Lisbon or Carcavelos (see Life at Nova Guide: https://novasbe.maglr.com/life-at-nova-sbe-guide/accommodation)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'instruction_languages', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=3', 'BSc Fact Sheet #page=3: course offer fully available in English (1st-year courses may also be taught in Portuguese); MSc Fact Sheet #page=3: programme only available in English.', '["English","Portuguese"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=5', NULL, '"Welcome Week / Welcome Day orientation, Student Central walk-ins (Mon/Wed/Fri 10:00–13:00, #page=2), NetPa student portal, Library & Documentation Centers, study rooms, cafeterias/canteen, private medical facilities on campus, Santander Bank branch, Student Organizations & Clubs open to incoming students (#page=5)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'living_cost_usd_est', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=5', '5-month USD midpoint estimate derived from EUR 790–1,290/month range (midpoint EUR 1,040/mo x 5 = EUR 5,200) converted at ECB 2026-11-13 reference rate 1 EUR = 1.1052 USD (collected 2026-11-15 via https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html): 5,200 x 1.1052 = 5,747.04 USD.', '5747.04');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=3', 'Insurance/resit details also on #page=4-5.', '"All incoming students (including exchange and Freemovers) must pay EUR 36.50 for Administrative Fees and School Insurance (non-waivable; NetPa documents/transcripts withheld until settled). Non-EU students without EHIC are encouraged to obtain full health insurance for their stay in Lisbon (#page=5). Grade improvement exam optional fee EUR 15 (BSc #page=4)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'min_gpa_host', 1, 'unknown', 'unknown', NULL, 'Official incoming exchange page (https://www.novasbe.unl.pt/en/programs/exchange-programs/incoming-exchange-students) explicitly states there is no minimum GPA required by Nova SBE.', NULL);
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'min_standing_note', 1, 'verified', 'official_web', 'https://www.novasbe.unl.pt/en/programs/exchange-programs/incoming-exchange-students', 'Online nomination platform requirement also confirmed in AY 2026/27 Fact Sheets (#page=2-3).', '"There is no minimum GPA required to join Nova SBE''s Exchange Program; applicants must be officially nominated by a partner university through Nova SBE''s online nomination platform and satisfy English proficiency requirements."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'nomination_deadlines', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=3', NULL, '"Fall & Full Year: Nominations 20 Feb–20 Apr, Applications 27 Apr; Spring: Nominations 20 Jul–20 Sep, Applications 27 Sep (online nomination platform only; email nominations not accepted)."');
