INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'required_application_docs', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=3', NULL, '["Online nomination & application via http://apps.novasbe.pt/NovaMobility (instructions sent post-nomination)","English proficiency proof (IELTS 6, TOEFL iBT 80, CFE 170, CAE/CPE, full-English degree proof, or B2 home-school statement)","Learning Agreement (EWP for Erasmus or PDF A-Form for non-Erasmus)"]');
