INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'spring_term_dates', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=6', 'MSc Spring dates also on MSc Fact Sheet #page=6.', '"AY 2026/27 Spring (S2): Course enrollments 5–7 Jan 2027 (BSc) / 18–20 Jan (MSc); Welcome Day 29 Jan 2027; S2 Classes 1 Feb–14 May 2027 (1st-yr BSc 2 Feb; T3 1 Feb–16 Mar, T4 5 Apr–14 May); Exams: T3 18–25 Mar, S2/T4 17 May–2 Jun 2027; BSc resits 14–23 Jun 2027."');
