INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'tuition_model', 2, 'verified', 'official_web', 'https://www.novasbe.unl.pt/en/programs/exchange-programs/faq', 'Bilateral/partner exchange students pay tuition at their home institution and are exempt from Nova SBE tuition (non-partner Freemovers pay Nova SBE tuition); all incoming students still pay the mandatory EUR 36.50 administrative/insurance fee (Fact Sheet #page=3).', '"auc_exchange_waiver"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('nova-school-of-business-and-economics-nova-sbe', 'visa_lead_time_and_financial_proof', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Nova School of Business and Economics/2026- 2027/Incoming BSc Factsheet_26_27.pdf#page=5', NULL, '"Portuguese visa processing takes 2 weeks to 3 months; students must apply immediately upon receiving Acceptance Letter and must NOT enter on a Tourist Visa (cannot be renewed). School intervention in visa/residence permits is legally limited (#page=5). See Life at Nova Guide (https://novasbe.maglr.com/life-at-nova-sbe-guide/international-students) and Portuguese MFA visa forms (https://vistos.mne.gov.pt/en/short-stay-visas-schengen/general-information/application-forms)."');
