INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('peking-university', 'est_monthly_living_local', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Peking University/Fact Sheet PKU 2020-2021 (updated).pdf#page=5', 'PKU Fact Sheet p.5 lists general monthly living expenses of 1,000-3,000 RMB/month EXCLUDING accommodation (Global Village dorm 3,300-4,500 RMB/mo or off-campus 2,000-5,000 RMB/mo; bilateral agreements may cover free housing per p.4). Live ISD guide (https://www.isd.pku.edu.cn/en/index.php?m=content&c=index&a=lists&catid=31) lists annual estimates of RMB 15,000 food, RMB 5,000 misc, and RMB 35,000 accommodation.', '{"currency":"CNY","max":3000.0,"min":1000.0}');
