INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('peking-university', 'housing_availability', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Peking University/Fact Sheet PKU 2020-2021 (updated).pdf#page=4', 'If covered by bilateral exchange agreement, a shared room at Zhongguanyuan Global Village is automatically allocated upon arrival; otherwise students apply online via studyatpku.com in mid-Jul / mid-Jan (~3,300-4,500 RMB/mo) or rent off campus (~2,000-5,000 RMB/mo).', '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('peking-university', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Peking University/Fact Sheet PKU 2020-2021 (updated).pdf#page=4', 'Monthly rent rates and booking timeline on data/raw/factsheets/Peking University/Fact Sheet PKU 2020-2021 (updated).pdf#page=5.', '"Global Village (Zhong Guan Xin Yuan) on-campus dorms ~3,300-4,500 RMB/month (shared facilities, automatic if agreement covers free dorms; else online booking mid-Jul/mid-Jan via studyatpku.com); off-campus ~2,000-5,000 RMB/month (Ziroom/BeijingBuddy)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('peking-university', 'instruction_languages', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Peking University/Fact Sheet PKU 2020-2021 (updated).pdf#page=3', 'Courses primarily taught in Chinese at UG/Master levels; select English-taught courses offered.', '["Chinese","English"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('peking-university', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Peking University/Fact Sheet PKU 2020-2021 (updated).pdf#page=1', 'Orientation and ISD services on p.4-5.', '"Office of International Relations (OIR, exchange@pku.edu.cn) and International Students Division (ISD Room 330 New Sun Student Center, study@pku.edu.cn) handle nominations, Global Village dorm placement, orientation Chinese placement interviews, and visa documents."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('peking-university', 'living_cost_usd_est', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Peking University/Fact Sheet PKU 2020-2021 (updated).pdf#page=5', 'Midpoint CNY 2,000/month (1,000-3,000 CNY/month excluding accommodation) * 5 months = CNY 10,000; converted at ECB 2026-11-13 rate (collected 2026-11-15) 1 EUR = 7.3738 CNY & 1 EUR = 1.1052 USD -> 1 CNY = 0.14988201 USD (https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html) = 1,498.82 USD (excludes dorm 3,300-4,500 CNY/mo unless covered by bilateral agreement).', '1498.82');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('peking-university', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Peking University/Fact Sheet PKU 2020-2021 (updated).pdf#page=5', NULL, '"Application, tuition, and administrative fees normally waived under bilateral agreements. Exchange students MUST purchase the designated Chinese medical insurance plan at CNY 400 per semester."');
