INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('peking-university', 'min_standing_note', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Peking University/Fact Sheet PKU 2020-2021 (updated).pdf#page=3', NULL, '"Applicants must have completed at least the first year of their current study programme during the exchange, remain registered at home university, be non-Chinese citizens aged 18-45 (graduate-year students are not recommended to apply)."');
