INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('queen-s-university-at-kingston', 'course_restrictions_note', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Queens University/2026-2027/Queen′s University - Arts and Science Exchange Fact Sheet.pdf#page=9', 'For Smith Commerce exchange (`data/raw/factsheets/Queens University/2026-2027/Smith Commerce Undergraduate Exchange Fact Sheet.pdf#page=3`), students must take the majority of courses in Smith School of Business (pre-requisites apply; >=6 Business/Economics foundation courses recommended on #page=2).', '"Arts & Science excludes History (300-level+) and Political Studies (300-level+) and limits high-demand subjects (e.g., Economics, Psychology, Sociology)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('queen-s-university-at-kingston', 'credit_system_and_load', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Queens University/2026-2027/Queen′s University - Arts and Science Exchange Fact Sheet.pdf#page=8', '4.3 GPA scale on #page=9.', '"Queen''s credit units (3.0 units = 1 one-term course; 6.0 units = full-year course). Standard full-time load: 12.0–15.0 units (4–5 courses) per semester; 4.3 GPA grading scale."');
