INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('queen-s-university-at-kingston', 'english_proficiency_and_rhet1020', 1, 'verified', 'official_web', 'https://www.queensu.ca/admission/about-applying/english-language-requirements', 'Confirmed on Smith Commerce 2026-27 Fact Sheet (data/raw/factsheets/Queens University/2026-2027/Smith Commerce Undergraduate Exchange Fact Sheet.pdf#page=2).', '"Non-English-medium applicants must submit IELTS Academic 6.5 (no band <6.0), TOEFL iBT/Home Edition 88 (min 20 in Writing, Speaking, Reading, and Listening; code 0949), Duolingo 120, CAEL 70, PTE 60, or Cambridge 175 (Smith #page=2 also lists TOEFL PBT 580). Exempt with IB diploma (excl. SL English B alone) or >=3 years residency in an English-primary country or full-time study in an English-medium institution. RHET 1020 waiver not stated."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('queen-s-university-at-kingston', 'est_monthly_living_local', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Queens University/2026-2027/Smith Commerce Undergraduate Exchange Fact Sheet.pdf#page=4', 'Sum of Smith Commerce 2026-2027 monthly Kingston estimates: off-campus housing incl. utilities CAD $720–$1,380 + food $450 + phone $35–$65 + misc >=$355 = CAD $1,560–$2,250+/month (local Kingston Transit pass included with student card).', '{"currency":"CAD","max":2250,"min":1560}');
