INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('queen-s-university-at-kingston', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Queens University/2026-2027/Queen′s University - Arts and Science Exchange Fact Sheet.pdf#page=13', 'Monthly rental estimate from Smith Commerce Fact Sheet #page=4.', '"Off-campus rentals only (est. CAD $720–$1,380/month incl. utilities); supported by Queen''s Off-Campus Living Advisor (OCLA) and Queen''s University International Centre (QUIC)."');
