INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('queen-s-university-at-kingston', 'living_cost_usd_est', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Queens University/2026-2027/Smith Commerce Undergraduate Exchange Fact Sheet.pdf#page=4', '5-month midpoint estimate: 1,905 CAD/month * 5 months = 9,525 CAD * 0.701358 USD/CAD = 6,680.44 USD (ECB 2026-11-13 cross rate 1 EUR = 1.5758 CAD and 1 EUR = 1.1052 USD -> 1 CAD = 0.701358 USD, collected 2026-11-15: https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html).', '6680.4');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('queen-s-university-at-kingston', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Queens University/2026-2027/Smith Commerce Undergraduate Exchange Fact Sheet.pdf#page=4', 'Transcript hold rule on Arts & Science Fact Sheet #page=10; UHIP mandatory confirmation on https://www.queensu.ca/international/incoming-exchange/costs.', '"Mandatory automatic enrollment in University Health Insurance Plan (UHIP) for international/exchange students (~CAD $264/1 term or CAD $528/2 terms per 2026-27 factsheets; transcripts held if UHIP balance owed). Student card includes Kingston Transit."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('queen-s-university-at-kingston', 'min_gpa_host', 1, 'unknown', 'unknown', NULL, 'Queen''s incoming exchange relies on partner university nomination benchmarks (note: the 2.7/2.8 cGPA figures on queensu.ca/international/bilateral-exchange-program govern outgoing Queen''s students).', NULL);
