INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('queen-s-university-at-kingston', 'nomination_deadlines', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Queens University/2026-2027/Queen′s University - Arts and Science Exchange Fact Sheet.pdf#page=4', 'Same deadlines confirmed on Smith Commerce Fact Sheet #page=2.', '"Fall / Full Year: nomination April 1, application April 30. Winter: early nomination April 1 / final nomination September 1, final application September 30 (fixed annual dates)."');
