INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('ritsumeikan-asia-pacific-university', 'english_proficiency_and_rhet1020', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Ritsumeikan Asia Pacific University (APU)/(Fall 2025) APU Student Exchange Program_Fall 2025 Information Sheet.pdf#page=3', NULL, '"For non-native English/Japanese students choosing English-basis: TOEFL iBT 79, IELTS 6.0, TOEIC L&R 780, PTE Academic 50, or Cambridge FCE Grade B. No RHET 1020 waiver stated."');
