INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('ritsumeikan-asia-pacific-university', 'housing_availability', 2, 'verified', 'official_web', 'https://en.apu.ac.jp/abroad/prospective/incoming/accomodation/', 'Official en.apu.ac.jp and Fall 2025 Fact Sheet (#page=9) confirm designated AP House 3 or AP House 4 accommodation is provided/guaranteed for all exchange students (no other housing options allowed).', '"guaranteed"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('ritsumeikan-asia-pacific-university', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Ritsumeikan Asia Pacific University (APU)/(Fall 2025) APU Student Exchange Program_Fall 2025 Information Sheet.pdf#page=9', NULL, '"Students choose AP House 3 (~JPY 230,000/sem) or AP House 4 (~JPY 300,000/sem; ~5-month package incl. rent, utilities, move-in fee, bedding), paid by lump-sum bank wire prior to arrival; no other housing allowed."');
