INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('ritsumeikan-asia-pacific-university', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Ritsumeikan Asia Pacific University (APU)/(Fall 2025) APU Student Exchange Program_Fall 2025 Information Sheet.pdf#page=5', NULL, '"Airport pick-up service, mandatory pre-term orientation, APU BUDDY system (#page=5 & #page=10)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('ritsumeikan-asia-pacific-university', 'living_cost_usd_est', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Ritsumeikan Asia Pacific University (APU)/(Fall 2025) APU Student Exchange Program_Fall 2025 Information Sheet.pdf#page=9', '5-month estimate in JPY: midpoint 116000 JPY/month * 5 * 0.006250 USD/JPY = 3625.04 USD (1 EUR = 1.1052 USD and 1 EUR = 176.83 JPY -> 1 JPY = 0.006250 USD; ECB 2026-11-13 reference rate collected 2026-11-15 at https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html). Summed from APU itemized Fact Sheet budgets over 5-month semester: AP House 3/4 (~230,000–300,000 JPY/sem = 46,000–60,000 JPY/mo), food (30,000–50,000 JPY/mo), transport (~50,000 JPY/sem = 10,000 JPY/mo; web lists 45,000–75,000 JPY/sem), books/academic (10,000–20,000 JPY/sem = 2,000–4,000 JPY/mo), and other personal (10,000 JPY/mo per Spring 2025 Fact Sheet #page=7).', '3625.04');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('ritsumeikan-asia-pacific-university', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Ritsumeikan Asia Pacific University (APU)/(Fall 2025) APU Student Exchange Program_Fall 2025 Information Sheet.pdf#page=9', NULL, '"Compulsory Japan National Health Insurance (~JPY 14,000/sem Fall 2025, ~JPY 10,000/sem Spring 2025) plus Student''s Comprehensive Renters Insurance (~JPY 3,000/sem per Spring 2025 #page=8)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('ritsumeikan-asia-pacific-university', 'min_gpa_host', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Ritsumeikan Asia Pacific University (APU)/(Fall 2025) APU Student Exchange Program_Fall 2025 Information Sheet.pdf#page=3', 'Minimum GPA 2.00 on a 4.00 scale.', '2.0');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('ritsumeikan-asia-pacific-university', 'min_standing_note', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Ritsumeikan Asia Pacific University (APU)/(Fall 2025) APU Student Exchange Program_Fall 2025 Information Sheet.pdf#page=3', NULL, '"Undergraduate level; must have completed at least 1 semester at home university with official grades available."');
