INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('roanoke-college', 'english_proficiency_and_rhet1020', 1, 'verified', 'official_web', 'https://www.roanoke.edu/inside/a-z_index/international_education/information_for_prospective_students', NULL, '"Proof of English proficiency is required if the primary language of instruction at the home institution is not English; accepted tests include TOEFL, IELTS, Duolingo, CEFR, Pearson''s English Test, or Cambridge Exams (exact numeric cutoffs and RHET 1020 equivalency are not stated; AUC is an English-medium institution)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('roanoke-college', 'est_monthly_living_local', 2, 'partial', 'official_web', 'https://www.roanoke.edu/inside/a-z_index/business_office/tuition_and_fees/international_tuition_and_financial_aid', 'Derived from Roanoke College 2026-27 on-campus Housing + 19-Meal Plan rates divided across a 5-month semester: Standard double housing ($7,614/yr = $3,807/sem) to single/apartment rooms up to $9,786/yr ($4,893/sem), plus 19-Meal Plan ($8,732/yr = $4,366/sem) = $8,173-$9,259/semester ($1,634.60-$1,851.80/month). Excludes $1,580/yr health insurance and books/personal expenses.', '{"currency":"USD","max":1851.8,"min":1634.6}');
