INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('roanoke-college', 'housing_availability', 2, 'verified', 'official_web', 'https://www.roanoke.edu/inside/a-z_index/business_office/tuition_and_fees/international_tuition_and_financial_aid', 'Residential campus with residence halls including Global Village (Chalmers Hall); exchange housing guarantee status is not explicitly stated.', '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('roanoke-college', 'housing_notes', 2, 'verified', 'official_web', 'https://www.roanoke.edu/inside/a-z_index/business_office/tuition_and_fees/international_tuition_and_financial_aid', NULL, '"2026-27 on-campus standard double room is $7,614/yr ($3,807/sem), single rooms up to $8,668-$9,786/yr; required 19-meal plan $8,732/yr ($4,366/sem). International and domestic students may reside in the Global Village community (Chalmers Hall)."');
