INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('roanoke-college', 'international_support_services', 4, 'verified', 'official_web', 'https://www.roanoke.edu/inside/a-z_index/international_student_services/visa_process', NULL, '"Incoming partner exchange applications handled directly by Dr. Michael Hancock-Parmer (mhancock@roanoke.edu); International Student Services (Morehead Hall) and Office of Global Engagement (Lucas Hall) handle F-1/J-1 advising and Global Village housing."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('roanoke-college', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://www.roanoke.edu/inside/a-z_index/business_office/tuition_and_fees/international_tuition_and_financial_aid', '1 USD = 1.0 USD on 2026-11-15 (native USD); 5-month semester midpoint of 2026-27 on-campus housing ($3,807 double to $4,893 Maroon Village single/apt per sem) + 19-Meal Plan ($4,366/sem) = $8,173-$9,259/semester (midpoint $8,716.00/semester). Excludes $1,580/yr international health insurance and books/personal costs.', '8716.0');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('roanoke-college', 'mandatory_host_fees_and_insurance', 2, 'partial', 'official_web', 'https://www.roanoke.edu/inside/a-z_index/business_office/tuition_and_fees/international_tuition_and_financial_aid', NULL, '"2026-2027 mandatory international student health insurance plan is $1,580/year (official ISEP exchange students are exempt from this institutional insurance charge). Regular residential student/technology fees range $2,208-$3,788/year."');
