INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('sciences-po-institute-d-etudes-politiques-de-paris', 'credit_system_and_load', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Sciences Po/2025-2026/factsheet2025-2026.pdf#page=2', NULL, '"ECTS: minimum 5 ECTS to maximum 30 ECTS per semester (up to 60 ECTS/year). Starting Sept 2025, language courses are 4 ECTS graded Pass/Fail (`Useful Info. Science Po.docx`); strict attendance policy allows max 2 absences per class."');
