INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-american-university-of-the-emirates', 'est_monthly_living_local', 2, 'partial', 'official_web', 'https://aue.ae/cost-of-attendance/', 'Derived monthly living range from AUE Cost of Attendance annual figures divided by 12 months: Accommodation AED 15,000-30,000 + Cost of living AED 36,000 + Transportation AED 6,000 + Utilities AED 12,000 = AED 69,000-84,000/yr -> AED 5,750-7,000/month. (Outdated 2020-21 local DOCX estimated 12,500 USD/yr or $1,214-1,938 USD/mo).', '{"currency":"AED","max":7000,"min":5750}');
