INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-american-university-of-the-emirates', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://aue.ae/cost-of-attendance/', '5-month estimate derived from monthly AED range 5,750-7,000 (midpoint 6,375.0)/month. Official peg 1 USD = 3.6725 AED (1 AED = 0.272294 USD) from Central Bank of the UAE (retrieved 2026-11-15 at https://centralbank.ae/en/reports-and-statistics/exchange-rates/); 5-month USD est = 6,375.0 AED * 5 / 3.6725 = 8,679.37 USD.', '8679.37');
