INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'course_restrictions_note', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Kansas University/Fact Sheet 2026-27/KU Exchange Fact Sheet 2026-27.pdf#page=3', NULL, '"Enrollment blocked until AEC English test/waiver, ''You at KU'' orientation registration, and health check-in appointment are completed. Must select Lawrence campus courses only (KU Med/Edwards/Regents prohibited), avoid Athletic Training/Law/Medicine/Pharmacy, and submit >=2 alternate courses. Independent Study/research credit typically unavailable; portfolios/auditions may apply for Architecture/Design/Art/Music."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'credit_system_and_load', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Kansas University/Fact Sheet 2026-27/KU Exchange Fact Sheet 2026-27.pdf#page=3', NULL, '"US semester credit hours. Exchange students must enroll full-time within exact caps: Undergraduates 12–15 credits/semester (typically 4–5 classes); Graduates 9 credits/semester (up to 12 max). Exceeding 15 UG / 12 Grad credits triggers direct tuition/fee charges; max 1 online course/semester."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'daily_life_english_friendliness', 4, 'unknown', 'unknown', NULL, NULL, NULL);
