INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'english_proficiency_and_rhet1020', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Kansas University/Fact Sheet 2026-27/KU Exchange Fact Sheet 2026-27.pdf#page=2', NULL, '"TOEFL and IELTS scores are NOT required to apply for exchange at KU; however, all non-native English speakers must take the Applied English Center (AEC) English Proficiency Exam (online pre-arrival or at orientation) unless waived by TOEFL iBT >=79 (no subscore <18 UG / <23/section Grad) or IELTS >=6.5 (no subscore <6.0). Note ''Assessment of Functional Level of English'' J-1 form does NOT waive the AEC exam. RHET 1020 exemption not mentioned."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'est_monthly_living_local', 2, 'partial', 'official_web', 'https://world.ku.edu/costs', 'Derived from KU International Admissions annual international undergraduate living expenses budget USD 18,424/yr (housing, food, personal items, books, mandatory health insurance) divided over 9 academic months = USD 2,047.11/month.', '{"currency":"USD","max":2047,"min":2047}');
