INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'excluded_majors', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Kansas University/Fact Sheet 2026-27/KU Exchange Fact Sheet 2026-27.pdf#page=3', 'AY 2026-27 Fact Sheet #page=3 also states exchange students may only take courses at the Lawrence campus (excluding KU Med, Edwards, and Regents campuses) and Independent Study/research credit is typically unavailable.', '["Athletic Training","Law","Medicine","Pharmacy"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'fall_term_dates', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Kansas University/Fact Sheet 2026-27/KU Exchange Fact Sheet 2026-27.pdf#page=3', NULL, '"Fall 2026: Orientation Arrival Date 10 Aug 2026; Classes begin 24 Aug 2026; Labor Day 7 Sep; Fall Break 17–20 Oct; Thanksgiving Break 25–29 Nov; Final Exams end 18 Dec 2026 (https://registrar.ku.edu/calendar)."');
