INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'housing_availability', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Kansas University/Fact Sheet 2026-27/KU Exchange Fact Sheet 2026-27.pdf#page=4', NULL, '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Kansas University/Fact Sheet 2026-27/KU Exchange Fact Sheet 2026-27.pdf#page=4', NULL, '"Exchange students arrange their own housing once admitted with KUID (https://housing.ku.edu; early move-in ~$40/night). On-campus options: apartments (Jayhawker Towers, Stouffer, McCarthy — open over breaks, optional dining) or Residence Halls (GSP, Corbin, Ellsworth, Hashinger open to all levels; mandatory dining plan at https://union.ku.edu/dining-plans; closed Winter Break unless extra fee paid). Fall-only students can opt out of Spring from AY contracts free of charge. Off-campus adjacent alternative: Naismith Hall (https://www.naismithhall.com/)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'instruction_languages', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Kansas University/Fact Sheet 2026-27/KU Exchange Fact Sheet 2026-27.pdf#page=2', NULL, '["English"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Kansas University/Fact Sheet 2026-27/KU Exchange Fact Sheet 2026-27.pdf#page=4', NULL, '"Mandatory ''You at KU'' orientation via ISS (https://iss.ku.edu/newly-admitted-students) including immigration check-in, shuttled shopping excursions, and social activities (#page=4); Applied English Center (https://studyabroad.ku.edu/applied-english-center); Campus Fee covers recreation/fitness center, campus bus, library, health center, >500 student groups (#page=1,5)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://world.ku.edu/costs', '5-month USD estimate derived from KU International Admissions annual living expenses budget USD 18,424/yr (USD 2,047.11/mo over 9 months x 5 = USD 10,235.56; 1-semester half share = USD 9,212), verified 2026-11-15 (USD local currency; no FX conversion).', '10235.56');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Kansas University/Fact Sheet 2026-27/KU Exchange Fact Sheet 2026-27.pdf#page=5', NULL, '"Students pay mandatory UnitedHealthcare health insurance (~USD 1,180/semester unless waived via https://iss.ku.edu/waivers by 1st day of class), Orientation Fee (USD 290), ISS Check-In Fee (USD 40), and KUID card (USD 21) — billed after arrival/enrollment."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'min_gpa_host', 1, 'unknown', 'unknown', NULL, 'No minimum incoming exchange GPA stated in AY 2026-27 Fact Sheet (the 2.5 GPA on #page=2 applies solely to an English-proficiency test waiver for students who graduated from an English-language high school; 2.5 on KU Study Abroad pages applies to outgoing KU students).', NULL);
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'min_standing_note', 1, 'verified', 'official_web', 'https://studyabroad.ku.edu/exchangestudents', 'Official partner nomination rule also on AY 2026-27 Fact Sheet #page=2.', '"Incoming exchange students must be officially nominated by their home university and remain in good academic standing as non-degree seeking study abroad students."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'nomination_deadlines', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Kansas University/Fact Sheet 2026-27/KU Exchange Fact Sheet 2026-27.pdf#page=2', NULL, '"Fall / Full Academic Year: Nomination 1 March (at least 2 weeks pre-app) / Application 15 March; Spring: Nomination 1 October / Application 15 October."');
