INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'tuition_model', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Kansas University/Fact Sheet 2026-27/KU Exchange Fact Sheet 2026-27.pdf#page=5', 'AY 2026-27 Fact Sheet #page=5 confirms Tuition, Course Fees, Technology Fee, International Student Service Fee, Infrastructure Fee, Wellness Fee, and Campus Fee are covered by KU Study Abroad & Global Engagement (exchange application fee also waived via code 42626669ku in 2026 UG Application Instructions #page=1).', '"auc_exchange_waiver"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-kansas', 'visa_lead_time_and_financial_proof', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Kansas University/Fact Sheet 2026-27/KU Exchange Fact Sheet 2026-27.pdf#page=4', 'Also cites #page=2 (financial docs), 2026 UG Application Instructions #page=4 (select J-1 Exchange Visitor), and https://iss.ku.edu/proof-finances.', '"J-1 Exchange Visitor (student) DS-2019 required; must arrive no later than DS-2019 Start Date (= Orientation Arrival Date). Proof of financial support must cover the ENTIRE J-1 duration using bank statements/letters <6 months old or sponsorship letters (+ signed Affidavit of Financial Support if not student''s own funds) per https://iss.ku.edu/proof-finances and Fact Sheet #page=2,4."');
