INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-new-mexico', 'english_proficiency_and_rhet1020', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/TUo New Mexico/UNM Information Sheet 2025-2026.pdf#page=3', NULL, '"Exempt if attending a university where English is the medium of instruction for >=1 year full-time (applies to AUC) or qualifying HS diploma <=2 yrs old. Otherwise: UG TOEFL iBT 68 / IELTS 6.0 / PTE 47 / Duolingo 95 / C1-C2 169; GR iBT 79 / IELTS 6.5 / PTE 53 / Duolingo 105 / C1-C2 176; Law School TOEFL iBT 100."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('the-university-of-new-mexico', 'est_monthly_living_local', 2, 'partial', 'official_web', 'https://bursar.unm.edu/tuition-and-fees/tuition-fee-information.html', 'Derived monthly UG living budget from UNM 2026-27 academic-year Cost of Attendance divided by 10 months (2 semesters x 5 mo): Housing & Food $10,648-$12,471 + Books $1,869 + Transportation $2,498 + Misc/Personal $2,800 = $17,815-$19,638/AY ($8,907.50-$9,819/sem -> $1,781.50-$1,963.80/mo). Visa financial proof minimum is $7,500/sem ($15,000/AY) per Fact Sheet p.3.', '{"currency":"USD","max":1964,"min":1782}');
