INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('universidad-carlos-iii-de-madrid-uc3m', 'course_restrictions_note', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/1. UC3M Fact Sheet 2026_2027.pdf#page=5', 'Full list of restricted/excluded degrees on data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/2. Course+Offer+Guide26-27.pdf#page=4-5; no-distance-exam rule on data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/1. UC3M Fact Sheet 2026_2027.pdf#page=4.', '"Non-European exchange students may enroll in courses across ALL UC3M schools (unlike Erasmus+, restricted to admitted school). Course enrollment is first-come, first-served with high-demand caps (plan backups). Distance exams are not allowed."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('universidad-carlos-iii-de-madrid-uc3m', 'credit_system_and_load', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/2. Course+Offer+Guide26-27.pdf#page=5', 'Also stated in data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/1. UC3M Fact Sheet 2026_2027.pdf#page=5-6.', '"ECTS credit system: minimum 6 ECTS (1 course) and maximum 30 ECTS per semester (60 ECTS per full academic year); max 3 Humanities/Cross-curricula short courses."');
