INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('universidad-carlos-iii-de-madrid-uc3m', 'english_proficiency_and_rhet1020', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/1. UC3M Fact Sheet 2026_2027.pdf#page=4', 'CEFR B2 equivalency guidance in data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/0. UC3M English Proficiency Letter Template.pdf#page=1.', '"CEFR B2 required for English-taught courses (referenced ~TOEFL 80 / IELTS 6.5 in UC3M English Proficiency Letter Template). No formal certificate upload is required by UC3M — partner home institution guarantees nominees hold B2 level. RHET 1020 waiver policy not mentioned."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('universidad-carlos-iii-de-madrid-uc3m', 'est_monthly_living_local', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/1. UC3M Fact Sheet 2026_2027.pdf#page=7', 'UC3M Fact Sheet 2026-27 p.7 explicitly states: ''Living expenses in Madrid (including sharing an apartment, food and transportation) would be around 700/800 EUR/month.''', '{"currency":"EUR","max":800.0,"min":700.0}');
