INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('universidad-carlos-iii-de-madrid-uc3m', 'excluded_majors', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/2. Course+Offer+Guide26-27.pdf#page=4', 'Restricted/excluded Bachelor degree programmes listed on Course Offer Guide 2026-27 p.4-5; Legal Clinic, Internships, and Final Degree Project excluded for non-Engineering schools.', '["Master''s programs (unless explicitly authorized under Master agreement)","Hispanic Studies Program","Philosophy, Politics, and Economics","Science, Technology, and Humanities","Security Engineering / Public Security Management","Double Degree in Computer Engineering and Business Administration","Bachelor in Science","4th-year Robotics Engineering","Artificial Intelligence","Applied Mathematics","Neuroscience","Biomedical Sciences","Primary Education","Quantum Technology Engineering with Dual Mention"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('universidad-carlos-iii-de-madrid-uc3m', 'fall_term_dates', 1, 'verified', 'official_web', 'https://www.uc3m.es/studies/international-exchange-students-in-UC3M-/bachelor-degrees/home', 'Early vs Jan exam split explained in data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/1. UC3M Fact Sheet 2026_2027.pdf#page=4; calendar portal https://www.uc3m.es/bachelor-degree/practical-information/calendar-schedules.', '"2026-27 Fall Semester: Welcome Event Sep 4, 2026; Courses Sep 7 - Dec 11, 2026; Anticipated exams for Fall-only exchange students Dec 16-22, 2026 (Full-year students sit Fall exams Jan 11-25, 2027)."');
