INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('universidad-carlos-iii-de-madrid-uc3m', 'host_language_requirement', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/1. UC3M Fact Sheet 2026_2027.pdf#page=4', 'Digital Humanities C1 rule on data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/2. Course+Offer+Guide26-27.pdf#page=4.', '"CEFR B2 in Spanish (for Spanish-taught courses) or CEFR B2 in English (for English-taught courses), certified/guaranteed by home partner university; C1 Spanish required for ''Spanish'' Digital Humanities course."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('universidad-carlos-iii-de-madrid-uc3m', 'housing_availability', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/4. HousingOptionsPartners.pdf#page=1', 'UC3M Residence Halls (2 in Getafe, 1 in Leganes — semester students increasingly accommodated), plus partnered private student residences (LIV Student, MiCampus, Amro, Vivocoliving) and housing agencies.', '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('universidad-carlos-iii-de-madrid-uc3m', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/4. HousingOptionsPartners.pdf#page=1', 'Rental scam warning and Living in Madrid guide on data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/1. UC3M Fact Sheet 2026_2027.pdf#page=7.', '"Options include UC3M Residence Halls (2 Getafe, 1 Leganes), partner residences (Getafe: LIV Student, MiCampus, Amro, Vivocoliving; Leganes: MiCampus), and verified housing agencies. Secure housing prior to arrival (Fact Sheet p.7)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('universidad-carlos-iii-de-madrid-uc3m', 'instruction_languages', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/1. UC3M Fact Sheet 2026_2027.pdf#page=4', 'Courses offered in English, Spanish, or bilingual groups; extensive English course lists on Getafe and Leganes campuses.', '["Spanish","English"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('universidad-carlos-iii-de-madrid-uc3m', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/1. UC3M Fact Sheet 2026_2027.pdf#page=6', 'No-pickup & Buddy/Support/Special-Needs on data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/1. UC3M Fact Sheet 2026_2027.pdf#page=4,6,7.', '"No airport pickup; Buddy program, Welcome Days, ESN UC3M, Student Support Center, psychological orientation in English & Spanish, special-needs support (register before Jul 15 Fall / Dec 15 Spring), and fee-paying Language Center Spanish courses."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('universidad-carlos-iii-de-madrid-uc3m', 'living_cost_usd_est', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/1. UC3M Fact Sheet 2026_2027.pdf#page=7', 'Midpoint EUR 750.00/month (700-800 EUR/month) * 5 months = EUR 3,750.00; converted at ECB 2026-11-13 rate (collected 2026-11-15) 1 EUR = 1.1052 USD (https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html) = 4,144.50 USD.', '4144.5');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('universidad-carlos-iii-de-madrid-uc3m', 'mandatory_host_fees_and_insurance', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/1. UC3M Fact Sheet 2026_2027.pdf#page=6', NULL, '"Tuition waived for exchange students. UC3M does not provide health insurance; incoming exchange students must arrange comprehensive travel/illness/accident insurance covering repatriation expenses due to illness or accident (Fact Sheet p.6)."');
