INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('universidad-carlos-iii-de-madrid-uc3m', 'visa_lead_time_and_financial_proof', 2, 'verified', 'official_web', 'https://www.uc3m.es/ss/Satellite/UC3MInstitucional/en/TextoDosColumnas/1371219273906/International_Exchange_Students', 'Admission SIGMA upload workflow on data/raw/factsheets/Universidad Carlos III de Madrid (UC3M)/UC3M Materials/1. UC3M Fact Sheet 2026_2027.pdf#page=3.', '"Non-EU students receive a SIGMA Acceptance Letter to apply for a Spanish student visa at a Spanish embassy/consulate; must upload passport, visa, and insurance docs to SIGMA by Jul 20 (Fall/FY) or Jan 24 (Spring). Stays >6 months require a Foreigner''s Identity Card (TIE) within 1 month of arrival. Spanish visa economic proof uses IPREM benchmark (~EUR 600/month * months of stay)."');
