INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('university-of-central-florida-ucf', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/UCF/2026-2027/UCF Fact Sheet 2026-2027.pdf#page=7', 'Insurance & immunization policies stated on #page=6; fee figures on #page=7.', '"Mandatory adequate health insurance per Florida Board of Governors (UCF Health Insurance ~$500–$950/sem depending on coverage); mandatory immunizations prior to registration; International Fee $50, Transcript $18. Lynx Orlando buses and UCF Shuttle free with UCF ID."');
