INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('university-of-edinburgh', 'course_restrictions_note', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/UoEdinburgh/International Exchange factsheet.pdf#page=4', NULL, '"Excluded unless subject-specific agreement: Medicine, Veterinary Medicine, Studio Arch/Art/Design, Education & Sport. High-pressure/no guarantee (incl. Law per Excel & PDF p.4): Law, Politics, Informatics, History, Psychology, Classics, Archaeology, English Lit, Geography, Music, Philosophy, Health, Nursing, Art/Design electives, AEVS/EIBC. Add/drop closes end of teaching week 2."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('university-of-edinburgh', 'credit_system_and_load', 3, 'verified', 'fact_sheet', 'data/raw/factsheets/UoEdinburgh/International Exchange factsheet.pdf#page=4', NULL, '"Scottish credit framework: standard and mandatory full-time load is strictly 60 credits per semester (majority of courses 20 cr/sem or 40 cr/yr); students cannot normally take >60 or <60 credits."');
