INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('university-of-edinburgh', 'english_proficiency_and_rhet1020', 1, 'verified', 'official_web', 'https://global.ed.ac.uk/study-abroad/study-options-and-entry-requirements', NULL, '"Standard requirements: IELTS Academic 6.5 (5.5 each band) or TOEFL iBT 92 (20 each section), higher for some 3rd-yr humanities/social science courses. Exempt if studying at an Edinburgh-approved English-medium university, or if on <6 month Standard Visitor route (unless taking 3rd/4th-yr courses per Fact Sheet p.5)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('university-of-edinburgh', 'est_monthly_living_local', 2, 'verified', 'official_web', 'https://www.ed.ac.uk/students/finance/student-funding/undergraduate/cost-of-living', 'Official University of Edinburgh AY 2026-2027 UG cost-of-living average £1,546/month (£13,914 per 39-wk AY; £18,552 per 52-wk yr): Accommodation & utilities £980 avg (range £752-1,249), food £248, socialising/leisure £248, local bus £58 (often free under age 22 via Young Scot NEC), mobile £12. Separate UK Student Visa outside-London threshold is £1,203/mo.', '{"currency":"GBP","max":1546,"min":1546}');
