INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('university-of-edinburgh', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://www.ed.ac.uk/students/finance/student-funding/undergraduate/cost-of-living', '5-month estimate derived from monthly GBP range 1,546/month. ECB cross-rate 1 EUR = 1.1052 USD and 1 EUR = 0.83559 GBP -> 1 GBP = 1.322658 USD (2026-11-13, retrieved 2026-11-15 at https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html); 5-month USD est = 1,546.0 GBP * 5 * 1.322658 = 10,224.15 USD.', '10224.15');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('university-of-edinburgh', 'mandatory_host_fees_and_insurance', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/UoEdinburgh/International Exchange factsheet.pdf#page=6', NULL, '"Single-semester students in private (non-university) accommodation may owe UK Council Tax; Student Route (>6 mo) requires Immigration Health Surcharge for NHS access; Standard Visitor (<=6 mo) receives free emergency/NHS treatment but travel/medical insurance recommended; resit exam charges apply."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('university-of-edinburgh', 'min_gpa_host', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/UoEdinburgh/International Exchange factsheet.pdf#page=3', 'Cumulative GPA >=3.0/4.0 (or B average / ECTS ''C'') at home university.', '3.0');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('university-of-edinburgh', 'min_standing_note', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/UoEdinburgh/International Exchange factsheet.pdf#page=3', NULL, '"CAHSS applicants must show >=1 full year of completed university study at application (case-by-case if from prior institution); College of Science & Engineering applicants must show >=1 completed semester."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('university-of-edinburgh', 'nomination_deadlines', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/UoEdinburgh/International Exchange factsheet.pdf#page=4', NULL, '"Student Application Deadlines (after home nomination): May 31 for September start (apply early May for July offer/housing); October 31 for January start (apply early Oct for Nov offer); strict, no late apps."');
