INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('university-of-helsinki', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://studies.helsinki.fi/instructions/article/living-helsinki', 'Midpoint EUR 1,075.00/month (900-1,250 EUR/month) * 5 months = EUR 5,375.00; converted at ECB 2026-11-13 rate (collected 2026-11-15) 1 EUR = 1.1052 USD (https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html) = 5,940.45 USD.', '5940.45');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('university-of-helsinki', 'mandatory_host_fees_and_insurance', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/UoHelsinki/2026-2027/University of Helsinki Fact Sheet 2026-2027 Erasmus+ ICM.pdf#page=5', NULL, '"Tuition fees waived. Non-EU nationals must hold comprehensive health insurance prior to applying for a Migri residence permit (EUR 450 online permit fee, partially covered only for Erasmus+ ICM per agreement; UH purchases insurance only for Erasmus+ ICM). Student Union membership (EUR 40-45/sem) is voluntary for exchange students."');
