INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('vienna-university-of-economics-and-business-wu', 'housing_availability', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Vienna University of Economics and Business/2027-2028/WU_Factsheet_2728.pdf#page=5', 'WU has no on-campus dormitories, but International Office assists via OeAD Student Housing (pre-reserved rooms; registration fee waived with code ''WUINCOMING'' per wu.ac.at) and other student residence providers.', '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('vienna-university-of-economics-and-business-wu', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Vienna University of Economics and Business/2027-2028/WU_Factsheet_2728.pdf#page=5', 'Accommodation page linked on p. 5: https://www.wu.ac.at/en/programs/international-and-exchange-students/incoming-exchange-students/exchange-semester/your-semester-at-wu-from-start-to-finish/accommodation.', '"Off-campus student residences (OeAD Student Housing promo ''WUINCOMING'' waives registration fee per wu.ac.at) or private flats: €450-€900/month (from ~€437/month at OeAD)."');
