INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('vienna-university-of-economics-and-business-wu', 'living_cost_usd_est', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Vienna University of Economics and Business/2027-2028/WU_Factsheet_2728.pdf#page=5', 'Midpoint 1650 EUR/month * 5 months * 1.1052 USD/EUR = 9117.90 USD (ECB reference rate dated 2026-11-13, collected 2026-11-15: https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html).', '9117.9');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('vienna-university-of-economics-and-business-wu', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Vienna University of Economics and Business/2027-2028/WU_Factsheet_2728.pdf#page=5', 'Entry travel insurance and ÖGK monthly rate verified on https://oead.at/en/to-austria/entry-and-residence/.', '"Mandatory Austrian Students'' Union (ÖH) dues: €25/semester (per Factsheet p. 5; ~€26 on wu.ac.at). Comprehensive health insurance required (ÖGK Student Self-Insurance ~€75/month per WU p. 5, €78.84/month per OeAD; entry travel insurance >=€30,000 needed for first month)."');
