INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('virginia-polytechnic-institute-and-state-university-virginia-tech', 'english_proficiency_and_rhet1020', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Virginia Tech/24-25 Virginia Tech (VT) fact sheet.pdf#page=2', 'DAAD B2 and English-medium exemption confirmed in data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=3 and on https://www.globaleducation.vt.edu/students/visiting-exchange.html.', '"UG minimums (`24-25 Fact Sheet#page=2`): IELTS 6.5 (no subscore <6.5), TOEFL iBT 80 (no subscore <16; CBT 233), Cambridge C1, or Duolingo 115. GR minimums: IELTS 6.5 (no subscore <6.5) or TOEFL iBT 90 (no subscore <20). For exchange only, 2026-27 Fact Sheet (#page=3) also accepts DAAD B2 in each category; native speakers and English-medium university students are exempt. RHET 1020 waiver not stated."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('virginia-polytechnic-institute-and-state-university-virginia-tech', 'est_monthly_living_local', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=4', 'Derived by dividing VT 2026-2027 1-semester DS-2019 proof-of-funding living cost ($10,500 USD/sem; $21,000/AY) by 5 months = $2,100/month. Factsheet itemizes on-campus housing & food ~$7,000/sem (off-campus shared rent $500–$1,200/mo) and mandatory Aetna health insurance ~$2,000/sem.', '{"currency":"USD","max":2100,"min":2100}');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('virginia-polytechnic-institute-and-state-university-virginia-tech', 'exchange_page_url', 3, 'verified', 'official_web', 'https://www.globaleducation.vt.edu/students/visiting-exchange.html', NULL, '"https://www.globaleducation.vt.edu/students/visiting-exchange.html"');
