INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('virginia-polytechnic-institute-and-state-university-virginia-tech', 'fall_term_dates', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=2', NULL, '"2026-08-17 to 2026-12-16 (AY 2026-2027 Fall semester incl. required orientation and final exams; arrive by Aug 16, 2026)"');
