INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('virginia-polytechnic-institute-and-state-university-virginia-tech', 'host_language_requirement', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=3', NULL, '"English proficiency required unless native speaker or enrolled at an English-medium university."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('virginia-polytechnic-institute-and-state-university-virginia-tech', 'housing_availability', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=4', 'On-campus housing is NOT guaranteed for exchange students (may request during application; on-campus residents must purchase a meal plan; overflow lounge housing used in high-demand terms per Useful Info.docx). Off-campus shared rent ~$500–$1,200/mo.', '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('virginia-polytechnic-institute-and-state-university-virginia-tech', 'housing_notes', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=4', NULL, '"On-campus housing & standard meal plan ~$7,000/semester (not guaranteed); off-campus shared housing in Blacksburg $500–$1,200/month (VT does not arrange off-campus leases)."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('virginia-polytechnic-institute-and-state-university-virginia-tech', 'instruction_languages', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=3', NULL, '["English"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('virginia-polytechnic-institute-and-state-university-virginia-tech', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=1', 'Free ROA airport pickup confirmed in 24-25 VT Fact Sheet #page=4; Academic Advising & Writing Center on #page=2.', '"Global Education Office (GEO) pre-departure/J-1 advising, required week-long orientation, free airport pickup from Roanoke-Blacksburg Airport (ROA), Academic Advising, Writing Center, and Schiffert Health Center."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('virginia-polytechnic-institute-and-state-university-virginia-tech', 'living_cost_usd_est', 2, 'partial', 'fact_sheet', 'data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=4', 'Official 2026-2027 1-semester exchange DS-2019 living budget / proof of funding ($10,500.00 USD per semester; $21,000 USD full year), already in USD (recorded 2026-11-15).', '10500.0');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('virginia-polytechnic-institute-and-state-university-virginia-tech', 'mandatory_host_fees_and_insurance', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=4', 'Pamplin fee noted as ~$2,500 (2+ courses) on #page=2 and $1,275 on #page=4 ($1,275 for 7+ credits in alternate 2026-27 PDF copy); immunizations in 24-25 PDF #page=2.', '"Mandatory J-1 health insurance: VT Aetna plan (~$2,000/semester) or VT-approved comparable policy; VT Program Fee $75; visa/SEVIS ~$400. Note: Pamplin College of Business supplemental fee applies if taking 2+ business courses (~$1,275–$2,500/sem across 2026-27 factsheet variants). Required immunizations post-acceptance."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('virginia-polytechnic-institute-and-state-university-virginia-tech', 'min_gpa_host', 1, 'unknown', 'unknown', NULL, NULL, NULL);
