INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('virginia-polytechnic-institute-and-state-university-virginia-tech', 'nomination_deadlines', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=1', NULL, '"Fall Semester & Academic Year: nomination March 1, application April 1. Spring Semester: nomination September 1, application October 1."');
