INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('virginia-polytechnic-institute-and-state-university-virginia-tech', 'visa_lead_time_and_financial_proof', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/Virginia Tech/2026-2027/Virginia Tech Inbound Exchange Fact Sheet 2026-27.pdf#page=4', NULL, '"J-1 visa (Form DS-2019) required unless US citizen/LPR; passport must be valid >=6 months past program end (`#page=3`). Must document $10,500 USD per semester or $21,000 USD per academic year in personal or family/private sponsor liquid funds (`#page=4`)."');
