INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('west-virginia-university', 'housing_availability', 2, 'verified', 'fact_sheet', 'data/raw/factsheets/West Virginia/2025-2026/WVU 202526 Fact sheet.pdf#page=2', 'Global Live-Learn Community at Stalnaker Hall (covered by WVU Exchange Housing Waiver if included in partner agreement); students >=24 are ineligible for residence halls (University Apartments recommended for >19). Note WVU housing/dining close during breaks (Thanksgiving/Winter/Spring) — Fact sheet p.1.', '"assisted"');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('west-virginia-university', 'housing_notes', 2, 'verified', 'official_web', 'https://housing.wvu.edu/residence-halls/room-and-dining-plan-rates', 'WVU 2025-26 Fact Sheet (data/raw/factsheets/West Virginia/2025-2026/WVU 202526 Fact sheet.pdf#page=1, #page=2) also specifies Global LLC at Stalnaker Hall (housing waiver if included in agreement), >=24 residence hall age cap, and hall/dining closures during breaks.', '"Morgantown residence hall rates per semester: Traditional towers double ~$3,682, single ~$4,628; Stalnaker/Summit double suite ~$4,038-$4,133, single ~$4,759-$4,863; Honors/Lincoln double ~$4,660-$4,729, single ~$4,863-$4,936; Seneca studios $5,718-$6,248; $225 deposit and required dining plan."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('west-virginia-university', 'instruction_languages', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/West Virginia/2025-2026/WVU 202526 Fact sheet.pdf#page=2', NULL, '["English"]');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('west-virginia-university', 'international_support_services', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/West Virginia/2025-2026/WVU 202526 Fact sheet.pdf#page=1', 'ISSS/Accessibility/Emergency contact on data/raw/factsheets/West Virginia/2025-2026/WVU 202526 Fact sheet.pdf#page=2.', '"Education Abroad (incomingexchange@mail.wvu.edu), International Students & Scholars Services (ISSS, https://isss.wvu.edu/), mandatory New International Student Orientation, scheduled shuttle pickups from Pittsburgh International Airport, Stalnaker Hall Global LLC, and Accessibility Services."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('west-virginia-university', 'living_cost_usd_est', 2, 'partial', 'official_web', 'https://admissions.wvu.edu/cost-and-aid', '1 USD = 1.0 USD on 2026-11-15 (native USD); 5-month semester equivalent of WVU 2026-27 average Food & Housing COA ($15,028/yr / 2 = $7,514.00/semester), excluding $150 admin fee and health insurance.', '7514.0');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('west-virginia-university', 'mandatory_host_fees_and_insurance', 2, 'verified', 'official_web', 'https://studentinsurance.wvu.edu/', 'J-1 insurance criteria at https://isss.wvu.edu/students-services/health-insurance-in-the-u-s; $150 administration fee at data/raw/factsheets/West Virginia/2025-2026/WVU 202526 Fact sheet.pdf#page=1.', '"WVU 2026-27 Aetna Student Health Insurance Plan (SHIP) premiums: $1,277 Fall, $1,980 Spring/Summer ($3,257 annual). J-1 exchange visitors must meet 22 CFR 62.14 insurance minimums ($100k medical, $25k repatriation, $50k evacuation, <=$500 deductible). WVU also charges a $150 USD exchange administration fee."');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('west-virginia-university', 'min_gpa_host', 1, 'verified', 'fact_sheet', 'data/raw/factsheets/West Virginia/2025-2026/WVU 202526 Fact sheet.pdf#page=2', 'Fact sheet p.2 states: ''MINIMUM GPA: 2.5/4.0. Students with a GPA of 2.0-2.49 may be considered on an individual basis. Course request list required for review.''', '2.5');
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('west-virginia-university', 'min_standing_note', 1, 'unknown', 'unknown', NULL, 'Residence halls exclude students >=24 years old; College of Law exchange requires a completed bachelor''s degree (p.2).', NULL);
INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('west-virginia-university', 'nomination_deadlines', 4, 'verified', 'fact_sheet', 'data/raw/factsheets/West Virginia/2025-2026/WVU 202526 Fact sheet.pdf#page=1', '6-month advance rule for health/law programs on p.2.', '"Fall (Aug-Dec): Nomination Mar 15, Application Apr 1. Spring (Jan-May): Nomination Sep 1, Application Sep 15 (late apps case-by-case; Medicine/Nursing/Law/Dentistry >=6 months advance)."');
