INSERT OR REPLACE INTO university_provenance (university_slug, field_name, tier, status, source_type, source_ref, notes, value_json) VALUES ('west-virginia-university', 'visa_lead_time_and_financial_proof', 2, 'verified', 'official_web', 'https://isss.wvu.edu/students-services/j-1-students', 'Financial documentation rules ($9,700/dependent) at https://isss.wvu.edu/students-services/new-student-on-boarding; Fact Sheet (data/raw/factsheets/West Virginia/2025-2026/WVU 202526 Fact sheet.pdf#page=2) also lists .../students/j-1-students.', '"J-1 Visa requires Form DS-2019 from WVU ISSS supported by Proof of Financial Support (liquid bank statements <=6 months old or sponsor/award letters covering COA; add $9,700 per J-2 dependent) and 22 CFR 62.14 compliant health insurance."');
